                RIS_REG[1] <= 1'b0;
            else if (matchx_flag)
                RIS_REG[1] <= 1'b1;

            if (IC_REG[2])
                RIS_REG[2] <= 1'b0;
            else if (matchy_flag)
                RIS_REG[2] <= 1'b1;
