                        sample_count <= sample_count + 1'b1;
                end
                STOP1: if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        sample_count <= 0;
                        frame_error_reg <= !rx;
                        state <= IDLE;
                        rx_done <= 1'b1;
                    end else
                        sample_count <= sample_count + 1'b1;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

