module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick, input wire [3:0] data_size,
    input wire stop_bits_count, input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done, output wire tx
);
    localparam IDLE=0, START=1, DATA=2, PARITY=3, STOP0=4, STOP1=5;
    reg [2:0] state;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data;
    reg parity_bit;
    reg tx_reg;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data <= 0;
            parity_bit <= 0;
            tx_reg <= 1'b1;
            tx_done <= 1'b0;
        end else begin
            tx_done <= 1'b0;
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    if (tx_start) begin
                        data <= d_in;
                        case (parity_type)
                            3'b001: parity_bit <= ~^d_in;
                            3'b010: parity_bit <= ^d_in;
                            3'b100: parity_bit <= 1'b0;
                            3'b101: parity_bit <= 1'b1;
                            default: parity_bit <= 1'b0;
                        endcase
                        tx_reg <= 1'b0;
                        state <= START;
                    end
                end
                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                DATA: begin
                    tx_reg <= data[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data <= data >> 1;
                            if (bit_count == data_size-1) begin
                                state <= (parity_type == 0) ? STOP0 : PARITY;
                            end else bit_count <= bit_count + 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                PARITY: begin
                    tx_reg <= parity_bit;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count) state <= STOP1;
                            else begin
                                state <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            tx_done <= 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
