module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire tx_start, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                 PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [MDW-1:0] data_reg;
    reg [3:0] bit_count;
    integer sample_count;
    reg tx_reg;
    reg [MDW-1:0] parity_data;
    reg parity_bit;

    always @* begin
        parity_data = data_reg;
        case (parity_type)
            3'b001: parity_bit = ~^parity_data;
            3'b010: parity_bit = ^parity_data;
            3'b100: parity_bit = 1'b0;
            3'b101: parity_bit = 1'b1;
            default: parity_bit = 1'b0;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            data_reg <= '0;
            bit_count <= 0;
            sample_count <= 0;
            tx_reg <= 1'b1;
            tx_done <= 1'b0;
        end else begin
            tx_done <= 1'b0;
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        data_reg <= d_in;
                        bit_count <= 0;
                        sample_count <= 0;
                        state <= START;
                        tx_reg <= 1'b0;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[bit_count];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                PARITY: begin
                    tx_reg <= parity_bit;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            tx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                 PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [MDW-1:0] data_reg;
    reg [3:0] bit_count;
    integer sample_count;
    reg parity_bad, frame_bad;
    reg [11:0] break_shift;
    reg [MDW-1:0] completed_data;

    wire expected_parity =
        (parity_type == 3'b001) ? ~^data_reg :
        (parity_type == 3'b010) ? ^data_reg :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            data_reg <= '0;
            completed_data <= '0;
            bit_count <= 0;
            sample_count <= 0;
            parity_bad <= 1'b0;
            frame_bad <= 1'b0;
            break_shift <= 12'hfff;
            rx_done <= 1'b0;
        end else begin
            rx_done <= 1'b0;

            if (b_tick && (sample_count == NUM_SAMPLES-1)) begin
                if (state == IDLE)
                    break_shift <= 12'hfff;
                else
                    break_shift <= {break_shift[10:0],rx};
            end

            case (state)
                IDLE: begin
                    sample_count <= 0;
                    if (b_tick && !rx) begin
                        state <= START;
                        sample_count <= 0;
                        parity_bad <= 1'b0;
                        frame_bad <= 1'b0;
                    end
                end

                START: begin
                    if (b_tick) begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                DATA: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg[bit_count] <= rx;
                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                PARITY: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (parity_type != 3'b100 &&
                                parity_type != 3'b101 &&
                                (rx != expected_parity))
                                parity_bad <= 1'b1;
                            else if ((parity_type == 3'b100 && rx != 1'b0) ||
                                     (parity_type == 3'b101 && rx != 1'b1))
                                parity_bad <= 1'b1;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                STOP0: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (!rx)
                                frame_bad <= 1'b1;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                completed_data <= data_reg;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                STOP1: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            if (!rx)
                                frame_bad <= 1'b1;
                            completed_data <= data_reg;
                            rx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign dout = completed_data;
    assign parity_error = parity_bad && rx_done;
    assign frame_error = frame_bad && rx_done;
    assign match_flag = (completed_data == match_data) && rx_done;
    assign break_flag = (break_shift == 12'd0);
endmodule

module EF_UART #(
    parameter MDW=9, FAW=4, SC=8, GFLEN=8
) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr, input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en, input wire glitch_filter_en,
    input wire tx_fifo_flush, input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire baudtick;
    wire rx_sync, rx_filtered, rx_in;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;

    ef_util_sync rx_synchronizer (.clk(clk),.in(rx),.out(rx_sync));
    ef_util_glitch_filter #(.N(GFLEN)) filter (
        .clk(clk),.rst_n(rst_n),.in(rx_sync),
        .en(glitch_filter_en),.out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud (
        .clk(clk),.rst_n(rst_n),.prescale(prescaler),
        .en(en),.baudtick(baudtick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(tx_done),.wr(wr),
        .flush(tx_fifo_flush),.wdata(wdata),
        .empty(tx_empty),.full(tx_full),.rdata(tx_data),
        .level(tx_level)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) rx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(rd),.wr(rx_done),
        .flush(rx_fifo_flush),.wdata(rx_data),
        .empty(rx_empty),.full(rx_full),.rdata(rdata),
        .level(rx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC),.MDW(MDW)) transmitter (
        .clk(clk),.resetn(rst_n),.tx_start(!tx_empty),
        .b_tick(baudtick && tx_en),.data_size(data_size),
        .stop_bits_count(stop_bits_count),.parity_type(parity_type),
        .d_in(tx_data),.tx_done(tx_done),.tx(tx)
    );

    UART_RX #(.NUM_SAMPLES(SC),.MDW(MDW)) receiver (
        .clk(clk),.resetn(rst_n),.b_tick(baudtick && rx_en),
        .data_size(data_size),.stop_bits_count(stop_bits_count),
        .parity_type(parity_type),.rx(rx_in),.match_data(match_data),
        .rx_done(rx_done),.parity_error(parity_error_flag),
        .frame_error(frame_error_flag),.break_flag(break_flag),
        .match_flag(match_flag),.dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [4:0] timeout_sample_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            timeout_sample_count <= 0;
        end else if (baudtick && rx_en) begin
            if (rx_done) begin
                timeout_count <= 0;
                timeout_sample_count <= 0;
            end else if (timeout_sample_count == SC-1) begin
                timeout_sample_count <= 0;
                if (timeout_count == timeout_bits)
                    timeout_count <= 0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else
                timeout_sample_count <= timeout_sample_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_full && rx_done;
    assign timeout_flag = (timeout_count == timeout_bits);
