    wire read_ok  = rd && !empty_reg;

    always @(posedge clk) begin
        if (write_ok)
            mem[wptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr <= '0;
            wptr <= '0;
            level_reg <= '0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
