                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (parity_type != 3'b100 &&
                                parity_type != 3'b101 &&
                                (rx != expected_parity))
                                parity_bad <= 1'b1;
                            else if ((parity_type == 3'b100 && rx != 1'b0) ||
                                     (parity_type == 3'b101 && rx != 1'b1))
                                parity_bad <= 1'b1;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                STOP0: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (!rx)
                                frame_bad <= 1'b1;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                completed_data <= data_reg;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1;
                    end
                end

                STOP1: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            if (!rx)
                                frame_bad <= 1'b1;
                            completed_data <= data_reg;
                            rx_done <= 1'b1;
