        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 10'b0;

            if (write && PADDR[15:0] == PR)
                pr_reg <= PWDATA[15:0];
            if (write && PADDR[15:0] == CTRL)
                ctrl_reg <= PWDATA[4:0];
            if (write && PADDR[15:0] == CFG)
                cfg_reg <= PWDATA[13:0];
            if (write && PADDR[15:0] == MATCH)
                match_reg <= PWDATA[MDW-1:0];
            if (write && PADDR[15:0] == RX_THRESHOLD)
                rx_threshold_reg <= PWDATA[FAW-1:0];
            if (write && PADDR[15:0] == TX_THRESHOLD)
                tx_threshold_reg <= PWDATA[FAW-1:0];
            if (write && PADDR[15:0] == RX_FLUSH)
                rx_flush_reg <= PWDATA[0];
            if (write && PADDR[15:0] == TX_FLUSH)
                tx_flush_reg <= PWDATA[0];
            if (write && PADDR[15:0] == GCLK)
                gclk_reg <= PWDATA[0];
            if (write && PADDR[15:0] == IM)
                im_reg <= PWDATA[9:0];
            if (write && PADDR[15:0] == IC)
                ic_reg <= PWDATA[9:0];
        end
    end

    wire [9:0] interrupt_conditions = {
        timeout_flag, overrun_flag, parity_error_flag,
        frame_error_flag, match_flag, break_flag,
        rx_level_above, tx_level_below, rx_full, tx_empty
    };

    integer i;
    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else begin
            for (i=0; i<10; i=i+1) begin
                if (ic_reg[i])
                    ris_reg[i] <= 1'b0;
                else if (interrupt_conditions[i])
                    ris_reg[i] <= 1'b1;
            end
        end
    end

    EF_UART #(.SC(SC),.MDW(MDW),.GFLEN(GFLEN),.FAW(FAW)) uart (
        .clk(clk),.rst_n(PRESETn),.prescaler(pr_reg),
        .en(ctrl_reg[0]),.tx_en(ctrl_reg[1]),.rx_en(ctrl_reg[2]),
        .rd(rd_rx),.wr(wr_tx),.wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),.stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),.txfifotr(tx_threshold_reg),
        .rxfifotr(rx_threshold_reg),.match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]),.loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg),.rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),.tx_full(tx_full),.tx_level(tx_level),
        .tx_level_below(tx_level_below),.rdata(rdata),
        .rx_empty(rx_empty),.rx_full(rx_full),.rx_level(rx_level),
        .rx_level_above(rx_level_above),.break_flag(break_flag),
        .match_flag(match_flag),.frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),.timeout_flag(timeout_flag),
        .rx(rx),.tx(tx)
    );

    assign PRDATA =
        (PADDR[15:0] == RXDATA)       ? {{(32-MDW){1'b0}},rdata} :
        (PADDR[15:0] == PR)           ? {{16{1'b0}},pr_reg} :
        (PADDR[15:0] == CTRL)         ? {{27{1'b0}},ctrl_reg} :
        (PADDR[15:0] == CFG)          ? {{18{1'b0}},cfg_reg} :
        (PADDR[15:0] == MATCH)        ? {{(32-MDW){1'b0}},match_reg} :
        (PADDR[15:0] == RX_LEVEL)     ? {{(32-FAW){1'b0}},rx_level} :
        (PADDR[15:0] == RX_THRESHOLD) ? {{(32-FAW){1'b0}},rx_threshold_reg} :
        (PADDR[15:0] == RX_FLUSH)     ? {{31{1'b0}},rx_flush_reg} :
        (PADDR[15:0] == TX_LEVEL)     ? {{(32-FAW){1'b0}},tx_level} :
        (PADDR[15:0] == TX_THRESHOLD) ? {{(32-FAW){1'b0}},tx_threshold_reg} :
        (PADDR[15:0] == TX_FLUSH)     ? {{31{1'b0}},tx_flush_reg} :
        (PADDR[15:0] == IM)           ? {{22{1'b0}},im_reg} :
        (PADDR[15:0] == MIS)          ? {{22{1'b0}},(ris_reg & im_reg)} :
        (PADDR[15:0] == RIS)          ? {{22{1'b0}},ris_reg} :
        (PADDR[15:0] == GCLK)         ? {{31{1'b0}},gclk_reg} :
        32'hdeadbeef;

    assign IRQ = |(ris_reg & im_reg);
    assign PREADY = 1'b1;
endmodule

