    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n)
        if(!rst_n)
            count_reg <= 0;
        else if(en)
            count_reg <= (count_reg == prescale) ? 0 : count_reg + 1'b1;

    assign baudtick = en && (count_reg == prescale);

