module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);

    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010,
               parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg p_error_reg, p_error_next, f_error_reg, f_error_next;
    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if(!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            if(current_state == idle_st) begin
                p_error_reg <= 0;
                f_error_reg <= 0;
            end else begin
                if(p_error_next) p_error_reg <= 1;
                if(f_error_next) f_error_reg <= 1;
            end
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        rx_done = 0;
        p_error_next = 0;
        f_error_next = 0;

        case(current_state)
            idle_st:
                if(!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end

            start_st:
                if(b_tick)
                    if(b_reg == NUM_SAMPLES/2-1) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;

            data_st:
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if(count_reg == data_size-1)
                            next_state = (parity_type == 0) ? stop0_st : parity_st;
                        else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;

            parity_st:
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case(parity_type)
                            3'b001: if((~^dout) != rx) p_error_next = 1;
                            3'b010: if((^dout) != rx) p_error_next = 1;
                            3'b100: if(rx) p_error_next = 1;
                            3'b101: if(!rx) p_error_next = 1;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;

            stop0_st:
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if(!rx) f_error_next = 1;
                        if(stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1;
                        end
                    end else
                        b_next = b_reg + 1'b1;

            stop1_st:
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1;
                        if(!rx) f_error_next = 1;
                    end else
                        b_next = b_reg + 1'b1;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if(!resetn)
            brk <= 12'hfff;
        else if(b_tick && b_reg == NUM_SAMPLES-1)
            if(current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
    end

    assign dout = data_reg >> (9-data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 0);
    assign match_flag = (match_data == dout) & rx_done;

endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);

    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010,
               parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg tx_reg, tx_next;
    wire [MDW-1:0] pdata = d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if(!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            tx_reg <= 1;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            tx_reg <= tx_next;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        tx_next = tx_reg;
        tx_done = 0;

        case(current_state)
            idle_st: begin
                tx_next = 1;
                if(tx_start) begin
                    next_state = start_st;
                    b_next = 0;
                    data_next = d_in;
                end
            end

            start_st: begin
                tx_next = 0;
                if(b_tick)
                    if(b_reg == NUM_SAMPLES) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
            end

            data_st: begin
                tx_next = data_reg[0];
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if(count_reg == data_size-1)
                            next_state = (parity_type == 0) ? stop0_st : parity_st;
                        else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end

            parity_st: begin
                case(parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 0;
                    3'b101: tx_next = 1;
                    default: tx_next = 0;
                endcase
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop0_st: begin
                tx_next = 1;
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if(stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop1_st: begin
                tx_next = 1;
                if(b_tick)
                    if(b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1;
                    end else
                        b_next = b_reg + 1'b1;
            end
        endcase
    end

    assign tx = tx_reg;

endmodule

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [0:0] rx,
    output wire [0:0] tx
);

    localparam RXDATA_REG_OFFSET = 16'h0000;
    localparam TXDATA_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET = 16'h0008;
    localparam CTRL_REG_OFFSET = 16'h000C;
    localparam CFG_REG_OFFSET = 16'h0010;
    localparam MATCH_REG_OFFSET = 16'h001C;
    localparam RX_FIFO_LEVEL_REG_OFFSET = 16'hFE00;
    localparam RX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE04;
    localparam RX_FIFO_FLUSH_REG_OFFSET = 16'hFE08;
    localparam TX_FIFO_LEVEL_REG_OFFSET = 16'hFE10;
    localparam TX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE14;
    localparam TX_FIFO_FLUSH_REG_OFFSET = 16'hFE18;
    localparam IM_REG_OFFSET = 16'hFF00;
    localparam MIS_REG_OFFSET = 16'hFF04;
    localparam RIS_REG_OFFSET = 16'hFF08;
    localparam IC_REG_OFFSET = 16'hFF0C;
    localparam GCLK_REG_OFFSET = 16'hFF10;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = PWRITE & apb_valid;
    wire apb_re = ~PWRITE & apb_valid;

    reg [15:0] PR_REG;
    reg [4:0] CTRL_REG;
    reg [13:0] CFG_REG;
    reg [MDW-1:0] MATCH_REG;
    reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
    reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
    reg RX_FIFO_FLUSH_REG;
    reg TX_FIFO_FLUSH_REG;
    reg GCLK_REG;
    reg [9:0] IM_REG, IC_REG, RIS_REG;

    wire [MDW-1:0] rdata;
    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag, parity_error_flag;
    wire overrun_flag, timeout_flag;
    wire tx_done_unused;
    wire rd, wr;

    wire [9:0] MIS_REG = RIS_REG & IM_REG;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) PR_REG <= 0;
        else if(apb_we && PADDR[15:0] == PR_REG_OFFSET)
            PR_REG <= PWDATA[15:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) CTRL_REG <= 0;
        else if(apb_we && PADDR[15:0] == CTRL_REG_OFFSET)
            CTRL_REG <= PWDATA[4:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) CFG_REG <= 14'h3F08;
        else if(apb_we && PADDR[15:0] == CFG_REG_OFFSET)
            CFG_REG <= PWDATA[13:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) MATCH_REG <= 0;
        else if(apb_we && PADDR[15:0] == MATCH_REG_OFFSET)
            MATCH_REG <= PWDATA[MDW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) RX_FIFO_THRESHOLD_REG <= 0;
        else if(apb_we && PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET)
            RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) TX_FIFO_THRESHOLD_REG <= 0;
        else if(apb_we && PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET)
            TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) RX_FIFO_FLUSH_REG <= 0;
        else if(apb_we && PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET)
            RX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            RX_FIFO_FLUSH_REG <= 0;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) TX_FIFO_FLUSH_REG <= 0;
        else if(apb_we && PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET)
            TX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            TX_FIFO_FLUSH_REG <= 0;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) GCLK_REG <= 0;
        else if(apb_we && PADDR[15:0] == GCLK_REG_OFFSET)
            GCLK_REG <= PWDATA[0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) IM_REG <= 0;
        else if(apb_we && PADDR[15:0] == IM_REG_OFFSET)
            IM_REG <= PWDATA[9:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) IC_REG <= 0;
        else if(apb_we && PADDR[15:0] == IC_REG_OFFSET)
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 0;

    wire [9:0] raw_irq = {
        timeout_flag, overrun_flag, parity_error_flag, frame_error_flag,
        match_flag, break_flag, rx_level_above, tx_level_below,
        rx_full, tx_empty
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if(!PRESETn)
            RIS_REG <= 0;
        else
            for(i=0; i<10; i=i+1)
                if(IC_REG[i])
                    RIS_REG[i] <= 0;
                else if(raw_irq[i])
                    RIS_REG[i] <= 1;
    end

    EF_UART #(
        .SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)
    ) instance_to_wrap (
        .clk(PCLK),
        .rst_n(PRESETn),
        .prescaler(PR_REG),
        .en(CTRL_REG[0]),
        .tx_en(CTRL_REG[1]),
        .rx_en(CTRL_REG[2]),
        .rd(rd),
        .wr(wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(CFG_REG[3:0]),
        .stop_bits_count(CFG_REG[4]),
        .parity_type(CFG_REG[7:5]),
        .txfifotr(TX_FIFO_THRESHOLD_REG[3:0]),
        .rxfifotr(RX_FIFO_THRESHOLD_REG[3:0]),
        .match_data(MATCH_REG),
        .timeout_bits(CFG_REG[13:8]),
        .loopback_en(CTRL_REG[3]),
        .glitch_filter_en(CTRL_REG[4]),
        .tx_fifo_flush(TX_FIFO_FLUSH_REG),
        .rx_fifo_flush(RX_FIFO_FLUSH_REG),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign rd = apb_re && (PADDR[15:0] == RXDATA_REG_OFFSET);

    // TXDATA writes push one entry into the TX FIFO.
    assign wr = apb_we && (PADDR[15:0] == TXDATA_REG_OFFSET);

    assign PRDATA =
        (PADDR[15:0] == RXDATA_REG_OFFSET) ? {{(32-MDW){1'b0}}, rdata} :
        (PADDR[15:0] == PR_REG_OFFSET) ? {{16{1'b0}}, PR_REG} :
        (PADDR[15:0] == CTRL_REG_OFFSET) ? {{27{1'b0}}, CTRL_REG} :
        (PADDR[15:0] == CFG_REG_OFFSET) ? {{18{1'b0}}, CFG_REG} :
        (PADDR[15:0] == MATCH_REG_OFFSET) ? {{(32-MDW){1'b0}}, MATCH_REG} :
        (PADDR[15:0] == RX_FIFO_LEVEL_REG_OFFSET) ? {{(32-FAW){1'b0}}, rx_level} :
        (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET) ? {{(32-FAW){1'b0}}, RX_FIFO_THRESHOLD_REG} :
        (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET) ? {{31{1'b0}}, RX_FIFO_FLUSH_REG} :
        (PADDR[15:0] == TX_FIFO_LEVEL_REG_OFFSET) ? {{(32-FAW){1'b0}}, tx_level} :
        (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET) ? {{(32-FAW){1'b0}}, TX_FIFO_THRESHOLD_REG} :
        (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET) ? {{31{1'b0}}, TX_FIFO_FLUSH_REG} :
        (PADDR[15:0] == IM_REG_OFFSET) ? {{22{1'b0}}, IM_REG} :
        (PADDR[15:0] == MIS_REG_OFFSET) ? {{22{1'b0}}, MIS_REG} :
        (PADDR[15:0] == RIS_REG_OFFSET) ? {{22{1'b0}}, RIS_REG} :
        (PADDR[15:0] == GCLK_REG_OFFSET) ? {{31{1'b0}}, GCLK_REG} :
        32'hDEADBEEF;

    assign PREADY = 1'b1;
    assign IRQ = |MIS_REG;

endmodule

