    end

    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .tmr_en(tmr_en),
        .tmr_start(tmr_start),
        .pwm0_en(pwm0_en),
        .pwm1_en(pwm1_en),
