        .prescaler(prescaler),
        .tmr_cfg(tmr_cfg),
        .pwm0_cfg(pwm0_cfg),
        .pwm1_cfg(pwm1_cfg[11:0]),
        .pwm0_inv(pwm0_inv),
        .pwm1_inv(pwm1_inv),
        .pwm_dt(pwm_dt),
        .pwm_fault_clr(pwm_fault_clr),
        .pwm_dt_en(pwm_dt_en),
        .tmr(tmr),
        .matchx_flag(matchx_flag),
        .matchy_flag(matchy_flag),
        .timeout_flag(timeout_flag),
        .pwm0(pwm0),
        .pwm1(pwm1),
        .pwm_fault(pwm_fault)
