    ef_util_gating_cell gate (
        .clk(PCLK), .rst_n(PRESETn), .clk_en(gclk_reg),
        .clk_o(clk_g)
    );

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_thresh_reg, tx_thresh_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [9:0] mis = ris_reg & im_reg;
    wire [MDW-1:0] rdata;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire [FAW-1:0] tx_level, rx_level;
    wire tx_below, rx_above;
    wire brk, match, fe, pre, overrun, timeout;
    wire rx_rd = apb_re && (addr == RXDATA);
    wire tx_wr = apb_we && (addr == TXDATA);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_thresh_reg <= 0;
            tx_thresh_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
        end else begin
            if (apb_we && addr == PR) pr_reg <= PWDATA[15:0];
            if (apb_we && addr == CTRL) ctrl_reg <= PWDATA[4:0];
            if (apb_we && addr == CFG) cfg_reg <= PWDATA[13:0];
            if (apb_we && addr == MATCH) match_reg <= PWDATA[MDW-1:0];
            if (apb_we && addr == RX_THRESH) rx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == TX_THRESH) tx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == RX_FLUSH) rx_flush_reg <= PWDATA[0];
            else rx_flush_reg <= 1'b0;
            if (apb_we && addr == TX_FLUSH) tx_flush_reg <= PWDATA[0];
            else tx_flush_reg <= 1'b0;
            if (apb_we && addr == GCLK) gclk_reg <= PWDATA[0];
            if (apb_we && addr == IM) im_reg <= PWDATA[9:0];
            if (apb_we && addr == IC) ic_reg <= PWDATA[9:0];
            else ic_reg <= 10'b0;
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else begin
            if (ic_reg[0]) ris_reg[0] <= 1'b0; else if (tx_empty) ris_reg[0] <= 1'b1;
            if (ic_reg[1]) ris_reg[1] <= 1'b0; else if (rx_full)  ris_reg[1] <= 1'b1;
            if (ic_reg[2]) ris_reg[2] <= 1'b0; else if (tx_below) ris_reg[2] <= 1'b1;
            if (ic_reg[3]) ris_reg[3] <= 1'b0; else if (rx_above) ris_reg[3] <= 1'b1;
            if (ic_reg[4]) ris_reg[4] <= 1'b0; else if (brk)      ris_reg[4] <= 1'b1;
            if (ic_reg[5]) ris_reg[5] <= 1'b0; else if (match)    ris_reg[5] <= 1'b1;
            if (ic_reg[6]) ris_reg[6] <= 1'b0; else if (fe)       ris_reg[6] <= 1'b1;
            if (ic_reg[7]) ris_reg[7] <= 1'b0; else if (pre)      ris_reg[7] <= 1'b1;
            if (ic_reg[8]) ris_reg[8] <= 1'b0; else if (overrun)  ris_reg[8] <= 1'b1;
            if (ic_reg[9]) ris_reg[9] <= 1'b0; else if (timeout)  ris_reg[9] <= 1'b1;
        end
    end

    EF_UART #(.SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)) core (
        .clk(clk_g), .rst_n(PRESETn), .prescaler(pr_reg),
        .en(ctrl_reg[0]), .tx_en(ctrl_reg[1]), .rx_en(ctrl_reg[2]),
        .rd(rx_rd), .wr(tx_wr), .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]), .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]), .txfifotr(tx_thresh_reg),
        .rxfifotr(rx_thresh_reg), .match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]), .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]), .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg), .tx_empty(tx_empty),
        .tx_full(tx_full), .tx_level(tx_level),
        .tx_level_below(tx_below), .rdata(rdata),
        .rx_empty(rx_empty), .rx_full(rx_full),
        .rx_level(rx_level), .rx_level_above(rx_above),
        .break_flag(brk), .match_flag(match), .frame_error_flag(fe),
        .parity_error_flag(pre), .overrun_flag(overrun),
        .timeout_flag(timeout), .rx(rx), .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA)     ? {{(32-MDW){1'b0}}, rdata} :
        (addr == PR)         ? {{16{1'b0}}, pr_reg} :
        (addr == CTRL)       ? {{27{1'b0}}, ctrl_reg} :
        (addr == CFG)        ? {{18{1'b0}}, cfg_reg} :
        (addr == MATCH)      ? {{(32-MDW){1'b0}}, match_reg} :
        (addr == RX_LEVEL)   ? {{(32-FAW){1'b0}}, rx_level} :
        (addr == RX_THRESH)  ? {{(32-FAW){1'b0}}, rx_thresh_reg} :
        (addr == RX_FLUSH)   ? {{31{1'b0}}, rx_flush_reg} :
        (addr == TX_LEVEL)   ? {{(32-FAW){1'b0}}, tx_level} :
        (addr == TX_THRESH)  ? {{(32-FAW){1'b0}}, tx_thresh_reg} :
        (addr == TX_FLUSH)   ? {{31{1'b0}}, tx_flush_reg} :
        (addr == IM)         ? {{22{1'b0}}, im_reg} :
        (addr == MIS)        ? {{22{1'b0}}, mis} :
        (addr == RIS)        ? {{22{1'b0}}, ris_reg} :
        (addr == GCLK)       ? {{31{1'b0}}, gclk_reg} :
                               32'hdeadbeef;

    assign IRQ = |mis;
    assign PREADY = 1'b1;
endmodule

