module ef_util_ticker #(parameter W = 8) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [W-1:0] clk_div,
    output wire         tick
);
    reg [W-1:0] counter;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            counter <= 'b0;
        else if (en) begin
            if (counter == 'b0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end
    end
    assign tick = en && ((clk_div == 'b0) || (counter == 'b0));
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input  wire clk,
    input  wire rst_n,
    input  wire in,
    input  wire en,
    output reg  out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out     <= 1'b0;
        end else if (tick) begin
