    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;

    reg [15:0] PR_REG;
    reg [4:0] CTRL_REG;
    reg [13:0] CFG_REG;
    reg [MDW-1:0] MATCH_REG;
    reg [FAW-1:0] RX_THRESHOLD_REG;
    reg [FAW-1:0] TX_THRESHOLD_REG;
    reg RX_FLUSH_REG, TX_FLUSH_REG;
    reg GCLK_REG;
