    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            TX_FLUSH_REG <= 1'b0;
        else if (apb_we && PADDR[15:0] == TX_FLUSH_OFFSET)
            TX_FLUSH_REG <= PWDATA[0];
        else
            TX_FLUSH_REG <= 1'b0;
