        if (!PRESETn)
            IC_REG <= 10'b0;
        else if (apb_we && PADDR[15:0] == IC_OFFSET)
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 10'b0;
    end

    wire [9:0] raw_events = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
