module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input  wire clk,
    input  wire rst_n,
    input  wire in,
    input  wire en,
    output reg  out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out     <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&shifter)
                out <= 1'b1;
            else if (~|shifter)
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW = 8, AW = 4) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         rd,
    input  wire         wr,
    input  wire         flush,
    input  wire [DW-1:0] wdata,
    output wire         empty,
    output wire         full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr, rptr;
    reg [AW-1:0] level_reg;
    reg empty_reg, full_reg;

    wire write_accept = wr && !full_reg;
    wire read_accept  = rd && !empty_reg;

    assign rdata = mem[rptr];
    assign empty = empty_reg;
    assign full  = full_reg;
    assign level = level_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr      <= 'b0;
            rptr      <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg  <= 1'b0;
        end else if (flush) begin
            wptr      <= 'b0;
            rptr      <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg  <= 1'b0;
        end else begin
            if (write_accept)
                mem[wptr] <= wdata;

            case ({write_accept, read_accept})
                2'b10: begin
                    wptr      <= wptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((wptr + 1'b1) == rptr)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    rptr      <= rptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg  <= 1'b0;
                    if ((rptr + 1'b1) == wptr)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    wptr <= wptr + 1'b1;
                    rptr <= rptr + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end
endmodule

