        if (!rst_n)
            count_reg <= 16'b0;
        else if (en) begin
            if (count_reg == prescale)
                count_reg <= 16'b0;
            else
                count_reg <= count_reg + 1'b1;
        end
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input  wire         clk,
    input  wire         resetn,
    input  wire         tx_start,
    input  wire         b_tick,
    input  wire [3:0]   data_size,
    input  wire         stop_bits_count,
    input  wire [2:0]   parity_type,
    input  wire [MDW-1:0] d_in,
    output reg          tx_done,
    output wire         tx
);
    localparam IDLE   = 3'd0;
    localparam START  = 3'd1;
    localparam DATA   = 3'd2;
    localparam PARITY = 3'd3;
    localparam STOP0  = 3'd4;
    localparam STOP1  = 3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire [MDW-1:0] parity_data =
        d_in & ~({MDW{1'b1}} << data_size);

    assign tx = tx_reg;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= IDLE;
            sample_count <= 0;
            bit_count    <= 0;
            data_reg     <= 0;
            tx_reg       <= 1'b1;
        end else begin
            tx_done <= 1'b0;

            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        state        <= START;
                        sample_count <= 0;
                        bit_count    <= 0;
                        data_reg     <= d_in;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            state        <= DATA;
                            sample_count <= 0;
                            bit_count    <= 0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg     <= data_reg >> 1;
                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^parity_data;
                        3'b010: tx_reg <=  ^parity_data;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b0;
                    endcase

                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state   <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state   <= IDLE;
                            tx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input  wire         clk,
    input  wire         resetn,
    input  wire         b_tick,
    input  wire [3:0]   data_size,
    input  wire         stop_bits_count,
    input  wire [2:0]   parity_type,
    input  wire         rx,
    input  wire [MDW-1:0] match_data,
    output reg          rx_done,
    output wire         parity_error,
    output wire         frame_error,
    output wire         break_flag,
    output wire         match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE   = 3'd0;
    localparam START  = 3'd1;
    localparam DATA   = 3'd2;
    localparam PARITY = 3'd3;
    localparam STOP0  = 3'd4;
    localparam STOP1  = 3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_error_reg;
    reg frame_error_reg;
    reg [11:0] break_reg;

    assign dout = data_reg;
    assign parity_error = rx_done &&
                          (parity_error_reg || parity_error_next);
    assign frame_error = rx_done &&
                         (frame_error_reg || frame_error_next);
    assign match_flag = rx_done && (dout == match_data);
    assign break_flag = (break_reg == 12'b0);

    reg parity_error_next;
    reg frame_error_next;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state           <= IDLE;
            sample_count    <= 0;
            bit_count       <= 0;
            data_reg        <= 0;
            parity_error_reg <= 1'b0;
            frame_error_reg  <= 1'b0;
            break_reg        <= 12'hfff;
        end else begin
            rx_done          <= 1'b0;
            parity_error_next <= 1'b0;
            frame_error_next  <= 1'b0;

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    break_reg <= 12'hfff;
                else
                    break_reg <= {break_reg[10:0], rx};
            end

            case (state)
                IDLE: begin
                    parity_error_reg <= 1'b0;
                    frame_error_reg  <= 1'b0;
                    sample_count     <= 0;
                    if (b_tick && !rx) begin
                        state        <= START;
                        sample_count <= 0;
                    end
                end

                START: begin
                    if (b_tick) begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            state        <= DATA;
                            sample_count <= 0;
                            bit_count    <= 0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg <= {data_reg[MDW-2:0], rx};

                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;

                            case (parity_type)
                                3'b001:
                                    if ((~^dout) != rx)
                                        parity_error_next <= 1'b1;
                                3'b010:
                                    if ((^dout) != rx)
                                        parity_error_next <= 1'b1;
                                3'b100:
                                    if (rx != 1'b0)
                                        parity_error_next <= 1'b1;
                                3'b101:
                                    if (rx != 1'b1)
                                        parity_error_next <= 1'b1;
                                default:
                                    parity_error_next <= 1'b0;
                            endcase
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (!rx)
                                frame_error_next <= 1'b1;

                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state   <= IDLE;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state   <= IDLE;
                            rx_done <= 1'b1;
                            if (!rx)
                                frame_error_next <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase

            if (state != IDLE) begin
                if (parity_error_next)
                    parity_error_reg <= 1'b1;
                if (frame_error_next)
                    frame_error_reg <= 1'b1;
            end
        end
    end
endmodule

module EF_UART #(
    parameter MDW = 9,
    parameter FAW = 4,
    parameter SC = 8,
    parameter GFLEN = 8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire b_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_sync, rx_filtered, rx_input;

    ef_util_sync rx_synchronizer (
        .clk(clk), .in(rx), .out(rx_sync)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_sync),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_input = loopback_en ? tx :
                      glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baudgen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) transmitter (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(b_tick && tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) receiver (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(b_tick && rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .rx(rx_input),
        .match_data(match_data),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count    <= 0;
            samples_count <= 0;
        end else if (rx_done) begin
            bits_count    <= 0;
            samples_count <= 0;
        end else if (b_tick) begin
            if (samples_count == SC-1) begin
                samples_count <= 0;
                if (bits_count == timeout_bits)
                    bits_count <= 0;
                else
                    bits_count <= bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag   = rx_full && rx_done;
    assign timeout_flag   = (bits_count == timeout_bits);
endmodule

module EF_UART_APB #(
