    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PR_REG <= 16'b0;
        else if (apb_we && PADDR[15:0] == PR_OFFSET)
            PR_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CTRL_REG <= 5'b0;
        else if (apb_we && PADDR[15:0] == CTRL_OFFSET)
            CTRL_REG <= PWDATA[4:0];
