        (PADDR[15:0] == TX_THRESHOLD_OFFSET)  ? {{(32-FAW){1'b0}}, TX_THRESHOLD_REG} :
        (PADDR[15:0] == TX_FLUSH_OFFSET)       ? {{31{1'b0}}, TX_FLUSH_REG} :
