    output wire             match_flag,
    output wire [MDW-1:0]   dout
);
    localparam idle_st   = 3'b000;
    localparam start_st  = 3'b001;
    localparam data_st   = 3'b010;
    localparam parity_st = 3'b011;
    localparam stop0_st  = 3'b100;
    localparam stop1_st  = 3'b101;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg p_error_reg, next_p_error;
    reg f_error_reg, next_f_error;
    reg [11:0] brk;

    wire [MDW-1:0] masked_data =
        data_reg >> (MDW - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= idle_st;
            sample_count <= 16'd0;
            bit_count    <= 4'd0;
            data_reg     <= 'b0;
            p_error_reg  <= 1'b0;
            f_error_reg  <= 1'b0;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;

            if (state == idle_st)
                p_error_reg <= 1'b0;
            else if (next_p_error)
                p_error_reg <= 1'b1;

            if (state == idle_st)
                f_error_reg <= 1'b0;
            else if (next_f_error)
                f_error_reg <= 1'b1;
        end
