    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_p_error      = 1'b0;
        next_f_error      = 1'b0;
        rx_done           = 1'b0;

        case (state)
            idle_st: begin
                if (b_tick && !rx) begin
                    next_state        = start_st;
                    next_sample_count = 16'd0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_sample_count = 16'd0;
                        if (rx) begin
                            next_state = idle_st;
                        end else begin
                            next_state     = data_st;
                            next_bit_count = 4'd0;
                        end
                    end else begin
                        next_sample_count = sample_count + 1'b1;
                    end
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg     = {rx, data_reg[MDW-1:1]};

                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else begin
                        next_sample_count = sample_count + 1'b1;
                    end
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state        = stop0_st;

                        case (parity_type)
