            stop1_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state        = idle_st;
                        tx_done           = 1'b1;
                    end else begin
                        next_sample_count = sample_count + 1'b1;
                    end
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

