    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 : count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
