module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_err_reg, frame_err_reg;
    reg [11:0] break_shift;

    wire last_sample = sample_count == NUM_SAMPLES-1;
    wire last_bit = bit_count == data_size-1;
    wire [MDW-1:0] shifted_data = {rx, data_reg[MDW-1:1]};

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state          <= IDLE;
            sample_count   <= 0;
            bit_count      <= 0;
            data_reg       <= 0;
            parity_err_reg <= 0;
            frame_err_reg  <= 0;
            break_shift    <= 12'hfff;
        end else begin
            rx_done <= 1'b0;

            if (b_tick) begin
                case (state)
                    IDLE: begin
                        sample_count   <= 0;
                        parity_err_reg <= 0;
                        frame_err_reg  <= 0;
                        break_shift    <= 12'hfff;
                        if (!rx) begin
                            state        <= START;
                            sample_count <= 0;
                        end
                    end

                    START: begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            state        <= DATA;
                            sample_count <= 0;
                            bit_count    <= 0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    DATA: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg     <= shifted_data;
                            if (last_bit) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    PARITY: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            case (parity_type)
                                3'b001: parity_err_reg <= ((~^data_reg) != rx);
                                3'b010: parity_err_reg <= (( ^data_reg) != rx);
                                3'b100: parity_err_reg <= (1'b0 != rx);
                                3'b101: parity_err_reg <= (1'b1 != rx);
                                default: parity_err_reg <= 1'b0;
                            endcase
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    STOP0: begin
                        if (last_sample) begin
                            sample_count  <= 0;
                            frame_err_reg <= !rx;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state   <= IDLE;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    STOP1: begin
                        if (last_sample) begin
                            sample_count  <= 0;
                            frame_err_reg <= frame_err_reg | !rx;
                            state         <= IDLE;
                            rx_done       <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    default: state <= IDLE;
                endcase

                if (sample_count == NUM_SAMPLES-1) begin
                    if (state == IDLE)
                        break_shift <= 12'hfff;
                    else
                        break_shift <= {break_shift[10:0], rx};
                end
            end
        end
    end

    assign dout         = data_reg;
    assign parity_error = parity_err_reg && rx_done;
    assign frame_error  = frame_err_reg && rx_done;
    assign match_flag   = (data_reg == match_data) && rx_done;
    assign break_flag   = (break_shift == 12'd0);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire last_sample = sample_count == NUM_SAMPLES-1;
    wire last_bit = bit_count == data_size-1;
    wire [MDW-1:0] parity_data =
        d_in & ({MDW{1'b1}} >> (MDW-data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= IDLE;
            sample_count <= 0;
            bit_count    <= 0;
            data_reg     <= 0;
            tx_reg       <= 1'b1;
        end else begin
            tx_done <= 1'b0;

            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        state        <= START;
                        sample_count <= 0;
                        data_reg     <= d_in;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            state        <= DATA;
                            sample_count <= 0;
                            bit_count    <= 0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg     <= data_reg >> 1;
                            if (last_bit) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^parity_data;
                        3'b010: tx_reg <=  ^parity_data;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b1;
                    endcase

                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state   <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state         <= IDLE;
                            tx_done       <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC=8,
    parameter MDW=9,
    parameter GFLEN=8,
    parameter FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
