    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg, tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [MDW-1:0] rdata;
    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_below, rx_above;
    wire break_flag, match_flag, frame_error, parity_error;
    wire overrun, timeout_flag;
    wire tx_done_unused;

    wire rx_read = apb_re && (addr == RXDATA);
    wire tx_write = apb_we && (addr == TXDATA);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg           <= 16'd0;
            ctrl_reg         <= 5'd0;
            cfg_reg          <= 14'h3f08;
            match_reg        <= '0;
            rx_threshold_reg <= '0;
            tx_threshold_reg <= '0;
            rx_flush_reg     <= 1'b0;
            tx_flush_reg     <= 1'b0;
            gclk_reg         <= 1'b0;
            im_reg           <= 10'd0;
            ic_reg           <= 10'd0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg       <= 10'd0;

            if (apb_we && addr == PR)            pr_reg <= PWDATA[15:0];
            if (apb_we && addr == CTRL)          ctrl_reg <= PWDATA[4:0];
            if (apb_we && addr == CFG)           cfg_reg <= PWDATA[13:0];
            if (apb_we && addr == MATCH)         match_reg <= PWDATA[MDW-1:0];
            if (apb_we && addr == RX_THRESHOLD)  rx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == TX_THRESHOLD)  tx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == RX_FLUSH)      rx_flush_reg <= PWDATA[0];
            if (apb_we && addr == TX_FLUSH)      tx_flush_reg <= PWDATA[0];
            if (apb_we && addr == IM)            im_reg <= PWDATA[9:0];
            if (apb_we && addr == IC)            ic_reg <= PWDATA[9:0];
