module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_err_reg, frame_err_reg;
    reg [11:0] break_shift;

    wire last_sample = sample_count == NUM_SAMPLES-1;
    wire last_bit = bit_count == data_size-1;
    wire [MDW-1:0] shifted_data = {rx, data_reg[MDW-1:1]};

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state          <= IDLE;
            sample_count   <= 0;
            bit_count      <= 0;
            data_reg       <= 0;
            parity_err_reg <= 0;
            frame_err_reg  <= 0;
            break_shift    <= 12'hfff;
        end else begin
            rx_done <= 1'b0;

            if (b_tick) begin
                case (state)
                    IDLE: begin
                        sample_count   <= 0;
                        parity_err_reg <= 0;
                        frame_err_reg  <= 0;
                        break_shift    <= 12'hfff;
                        if (!rx) begin
                            state        <= START;
                            sample_count <= 0;
                        end
                    end

                    START: begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            state        <= DATA;
                            sample_count <= 0;
                            bit_count    <= 0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    DATA: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg     <= shifted_data;
                            if (last_bit) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    PARITY: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            case (parity_type)
                                3'b001: parity_err_reg <= ((~^data_reg) != rx);
                                3'b010: parity_err_reg <= (( ^data_reg) != rx);
                                3'b100: parity_err_reg <= (1'b0 != rx);
                                3'b101: parity_err_reg <= (1'b1 != rx);
                                default: parity_err_reg <= 1'b0;
                            endcase
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    STOP0: begin
                        if (last_sample) begin
                            sample_count  <= 0;
                            frame_err_reg <= !rx;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state   <= IDLE;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    STOP1: begin
                        if (last_sample) begin
                            sample_count  <= 0;
                            frame_err_reg <= frame_err_reg | !rx;
                            state         <= IDLE;
                            rx_done       <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    default: state <= IDLE;
                endcase

                if (sample_count == NUM_SAMPLES-1) begin
                    if (state == IDLE)
                        break_shift <= 12'hfff;
                    else
                        break_shift <= {break_shift[10:0], rx};
                end
            end
        end
    end

    assign dout         = data_reg;
    assign parity_error = parity_err_reg && rx_done;
    assign frame_error  = frame_err_reg && rx_done;
    assign match_flag   = (data_reg == match_data) && rx_done;
    assign break_flag   = (break_shift == 12'd0);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire last_sample = sample_count == NUM_SAMPLES-1;
    wire last_bit = bit_count == data_size-1;
    wire [MDW-1:0] parity_data =
        d_in & ({MDW{1'b1}} >> (MDW-data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= IDLE;
            sample_count <= 0;
            bit_count    <= 0;
            data_reg     <= 0;
            tx_reg       <= 1'b1;
        end else begin
            tx_done <= 1'b0;

            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        state        <= START;
                        sample_count <= 0;
                        data_reg     <= d_in;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            state        <= DATA;
                            sample_count <= 0;
                            bit_count    <= 0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg     <= data_reg >> 1;
                            if (last_bit) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^parity_data;
                        3'b010: tx_reg <=  ^parity_data;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b1;
                    endcase

                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state   <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state         <= IDLE;
                            tx_done       <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC=8,
    parameter MDW=9,
    parameter GFLEN=8,
    parameter FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA=16'h0000, TXDATA=16'h0004, PR=16'h0008,
               CTRL=16'h000c, CFG=16'h0010, MATCH=16'h001c,
               RX_LEVEL=16'hfe00, RX_THRESHOLD=16'hfe04,
               RX_FLUSH=16'hfe08, TX_LEVEL=16'hfe10,
               TX_THRESHOLD=16'hfe14, TX_FLUSH=16'hfe18,
               IM=16'hff00, MIS=16'hff04, RIS=16'hff08,
               IC=16'hff0c, GCLK=16'hff10;

    wire apb_we = PSEL && PENABLE && PWRITE;
    wire apb_re = PSEL && PENABLE && !PWRITE;
    wire [15:0] addr = PADDR[15:0];

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg, tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [MDW-1:0] rdata;
    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_below, rx_above;
    wire break_flag, match_flag, frame_error, parity_error;
    wire overrun, timeout_flag;
    wire tx_done_unused;

    wire rx_read = apb_re && (addr == RXDATA);
    wire tx_write = apb_we && (addr == TXDATA);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg           <= 16'd0;
            ctrl_reg         <= 5'd0;
            cfg_reg          <= 14'h3f08;
            match_reg        <= '0;
            rx_threshold_reg <= '0;
            tx_threshold_reg <= '0;
            rx_flush_reg     <= 1'b0;
            tx_flush_reg     <= 1'b0;
            gclk_reg         <= 1'b0;
            im_reg           <= 10'd0;
            ic_reg           <= 10'd0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg       <= 10'd0;

            if (apb_we && addr == PR)            pr_reg <= PWDATA[15:0];
            if (apb_we && addr == CTRL)          ctrl_reg <= PWDATA[4:0];
            if (apb_we && addr == CFG)           cfg_reg <= PWDATA[13:0];
            if (apb_we && addr == MATCH)         match_reg <= PWDATA[MDW-1:0];
            if (apb_we && addr == RX_THRESHOLD)  rx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == TX_THRESHOLD)  tx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == RX_FLUSH)      rx_flush_reg <= PWDATA[0];
            if (apb_we && addr == TX_FLUSH)      tx_flush_reg <= PWDATA[0];
            if (apb_we && addr == IM)            im_reg <= PWDATA[9:0];
            if (apb_we && addr == IC)            ic_reg <= PWDATA[9:0];
            if (apb_we && addr == GCLK)          gclk_reg <= PWDATA[0];
        end
    end

    wire [9:0] raw_status = {
        timeout_flag, overrun, parity_error, frame_error, match_flag,
        break_flag, rx_above, tx_below, rx_full, tx_empty
    };

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'd0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | raw_status;
    end

    EF_UART #(
        .SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)
    ) uart_core (
        .clk(PCLK),
        .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]),
        .rx_en(ctrl_reg[2]),
        .rd(rx_read),
        .wr(tx_write),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_threshold_reg),
        .rxfifotr(rx_threshold_reg),
        .match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error),
        .parity_error_flag(parity_error),
        .overrun_flag(overrun),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    always @* begin
        case (addr)
            RXDATA:       PRDATA = {{(32-MDW){1'b0}}, rdata};
            PR:           PRDATA = {16'd0, pr_reg};
            CTRL:         PRDATA = {27'd0, ctrl_reg};
            CFG:          PRDATA = {18'd0, cfg_reg};
            MATCH:        PRDATA = {{(32-MDW){1'b0}}, match_reg};
            RX_LEVEL:     PRDATA = {{(32-FAW){1'b0}}, rx_level};
            RX_THRESHOLD: PRDATA = {{(32-FAW){1'b0}}, rx_threshold_reg};
            RX_FLUSH:     PRDATA = {31'd0, rx_flush_reg};
            TX_LEVEL:     PRDATA = {{(32-FAW){1'b0}}, tx_level};
            TX_THRESHOLD: PRDATA = {{(32-FAW){1'b0}}, tx_threshold_reg};
            TX_FLUSH:     PRDATA = {31'd0, tx_flush_reg};
            IM:           PRDATA = {22'd0, im_reg};
            MIS:          PRDATA = {22'd0, (ris_reg & im_reg)};
            RIS:          PRDATA = {22'd0, ris_reg};
            GCLK:         PRDATA = {31'd0, gclk_reg};
            default:      PRDATA = 32'hdeadbeef;
        endcase
    end

    assign IRQ    = |(ris_reg & im_reg);
    assign PREADY = 1'b1;
endmodule

