      pwm0_out_reg <= pwm0_delayed & pwm0_state;
      pwm1_out_reg <= ~pwm0_delayed & ~pwm0_state;
    end
    else begin
      pwm0_out_reg <= pwm0_state;
      pwm1_out_reg <= pwm1_state;
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      fault_latched <= 1'b0;
      fault_armed   <= 1'b0;
    end
    else begin
      if (pwm_fault_clr == PWM_FAULT_CLR_C0)
        fault_armed <= 1'b1;
      else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
        fault_armed <= 1'b0;

      if (pwm_fault)
        fault_latched <= 1'b1;
      else if (fault_armed &&
               (pwm_fault_clr == PWM_FAULT_CLR_C1))
        fault_latched <= 1'b0;
    end
  end

