module ef_util_ticker #(parameter W=8) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [W-1:0] clk_div,
    output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;
    wire counter_is_zero = (counter == 'b0);
    wire tick_w = (clk_div == 'b0) ? 1'b1 : counter_is_zero;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            counter <= 'b0;
        else if (en) begin
            if (counter_is_zero)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tick_reg <= 1'b0;
        else if (en)
            tick_reg <= tick_w;
        else
            tick_reg <= 1'b0;
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk,
    input wire rst_n,
    input wire in,
    input wire en,
    output reg out
);
