    localparam DEPTH = 2**AW;

    reg [DW-1:0] array_reg [0:DEPTH-1];
    reg [AW-1:0] w_ptr, r_ptr;
    reg [AW-1:0] level_reg;
    reg empty_reg, full_reg;
    wire w_en = wr & ~full_reg;

    assign rdata = array_reg[r_ptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;

    always @(posedge clk) begin
        if (w_en)
            array_reg[w_ptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr <= 'b0;
            r_ptr <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else if (flush) begin
            w_ptr <= 'b0;
            r_ptr <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else begin
            case ({w_en, rd & ~empty_reg})
                2'b10: begin
                    w_ptr <= w_ptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
