                2'b01: begin
                    r_ptr <= r_ptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg <= 1'b0;
                    if ((r_ptr + 1'b1) == w_ptr)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    w_ptr <= w_ptr + 1'b1;
                    r_ptr <= r_ptr + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end
