module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;
    wire [15:0] count_next;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'b0;
        else if (en)
            count_reg <= count_next;
    end

    assign count_next = (count_reg == prescale) ? 16'b0 :
                        count_reg + 1'b1;
    assign baudtick = en && (count_reg == prescale);
