        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_tx_reg = tx_reg;
        tx_done = 1'b0;

        case (state)
            IDLE: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state = START;
                    next_sample_count = 0;
                    next_data_reg = d_in;
                end
            end
            START: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            DATA: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            PARITY: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^pdata;
                    3'b010: next_tx_reg = ^pdata;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b0;
                endcase
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            STOP0: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            STOP1: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            default: next_state = IDLE;
        endcase
