    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [8:0] data_reg, next_data_reg;
    reg parity_err, next_parity_err;
    reg frame_err, next_frame_err;
    reg [11:0] brk;

    wire [MDW-1:0] received_data =
        data_reg >> (9-data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_err <= 0;
            frame_err <= 0;
            brk <= 12'hfff;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            if (state == IDLE)
                parity_err <= 1'b0;
            else if (next_parity_err)
                parity_err <= 1'b1;
            if (state == IDLE)
                frame_err <= 1'b0;
            else if (next_frame_err)
                frame_err <= 1'b1;

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    brk <= 12'hfff;
                else
                    brk <= {brk[10:0], rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_parity_err = 1'b0;
        next_frame_err = 1'b0;
        rx_done = 1'b0;

        case (state)
            IDLE:
                if (!rx && b_tick) begin
                    next_state = START;
                    next_sample_count = 0;
                end

            START:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES/2-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            DATA:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1)
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            PARITY:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                        case (parity_type)
                            3'b001: if ((~^received_data) != rx)
                                        next_parity_err = 1'b1;
                            3'b010: if ((^received_data) != rx)
                                        next_parity_err = 1'b1;
                            3'b100: if (rx != 1'b0)
                                        next_parity_err = 1'b1;
                            3'b101: if (rx != 1'b1)
                                        next_parity_err = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            STOP0:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx)
                            next_frame_err = 1'b1;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            STOP1:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_err = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            default: next_state = IDLE;
        endcase
    end

    assign dout = received_data;
    assign parity_error = parity_err & rx_done;
    assign frame_error = frame_err & rx_done;
    assign break_flag = (brk == 12'b0);
    assign match_flag = (match_data == received_data) & rx_done;
endmodule

module EF_UART #(
