module ef_util_sync #(parameter NUM_STAGES = 2) (
    input  wire clk,
    input  wire in,
    output wire out
);
    reg [NUM_STAGES-1:0] sync;

    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};

    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [W-1:0] clk_div,
    output wire         tick
);
    reg [W-1:0] counter;
    reg         tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter  <= 'b0;
            tick_reg <= 1'b0;
        end else begin
            tick_reg <= en && ((clk_div == 'b0) || (counter == 'b0));
            if (en) begin
                if (counter == 'b0)
                    counter <= clk_div;
                else
                    counter <= counter - 1'b1;
            end
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input  wire clk,
    input  wire rst_n,
    input  wire in,
    input  wire en,
    output reg  out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out     <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&{shifter[N-2:0], in})
                out <= 1'b1;
            else if (~|{shifter[N-2:0], in})
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          rd,
    input  wire          wr,
    input  wire          flush,
    input  wire [DW-1:0] wdata,
    output wire          empty,
    output wire          full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;

    reg [DW-1:0] array_reg [0:DEPTH-1];
    reg [AW-1:0] w_ptr_reg, r_ptr_reg;
    reg [AW-1:0] level_reg;
    reg          full_reg, empty_reg;

    wire wr_accept = wr && !full_reg;
    wire rd_accept = rd && !empty_reg;

    always @(posedge clk) begin
        if (wr_accept)
            array_reg[w_ptr_reg] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            level_reg <= 'b0;
            full_reg  <= 1'b0;
            empty_reg <= 1'b1;
        end else if (flush) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            level_reg <= 'b0;
            full_reg  <= 1'b0;
            empty_reg <= 1'b1;
        end else begin
            case ({wr_accept, rd_accept})
                2'b10: begin
                    w_ptr_reg <= w_ptr_reg + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((w_ptr_reg + 1'b1) == r_ptr_reg)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    r_ptr_reg <= r_ptr_reg + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg  <= 1'b0;
                    if ((r_ptr_reg + 1'b1) == w_ptr_reg)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    w_ptr_reg <= w_ptr_reg + 1'b1;
                    r_ptr_reg <= r_ptr_reg + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

    assign rdata = array_reg[r_ptr_reg];
    assign empty = empty_reg;
    assign full  = full_reg;
    assign level = level_reg;
endmodule

