module ef_util_ticker #(parameter W=8) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [W-1:0] clk_div,
    output wire         tick
);
    reg [W-1:0] counter;
    reg         tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter  <= 'b0;
            tick_reg <= 1'b0;
        end else begin
            tick_reg <= en && ((clk_div == 'b0) || (counter == 'b0));
            if (en) begin
                if (counter == 'b0)
                    counter <= clk_div;
                else
                    counter <= counter - 1'b1;
            end
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
