module EF_UART #(
    parameter MDW = 9,
    parameter FAW = 4,
    parameter SC = 8,
    parameter GFLEN = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire [15:0] prescaler,
    input  wire en,
    input  wire tx_en,
    input  wire rx_en,
    input  wire rd,
    input  wire wr,
    input  wire [MDW-1:0] wdata,
    input  wire [3:0] data_size,
    input  wire stop_bits_count,
    input  wire [2:0] parity_type,
    input  wire [3:0] txfifotr,
    input  wire [3:0] rxfifotr,
    input  wire [MDW-1:0] match_data,
    input  wire [5:0] timeout_bits,
    input  wire loopback_en,
    input  wire glitch_filter_en,
    input  wire tx_fifo_flush,
    input  wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire b_tick;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_synched, rx_filtered, rx_in;
    wire tx_done, rx_done;

    ef_util_sync rx_sync (
        .clk(clk), .in(rx), .out(rx_synched)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .en(glitch_filter_en),
        .in(rx_synched),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_synched;

    BAUDGEN baud_gen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_tx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_tx (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(b_tick && tx_en),
        .data_size(data_size),
        .parity_type(parity_type),
        .stop_bits_count(stop_bits_count),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_rx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_rx (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(b_tick && rx_en),
        .data_size(data_size),
        .parity_type(parity_type),
        .stop_bits_count(stop_bits_count),
        .match_data(match_data),
        .rx(rx_in),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .rx_done(rx_done),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count    <= 6'd0;
            samples_count <= 5'd0;
        end else if (rx_done) begin
            bits_count    <= 6'd0;
            samples_count <= 5'd0;
        end else if (b_tick) begin
            if (samples_count == SC-1) begin
                samples_count <= 5'd0;
                if (bits_count == timeout_bits)
                    bits_count <= 6'd0;
                else
                    bits_count <= bits_count + 1'b1;
            end else begin
                samples_count <= samples_count + 1'b1;
            end
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag   = rx_full && rx_done;
    assign timeout_flag   = (bits_count == timeout_bits);
endmodule

module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 :
                         count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data;
    reg p_error, next_p_error;
    reg f_error, next_f_error;
    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state         <= idle_st;
            sample_count  <= 0;
            bit_count     <= 0;
            data_reg      <= 0;
            p_error       <= 0;
            f_error       <= 0;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data;
            if (state == idle_st) begin
                p_error <= 1'b0;
                f_error <= 1'b0;
            end else begin
                p_error <= p_error | next_p_error;
                f_error <= f_error | next_f_error;
            end
        end
    end

    always @* begin
        next_state       = state;
        next_sample_count = sample_count;
        next_bit_count   = bit_count;
        next_data        = data_reg;
        next_p_error     = 1'b0;
        next_f_error     = 1'b0;
        rx_done          = 1'b0;

        case (state)
            idle_st: begin
                if (b_tick && !rx) begin
                    next_state        = start_st;
                    next_sample_count = 0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state        = data_st;
                        next_sample_count = 0;
                        next_bit_count    = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if ((~^data_reg) != rx) next_p_error = 1'b1;
                            3'b010: if (( ^data_reg) != rx) next_p_error = 1'b1;
                            3'b100: if (1'b0 != rx)       next_p_error = 1'b1;
                            3'b101: if (1'b1 != rx)       next_p_error = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx) next_f_error = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx) next_f_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && sample_count == NUM_SAMPLES-1) begin
            if (state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout         = data_reg;
    assign parity_error = rx_done && (p_error || next_p_error);
    assign frame_error  = rx_done && (f_error || next_f_error);
    assign break_flag   = (brk == 12'd0);
    assign match_flag   = rx_done && (dout == match_data);
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data;
    reg tx_reg, next_tx;

    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= idle_st;
            sample_count <= 0;
            bit_count    <= 0;
            data_reg     <= 0;
            tx_reg       <= 1'b1;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data;
            tx_reg       <= next_tx;
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data         = data_reg;
        next_tx           = tx_reg;
        tx_done           = 1'b0;

        case (state)
            idle_st: begin
                next_tx = 1'b1;
                if (tx_start) begin
                    next_state        = start_st;
                    next_sample_count = 0;
                    next_data         = d_in;
                end
            end

            start_st: begin
                next_tx = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state        = data_st;
                        next_sample_count = 0;
                        next_bit_count    = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                next_tx = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx = ~^pdata;
                    3'b010: next_tx =  ^pdata;
                    3'b100: next_tx = 1'b0;
                    3'b101: next_tx = 1'b1;
                    default: next_tx = 1'b0;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = stop0_st;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    parameter MDW = 9,
    parameter GFLEN = 8,
    parameter FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_OFFSET = 16'h0000;
    localparam TXDATA_OFFSET = 16'h0004;
    localparam PR_OFFSET     = 16'h0008;
    localparam CTRL_OFFSET   = 16'h000c;
    localparam CFG_OFFSET    = 16'h0010;
    localparam MATCH_OFFSET  = 16'h001c;
    localparam RXLEVEL_OFFSET = 16'hfe00;
    localparam RXTHRESH_OFFSET = 16'hfe04;
    localparam RXFLUSH_OFFSET = 16'hfe08;
    localparam TXLEVEL_OFFSET = 16'hfe10;
    localparam TXTHRESH_OFFSET = 16'hfe14;
    localparam TXFLUSH_OFFSET = 16'hfe18;
    localparam IM_OFFSET  = 16'hff00;
    localparam MIS_OFFSET = 16'hff04;
    localparam RIS_OFFSET = 16'hff08;
    localparam IC_OFFSET  = 16'hff0c;
    localparam GCLK_OFFSET = 16'hff10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;
    wire clk = PCLK;

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_thresh_reg, tx_thresh_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire rd = apb_re && (PADDR[15:0] == RXDATA_OFFSET);
    wire wr = apb_we  && (PADDR[15:0] == TXDATA_OFFSET);
    wire rx_flush = rx_flush_reg;
    wire tx_flush = tx_flush_reg;

    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg        <= 16'd0;
            ctrl_reg      <= 5'd0;
            cfg_reg       <= 14'h3f08;
            match_reg     <= 'd0;
            rx_thresh_reg <= 'd0;
            tx_thresh_reg <= 'd0;
            rx_flush_reg  <= 1'b0;
            tx_flush_reg  <= 1'b0;
            gclk_reg      <= 1'b0;
            im_reg        <= 10'd0;
            ic_reg        <= 10'd0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg       <= 10'd0;

            if (apb_we && PADDR[15:0] == PR_OFFSET)
                pr_reg <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == CTRL_OFFSET)
                ctrl_reg <= PWDATA[4:0];
            if (apb_we && PADDR[15:0] == CFG_OFFSET)
                cfg_reg <= PWDATA[13:0];
            if (apb_we && PADDR[15:0] == MATCH_OFFSET)
                match_reg <= PWDATA[MDW-1:0];
            if (apb_we && PADDR[15:0] == RXTHRESH_OFFSET)
                rx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == TXTHRESH_OFFSET)
                tx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == RXFLUSH_OFFSET)
                rx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == TXFLUSH_OFFSET)
                tx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == GCLK_OFFSET)
                gclk_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == IM_OFFSET)
                im_reg <= PWDATA[9:0];
            if (apb_we && PADDR[15:0] == IC_OFFSET)
                ic_reg <= PWDATA[9:0];
        end
    end

    EF_UART #(
        .SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)
    ) uart (
        .clk(clk),
        .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]),
        .rx_en(ctrl_reg[2]),
        .rd(rd),
        .wr(wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_thresh_reg),
        .rxfifotr(rx_thresh_reg),
        .match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush),
        .rx_fifo_flush(rx_flush),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    wire [9:0] event_status = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'd0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | event_status;
    end

    assign PRDATA =
        (PADDR[15:0] == RXDATA_OFFSET)    ? {{(32-MDW){1'b0}}, rdata} :
        (PADDR[15:0] == PR_OFFSET)        ? {{16{1'b0}}, pr_reg} :
        (PADDR[15:0] == CTRL_OFFSET)      ? {{27{1'b0}}, ctrl_reg} :
        (PADDR[15:0] == CFG_OFFSET)       ? {{18{1'b0}}, cfg_reg} :
        (PADDR[15:0] == MATCH_OFFSET)     ? {{(32-MDW){1'b0}}, match_reg} :
        (PADDR[15:0] == RXLEVEL_OFFSET)   ? {{(32-FAW){1'b0}}, rx_level} :
        (PADDR[15:0] == RXTHRESH_OFFSET)  ? {{(32-FAW){1'b0}}, rx_thresh_reg} :
        (PADDR[15:0] == RXFLUSH_OFFSET)   ? {{31{1'b0}}, rx_flush_reg} :
        (PADDR[15:0] == TXLEVEL_OFFSET)   ? {{(32-FAW){1'b0}}, tx_level} :
        (PADDR[15:0] == TXTHRESH_OFFSET)  ? {{(32-FAW){1'b0}}, tx_thresh_reg} :
        (PADDR[15:0] == TXFLUSH_OFFSET)   ? {{31{1'b0}}, tx_flush_reg} :
        (PADDR[15:0] == IM_OFFSET)        ? {{22{1'b0}}, im_reg} :
        (PADDR[15:0] == MIS_OFFSET)       ? {{22{1'b0}}, (ris_reg & im_reg)} :
        (PADDR[15:0] == RIS_OFFSET)       ? {{22{1'b0}}, ris_reg} :
        (PADDR[15:0] == GCLK_OFFSET)      ? {{31{1'b0}}, gclk_reg} :
        32'hdeadbeef;

    assign PREADY = 1'b1;
    assign IRQ = |(ris_reg & im_reg);
endmodule

`default_nettype wire
