    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IM_REG <= 3'd0;
        else if (apb_we && PADDR[15:0] == IM_REG_OFFSET)
            IM_REG <= PWDATA[2:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IC_REG <= 3'd0;
        else if (apb_we && PADDR[15:0] == IC_REG_OFFSET)
            IC_REG <= PWDATA[2:0];
        else
            IC_REG <= 3'd0;
    end

    wire [2:0] irq_flags = {
        matchy_flag,
        matchx_flag,
        timeout_flag
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'd0;
        else begin
            for (i = 0; i < 3; i = i + 1) begin
                if (IC_REG[i])
                    RIS_REG[i] <= 1'b0;
                else if (irq_flags[i])
                    RIS_REG[i] <= 1'b1;
            end
        end
    end

    wire [31:0] tmr;
    wire matchx_flag;
    wire matchy_flag;
    wire timeout_flag;

    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .tmr_en(CTRL_REG[0]),
        .tmr_start(CTRL_REG[1]),
        .pwm0_en(CTRL_REG[2]),
        .pwm1_en(CTRL_REG[3]),
        .tmr_reload(RELOAD_REG),
        .cmpx(CMPX_REG),
        .cmpy(CMPY_REG),
        .prescaler(PR_REG),
        .tmr_cfg(CFG_REG),
        .pwm0_cfg(PWM0CFG_REG),
        .pwm1_cfg(PWM1CFG_REG[11:0]),
        .pwm0_inv(CTRL_REG[5]),
