module BAUDGEN (
    input wire clk, input wire rst_n,
    input wire [15:0] prescale, input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 :
                         count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st=3'd0, start_st=3'd1, data_st=3'd2,
               parity_st=3'd3, stop0_st=3'd4, stop1_st=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] baud_count, next_baud_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx_reg;

    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state      <= idle_st;
            baud_count <= 0;
            bit_count  <= 0;
            data_reg   <= 0;
            tx_reg     <= 1'b1;
        end else begin
            state      <= next_state;
            baud_count <= next_baud_count;
            bit_count  <= next_bit_count;
            data_reg   <= next_data_reg;
            tx_reg     <= next_tx_reg;
        end
    end

    always @* begin
        next_state      = state;
        next_baud_count = baud_count;
        next_bit_count  = bit_count;
        next_data_reg   = data_reg;
        next_tx_reg     = tx_reg;
        tx_done         = 1'b0;

        case (state)
            idle_st: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state      = start_st;
                    next_baud_count = 0;
                    next_data_reg   = d_in;
                end
            end

            start_st: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES) begin
                        next_state      = data_st;
                        next_baud_count = 0;
                        next_bit_count  = 0;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            data_st: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_data_reg   = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^pdata;
                    3'b010: next_tx_reg =  ^pdata;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b0;
                endcase

                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = stop0_st;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_state = idle_st;
                        next_baud_count = 0;
                        tx_done = 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error, output wire frame_error,
    output wire break_flag, output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st=3'd0, start_st=3'd1, data_st=3'd2,
               parity_st=3'd3, stop0_st=3'd4, stop1_st=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] baud_count, next_baud_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    wire [MDW-1:0] data_value = data_reg >> (MDW-data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state           <= idle_st;
            baud_count      <= 0;
            bit_count       <= 0;
            data_reg        <= 0;
            parity_error_reg<= 1'b0;
            frame_error_reg <= 1'b0;
            break_shift     <= 12'hfff;
        end else begin
            state      <= next_state;
            baud_count <= next_baud_count;
            bit_count  <= next_bit_count;
            data_reg   <= next_data_reg;

            if (state == idle_st) begin
                parity_error_reg <= 1'b0;
                frame_error_reg  <= 1'b0;
            end else begin
                if (next_parity_error)
                    parity_error_reg <= 1'b1;
                if (next_frame_error)
                    frame_error_reg <= 1'b1;
            end

            if (b_tick && baud_count == NUM_SAMPLES-1) begin
                if (state == idle_st)
                    break_shift <= 12'hfff;
                else
                    break_shift <= {break_shift[10:0], rx};
            end
        end
    end

    always @* begin
        next_state       = state;
        next_baud_count  = baud_count;
        next_bit_count   = bit_count;
        next_data_reg    = data_reg;
        next_parity_error= 1'b0;
        next_frame_error = 1'b0;
        rx_done          = 1'b0;

        case (state)
            idle_st: begin
                if (!rx && b_tick) begin
                    next_state = start_st;
                    next_baud_count = 0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (baud_count == (NUM_SAMPLES/2)-1) begin
                        next_state = data_st;
                        next_baud_count = 0;
                        next_bit_count = 0;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_data_reg = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1)
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001:
                                if ((~^data_value) != rx)
                                    next_parity_error = 1'b1;
                            3'b010:
                                if ((^data_value) != rx)
                                    next_parity_error = 1'b1;
                            3'b100:
                                if (rx != 1'b0)
                                    next_parity_error = 1'b1;
                            3'b101:
                                if (rx != 1'b1)
                                    next_parity_error = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        if (!rx)
                            next_frame_error = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign dout         = data_value;
    assign parity_error = parity_error_reg && rx_done;
    assign frame_error  = frame_error_reg && rx_done;
    assign match_flag   = (data_value == match_data) && rx_done;
    assign break_flag   = (break_shift == 12'b0);
endmodule

module EF_UART #(parameter MDW=9, FAW=4, SC=8, GFLEN=8) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr, input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en, input wire glitch_filter_en,
    input wire tx_fifo_flush, input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire baud_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_sync, rx_filtered, rx_in;

    ef_util_sync rx_sync_i (.clk(clk), .in(rx), .out(rx_sync));

    ef_util_glitch_filter #(.N(GFLEN)) filter_i (
        .clk(clk), .rst_n(rst_n), .in(rx_sync),
        .en(glitch_filter_en), .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud_i (
        .clk(clk), .rst_n(rst_n), .prescale(prescaler),
        .en(en), .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk), .rst_n(rst_n), .rd(tx_done), .wr(wr),
        .flush(tx_fifo_flush), .wdata(wdata),
        .empty(tx_empty), .full(tx_full), .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) tx_i (
        .clk(clk), .resetn(rst_n), .tx_start(!tx_empty),
        .b_tick(baud_tick && tx_en), .data_size(data_size),
        .stop_bits_count(stop_bits_count), .parity_type(parity_type),
        .d_in(tx_data), .tx_done(tx_done), .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk), .rst_n(rst_n), .rd(rd), .wr(rx_done),
        .flush(rx_fifo_flush), .wdata(rx_data),
        .empty(rx_empty), .full(rx_full), .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) rx_i (
        .clk(clk), .resetn(rst_n), .b_tick(baud_tick && rx_en),
        .data_size(data_size), .stop_bits_count(stop_bits_count),
        .parity_type(parity_type), .rx(rx_in),
        .match_data(match_data), .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag), .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [4:0] sample_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            sample_count  <= 0;
        end else if (rx_done) begin
            timeout_count <= 0;
            sample_count  <= 0;
        end else if (baud_tick && rx_en) begin
            if (sample_count == SC-1) begin
                sample_count <= 0;
                if (timeout_count == timeout_bits)
                    timeout_count <= 0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else
                sample_count <= sample_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag   = rx_full && rx_done;
    assign timeout_flag   = (timeout_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC=8, MDW=9, GFLEN=8, FAW=4
) (
    input wire PCLK, input wire PRESETn,
    input wire PWRITE, input wire [31:0] PWDATA,
    input wire [31:0] PADDR, input wire PENABLE, input wire PSEL,
    output wire PREADY, output wire [31:0] PRDATA, output wire IRQ,
    input wire [1-1:0] rx, output wire [1-1:0] tx
);
    localparam RXDATA = 16'h0000, TXDATA = 16'h0004;
    localparam PR     = 16'h0008, CTRL   = 16'h000c;
    localparam CFG    = 16'h0010, MATCH  = 16'h001c;
    localparam RXLEV  = 16'hfe00, RXTHR  = 16'hfe04, RXFLUSH = 16'hfe08;
    localparam TXLEV  = 16'hfe10, TXTHR  = 16'hfe14, TXFLUSH = 16'hfe18;
    localparam IM     = 16'hff00, MIS    = 16'hff04, RIS    = 16'hff08;
    localparam IC     = 16'hff0c, GCLK   = 16'hff10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_we    = apb_valid && PWRITE;
    wire apb_re    = apb_valid && !PWRITE;

    reg [15:0] pr_reg;
    reg [4:0]  ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_thr_reg, tx_thr_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rx_data;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire [9:0] raw_status = {
        timeout_flag, overrun_flag, parity_error_flag, frame_error_flag,
        match_flag, break_flag, rx_level_above, tx_level_below,
        rx_full, tx_empty
    };

    wire [9:0] mis_value = ris_reg & im_reg;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg       <= 0;
            ctrl_reg     <= 0;
            cfg_reg      <= 14'h3f08;
            match_reg    <= 0;
            rx_thr_reg   <= 0;
            tx_thr_reg   <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg     <= 0;
            im_reg       <= 0;
            ic_reg       <= 0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg       <= 10'b0;

            if (apb_we && PADDR[15:0] == PR)
                pr_reg <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == CTRL)
                ctrl_reg <= PWDATA[4:0];
            if (apb_we && PADDR[15:0] == CFG)
                cfg_reg <= PWDATA[13:0];
            if (apb_we && PADDR[15:0] == MATCH)
                match_reg <= PWDATA[MDW-1:0];
            if (apb_we && PADDR[15:0] == RXTHR)
                rx_thr_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == TXTHR)
                tx_thr_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == RXFLUSH)
                rx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == TXFLUSH)
                tx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == GCLK)
                gclk_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == IM)
                im_reg <= PWDATA[9:0];
            if (apb_we && PADDR[15:0] == IC)
                ic_reg <= PWDATA[9:0];
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | raw_status;
    end

    EF_UART #(
        .SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)
    ) uart (
        .clk(PCLK), .rst_n(PRESETn),
        .prescaler(pr_reg), .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]), .rx_en(ctrl_reg[2]),
        .loopback_en(ctrl_reg[3]), .glitch_filter_en(ctrl_reg[4]),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .timeout_bits(cfg_reg[13:8]),
        .match_data(match_reg),
        .txfifotr(tx_thr_reg), .rxfifotr(rx_thr_reg),
        .rd(apb_re && PADDR[15:0] == RXDATA),
        .wr(apb_we && PADDR[15:0] == TXDATA),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty), .tx_full(tx_full),
        .tx_level(tx_level), .tx_level_below(tx_level_below),
        .rdata(rx_data),
        .rx_empty(rx_empty), .rx_full(rx_full),
        .rx_level(rx_level), .rx_level_above(rx_level_above),
        .break_flag(break_flag), .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx), .tx(tx)
    );

    assign PRDATA =
        (PADDR[15:0] == RXDATA)  ? {{(32-MDW){1'b0}}, rx_data} :
        (PADDR[15:0] == PR)      ? {{16{1'b0}}, pr_reg} :
        (PADDR[15:0] == CTRL)    ? {{27{1'b0}}, ctrl_reg} :
        (PADDR[15:0] == CFG)     ? {{18{1'b0}}, cfg_reg} :
        (PADDR[15:0] == MATCH)   ? {{(32-MDW){1'b0}}, match_reg} :
        (PADDR[15:0] == RXLEV)   ? {{(32-FAW){1'b0}}, rx_level} :
        (PADDR[15:0] == RXTHR)   ? {{(32-FAW){1'b0}}, rx_thr_reg} :
        (PADDR[15:0] == RXFLUSH) ? {{31{1'b0}}, rx_flush_reg} :
        (PADDR[15:0] == TXLEV)   ? {{(32-FAW){1'b0}}, tx_level} :
        (PADDR[15:0] == TXTHR)   ? {{(32-FAW){1'b0}}, tx_thr_reg} :
        (PADDR[15:0] == TXFLUSH) ? {{31{1'b0}}, tx_flush_reg} :
        (PADDR[15:0] == IM)      ? {{22{1'b0}}, im_reg} :
        (PADDR[15:0] == MIS)     ? {{22{1'b0}}, mis_value} :
        (PADDR[15:0] == RIS)     ? {{22{1'b0}}, ris_reg} :
        (PADDR[15:0] == GCLK)    ? {{31{1'b0}}, gclk_reg} :
        32'hdeadbeef;

    assign PREADY = 1'b1;
    assign IRQ = |mis_value;
