    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en) begin
            if (count_reg == prescale)
                count_reg <= 16'd0;
            else
                count_reg <= count_reg + 1'b1;
        end
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire tx_start, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2;
    localparam PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx_reg;
    reg parity_bit;

    always @* begin
        parity_bit = 1'b0;
        case (parity_type)
            3'b001: parity_bit = ~(^d_in);
            3'b010: parity_bit =  ^d_in;
            3'b100: parity_bit = 1'b0;
            3'b101: parity_bit = 1'b1;
            default: parity_bit = 1'b0;
        endcase
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_tx_reg = tx_reg;
        tx_done = 1'b0;

        case (state)
            IDLE: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state = START;
                    next_sample_count = 16'd0;
                    next_data_reg = d_in;
                end
            end

            START: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state = DATA;
                        next_sample_count = 16'd0;
                        next_bit_count = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = STOP0;
                            else
                                next_state = PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                next_tx_reg = parity_bit;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = IDLE;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 16'd0;
            bit_count <= 4'd0;
            data_reg <= 'b0;
            tx_reg <= 1'b1;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            tx_reg <= next_tx_reg;
        end
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2;
    localparam PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_reg;

    wire calculated_parity =
        (parity_type == 3'b001) ? ~(^data_reg) :
        (parity_type == 3'b010) ?  (^data_reg) :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_parity_error = parity_error_reg;
        next_frame_error = frame_error_reg;
        rx_done = 1'b0;

        case (state)
            IDLE: begin
                next_parity_error = 1'b0;
                next_frame_error = 1'b0;
                if (b_tick && !rx) begin
                    next_state = START;
                    next_sample_count = 16'd0;
                end
            end

            START: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state = DATA;
                        next_sample_count = 16'd0;
                        next_bit_count = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = STOP0;
                            else
                                next_state = PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = STOP0;
                        if (rx != calculated_parity)
                            next_parity_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        if (!rx)
                            next_frame_error = 1'b1;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = IDLE;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 16'd0;
            bit_count <= 4'd0;
            data_reg <= 'b0;
            parity_error_reg <= 1'b0;
            frame_error_reg <= 1'b0;
            break_reg <= 12'hfff;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            parity_error_reg <= next_parity_error;
            frame_error_reg <= next_frame_error;

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    break_reg <= 12'hfff;
                else
                    break_reg <= {break_reg[10:0], rx};
            end
        end
    end

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = parity_error_reg && rx_done;
    assign frame_error = frame_error_reg && rx_done;
    assign break_flag = (break_reg == 12'd0);
    assign match_flag = (dout == match_data) && rx_done;
endmodule

module EF_UART #(
    parameter MDW=9, FAW=4, SC=8, GFLEN=8
) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire baud_tick;
    wire rx_synched, rx_filtered, rx_in;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;

    ef_util_sync rx_sync (
        .clk(clk), .in(rx), .out(rx_synched)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_filter (
        .clk(clk), .rst_n(rst_n), .in(rx_synched),
        .en(glitch_filter_en), .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_synched;

    BAUDGEN baudgen (
        .clk(clk), .rst_n(rst_n), .prescale(prescaler),
        .en(en), .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk), .rst_n(rst_n), .rd(tx_done), .wr(wr),
        .flush(tx_fifo_flush), .wdata(wdata),
        .empty(tx_empty), .full(tx_full),
        .rdata(tx_data), .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) transmitter (
        .clk(clk), .resetn(rst_n), .tx_start(!tx_empty),
        .b_tick(baud_tick && tx_en), .data_size(data_size),
        .stop_bits_count(stop_bits_count), .parity_type(parity_type),
        .d_in(tx_data), .tx_done(tx_done), .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk), .rst_n(rst_n), .rd(rd), .wr(rx_done),
        .flush(rx_fifo_flush), .wdata(rx_data),
        .empty(rx_empty), .full(rx_full),
        .rdata(rdata), .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) receiver (
        .clk(clk), .resetn(rst_n), .b_tick(baud_tick && rx_en),
        .data_size(data_size), .stop_bits_count(stop_bits_count),
        .parity_type(parity_type), .rx(rx_in),
        .match_data(match_data), .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag), .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [4:0] sample_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 6'd0;
            sample_count <= 5'd0;
        end else if (baud_tick) begin
            if (rx_done) begin
                timeout_count <= 6'd0;
                sample_count <= 5'd0;
            end else if (sample_count == SC-1) begin
                sample_count <= 5'd0;
                if (timeout_count == timeout_bits)
                    timeout_count <= 6'd0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else begin
                sample_count <= sample_count + 1'b1;
            end
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_full && rx_done;
    assign timeout_flag = (timeout_count == timeout_bits);
endmodule

