            /*
             * A simultaneous read/write advances both pointers and leaves
             * the FIFO occupancy unchanged, as specified.
             */
            wptr <= wptr + 1'b1;
            rptr <= rptr + 1'b1;
        end else if (write_accept) begin
            wptr <= wptr + 1'b1;
            level_reg <= level_reg + 1'b1;
            empty_reg <= 1'b0;
            if ((wptr + 1'b1) == rptr)
                full_reg <= 1'b1;
        end else if (rd && !empty_reg) begin
            rptr <= rptr + 1'b1;
            level_reg <= level_reg - 1'b1;
            full_reg <= 1'b0;
            if ((rptr + 1'b1) == wptr)
                empty_reg <= 1'b1;
        end
    end

    assign rdata = mem[rptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;
