module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk, input wire in, output wire out
);
    reg [NUM_STAGES-1:0] sync;
    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};
    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;
    wire zero = (counter == {W{1'b0}});
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 'b0;
            tick_reg <= 1'b0;
        end else if (en) begin
            counter <= zero ? clk_div : counter - 1'b1;
            tick_reg <= (clk_div == 0) ? 1'b1 : zero;
        end else begin
            tick_reg <= 1'b0;
        end
    end
    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;
    ef_util_ticker #(.W(8)) ticker (
        .clk(clk), .rst_n(rst_n), .en(en), .clk_div(CLKDIV), .tick(tick)
    );
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0],in};
            if (&shifter)
                out <= 1'b1;
            else if (~|shifter)
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 1 << AW;
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rp, wp, lev;
    reg emp, ful;
    wire do_wr = wr & ~ful;
    wire do_rd = rd & ~emp;

    always @(posedge clk) begin
        if (do_wr)
            mem[wp] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rp <= 0;
            wp <= 0;
            lev <= 0;
            emp <= 1'b1;
            ful <= 1'b0;
        end else if (flush) begin
            rp <= 0;
            wp <= 0;
            lev <= 0;
            emp <= 1'b1;
            ful <= 1'b0;
        end else begin
            if (do_wr)
                wp <= wp + 1'b1;
            if (do_rd)
                rp <= rp + 1'b1;

            case ({do_wr,do_rd})
                2'b10: begin
                    lev <= lev + 1'b1;
                    emp <= 1'b0;
                    if (lev == {AW{1'b1}})
                        ful <= 1'b1;
                end
                2'b01: begin
                    lev <= lev - 1'b1;
                    ful <= 1'b0;
                    if (lev == {{(AW-1){1'b0}},1'b1})
                        emp <= 1'b1;
                end
                default: begin
                    lev <= lev;
                    emp <= emp;
                    ful <= ful;
                end
            endcase
        end
    end

    assign rdata = mem[rp];
    assign level = lev;
    assign empty = emp;
    assign full = ful;
endmodule

