module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                   PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx;
    wire parity_value =
        (parity_type == 3'b001) ? ~^d_in :
        (parity_type == 3'b010) ?  ^d_in :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            tx_reg <= next_tx;
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_tx = tx_reg;
        tx_done = 1'b0;

        case (state)
            IDLE: begin
                next_tx = 1'b1;
                if (tx_start) begin
                    next_state = START;
                    next_sample_count = 0;
                    next_bit_count = 0;
                    next_data_reg = d_in;
                end
            end
            START: begin
                next_tx = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state = DATA;
                        next_sample_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            DATA: begin
                next_tx = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = data_reg >> 1;
                        if (bit_count == data_size-1)
                            next_state = (parity_type == 3'b000) ? STOP0 : PARITY;
                        else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            PARITY: begin
                next_tx = parity_value;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            STOP0: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            STOP1: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_state = IDLE;
                        next_sample_count = 0;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end
            default: next_state = IDLE;
        endcase
    end
    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                   PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_err_reg, next_parity_err;
    reg frame_err_reg, next_frame_err;
    reg [11:0] brk;

    wire expected_parity =
        (parity_type == 3'b001) ? ~^data_reg :
        (parity_type == 3'b010) ?  ^data_reg :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_err_reg <= 0;
            frame_err_reg <= 0;
            brk <= 12'hfff;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            if (state == IDLE) begin
                parity_err_reg <= 1'b0;
                frame_err_reg <= 1'b0;
            end else begin
                if (next_parity_err)
                    parity_err_reg <= 1'b1;
                if (next_frame_err)
                    frame_err_reg <= 1'b1;
            end

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    brk <= 12'hfff;
                else
                    brk <= {brk[10:0],rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_parity_err = 1'b0;
        next_frame_err = 1'b0;
        rx_done = 1'b0;

        case (state)
            IDLE:
                if (!rx && b_tick) begin
                    next_state = START;
                    next_sample_count = 0;
                end

            START:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES/2-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            DATA:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = {rx,data_reg[MDW-1:1]};
                        if (bit_count == data_size-1)
                            next_state = (parity_type == 3'b000) ? STOP0 : PARITY;
                        else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            PARITY:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                        if (parity_type != 3'b000 && rx != expected_parity)
                            next_parity_err = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            STOP0:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx)
                            next_frame_err = 1'b1;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            STOP1:
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_state = IDLE;
                        next_sample_count = 0;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_err = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end

            default: next_state = IDLE;
        endcase
    end

    assign dout = data_reg;
    assign parity_error = parity_err_reg & rx_done;
    assign frame_error = frame_err_reg & rx_done;
    assign break_flag = (brk == 12'b0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module EF_UART #(
    parameter MDW=9, FAW=4, SC=8, GFLEN=8
) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr, input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en, input wire glitch_filter_en,
    input wire tx_fifo_flush, input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire b_tick, tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_sync, rx_filtered, rx_in;

    ef_util_sync sync_i(.clk(clk),.in(rx),.out(rx_sync));
    ef_util_glitch_filter #(.N(GFLEN)) filter_i(
        .clk(clk),.rst_n(rst_n),.in(rx_sync),
        .en(glitch_filter_en),.out(rx_filtered)
    );
    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud_i(
        .clk(clk),.rst_n(rst_n),.prescale(prescaler),
        .en(en),.baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo(
        .clk(clk),.rst_n(rst_n),.rd(tx_done),.wr(wr),
        .flush(tx_fifo_flush),.wdata(wdata),
        .empty(tx_empty),.full(tx_full),
        .rdata(tx_data),.level(tx_level)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) rx_fifo(
        .clk(clk),.rst_n(rst_n),.rd(rd),.wr(rx_done),
        .flush(rx_fifo_flush),.wdata(rx_data),
        .empty(rx_empty),.full(rx_full),
        .rdata(rdata),.level(rx_level)
    );

    UART_TX #(.MDW(MDW),.NUM_SAMPLES(SC)) tx_i(
        .clk(clk),.resetn(rst_n),.tx_start(~tx_empty),
        .b_tick(b_tick & tx_en),.data_size(data_size),
        .stop_bits_count(stop_bits_count),.parity_type(parity_type),
        .d_in(tx_data),.tx_done(tx_done),.tx(tx)
    );

    UART_RX #(.MDW(MDW),.NUM_SAMPLES(SC)) rx_i(
        .clk(clk),.resetn(rst_n),.b_tick(b_tick & rx_en),
        .data_size(data_size),.stop_bits_count(stop_bits_count),
        .parity_type(parity_type),.rx(rx_in),
        .match_data(match_data),.rx_done(rx_done),
        .dout(rx_data),.break_flag(break_flag),
        .match_flag(match_flag),.parity_error(parity_error_flag),
        .frame_error(frame_error_flag)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count <= 0;
            samples_count <= 0;
        end else if (b_tick) begin
            if (rx_done) begin
                bits_count <= 0;
                samples_count <= 0;
            end else if (samples_count == SC-1) begin
                samples_count <= 0;
                bits_count <= timeout_flag ? 0 : bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) & ~tx_full;
    assign rx_level_above = (rx_level > rxfifotr) | rx_full;
    assign overrun_flag = rx_full & rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module EF_UART_APB #(
