               IC=16'hff0c, GCLK=16'hff10;

    wire valid = PSEL & PENABLE;
    wire we = valid & PWRITE;
    wire re = valid & ~PWRITE;
    wire clk = PCLK;

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_thresh_reg, tx_thresh_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_below, rx_above;
    wire [MDW-1:0] rdata;
    wire brk, match, fe, pre, overrun, rto;
    wire tx_done_unused;

    wire rd = re && (PADDR[15:0] == RXDATA);
    wire wr = we && (PADDR[15:0] == TXDATA);

    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_thresh_reg <= 0;
            tx_thresh_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 0;
            if (we && PADDR[15:0] == PR) pr_reg <= PWDATA[15:0];
            if (we && PADDR[15:0] == CTRL) ctrl_reg <= PWDATA[4:0];
            if (we && PADDR[15:0] == CFG) cfg_reg <= PWDATA[13:0];
            if (we && PADDR[15:0] == MATCH) match_reg <= PWDATA[MDW-1:0];
            if (we && PADDR[15:0] == RXTHRESH) rx_thresh_reg <= PWDATA[FAW-1:0];
            if (we && PADDR[15:0] == TXTHRESH) tx_thresh_reg <= PWDATA[FAW-1:0];
            if (we && PADDR[15:0] == RXFLUSH) rx_flush_reg <= PWDATA[0];
            if (we && PADDR[15:0] == TXFLUSH) tx_flush_reg <= PWDATA[0];
            if (we && PADDR[15:0] == GCLK) gclk_reg <= PWDATA[0];
            if (we && PADDR[15:0] == IM) im_reg <= PWDATA[9:0];
            if (we && PADDR[15:0] == IC) ic_reg <= PWDATA[9:0];
        end
    end

    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 0;
        else begin
            if (ic_reg[0]) ris_reg[0] <= 0; else if (tx_empty) ris_reg[0] <= 1;
            if (ic_reg[1]) ris_reg[1] <= 0; else if (rx_full) ris_reg[1] <= 1;
            if (ic_reg[2]) ris_reg[2] <= 0; else if (tx_below) ris_reg[2] <= 1;
            if (ic_reg[3]) ris_reg[3] <= 0; else if (rx_above) ris_reg[3] <= 1;
            if (ic_reg[4]) ris_reg[4] <= 0; else if (brk) ris_reg[4] <= 1;
            if (ic_reg[5]) ris_reg[5] <= 0; else if (match) ris_reg[5] <= 1;
            if (ic_reg[6]) ris_reg[6] <= 0; else if (fe) ris_reg[6] <= 1;
            if (ic_reg[7]) ris_reg[7] <= 0; else if (pre) ris_reg[7] <= 1;
            if (ic_reg[8]) ris_reg[8] <= 0; else if (overrun) ris_reg[8] <= 1;
            if (ic_reg[9]) ris_reg[9] <= 0; else if (rto) ris_reg[9] <= 1;
        end
    end

    EF_UART #(.SC(SC),.MDW(MDW),.GFLEN(GFLEN),.FAW(FAW)) core (
        .clk(clk), .rst_n(PRESETn), .prescaler(pr_reg),
        .en(ctrl_reg[0]), .tx_en(ctrl_reg[1]), .rx_en(ctrl_reg[2]),
        .loopback_en(ctrl_reg[3]), .glitch_filter_en(ctrl_reg[4]),
        .rd(rd), .wr(wr), .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]), .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]), .timeout_bits(cfg_reg[13:8]),
        .match_data(match_reg), .txfifotr(tx_thresh_reg),
        .rxfifotr(rx_thresh_reg), .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg), .tx_empty(tx_empty),
        .tx_full(tx_full), .tx_level(tx_level),
        .tx_level_below(tx_below), .rdata(rdata),
        .rx_empty(rx_empty), .rx_full(rx_full),
        .rx_level(rx_level), .rx_level_above(rx_above),
        .break_flag(brk), .match_flag(match),
        .frame_error_flag(fe), .parity_error_flag(pre),
        .overrun_flag(overrun), .timeout_flag(rto),
        .rx(rx), .tx(tx)
    );

    assign PRDATA =
        (PADDR[15:0] == RXDATA)   ? {{(32-MDW){1'b0}},rdata} :
        (PADDR[15:0] == PR)       ? {{16{1'b0}},pr_reg} :
        (PADDR[15:0] == CTRL)     ? {{27{1'b0}},ctrl_reg} :
        (PADDR[15:0] == CFG)      ? {{18{1'b0}},cfg_reg} :
        (PADDR[15:0] == MATCH)    ? {{(32-MDW){1'b0}},match_reg} :
        (PADDR[15:0] == RXLEVEL)  ? {{(32-FAW){1'b0}},rx_level} :
        (PADDR[15:0] == RXTHRESH) ? {{(32-FAW){1'b0}},rx_thresh_reg} :
        (PADDR[15:0] == RXFLUSH)  ? {{31{1'b0}},rx_flush_reg} :
        (PADDR[15:0] == TXLEVEL)  ? {{(32-FAW){1'b0}},tx_level} :
        (PADDR[15:0] == TXTHRESH) ? {{(32-FAW){1'b0}},tx_thresh_reg} :
        (PADDR[15:0] == TXFLUSH)  ? {{31{1'b0}},tx_flush_reg} :
        (PADDR[15:0] == IM)       ? {{22{1'b0}},im_reg} :
        (PADDR[15:0] == MIS)      ? {{22{1'b0}},(ris_reg & im_reg)} :
        (PADDR[15:0] == RIS)      ? {{22{1'b0}},ris_reg} :
        (PADDR[15:0] == GCLK)     ? {{31{1'b0}},gclk_reg} :
        32'hdeadbeef;

    assign PREADY = 1'b1;
    assign IRQ = |(ris_reg & im_reg);
endmodule

