            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            if (current_state == idle_st)
                p_error_reg <= 1'b0;
            else if (p_error_next)
                p_error_reg <= 1'b1;
            if (current_state == idle_st)
                f_error_reg <= 1'b0;
            else if (f_error_next)
                f_error_reg <= 1'b1;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        p_error_next = 1'b0;
        f_error_next = 1'b0;
        rx_done = 1'b0;

        case (current_state)
            idle_st: begin
                if (!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (b_reg == (NUM_SAMPLES/2-1)) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if (count_reg == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if ((~^dout) != rx) p_error_next = 1'b1;
                            3'b010: if ((^dout) != rx)  p_error_next = 1'b1;
                            3'b100: if (rx != 1'b0)       p_error_next = 1'b1;
                            3'b101: if (rx != 1'b1)       p_error_next = 1'b1;
                            default: ;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (!rx) f_error_next = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx) f_error_next = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && (b_reg == NUM_SAMPLES-1)) begin
            if (current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = (p_error_reg | p_error_next) & rx_done;
    assign frame_error = (f_error_reg | f_error_next) & rx_done;
    assign break_flag = (brk == 12'd0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'b000;
    localparam start_st  = 3'b001;
    localparam data_st   = 3'b010;
    localparam parity_st = 3'b011;
    localparam stop0_st  = 3'b100;
    localparam stop1_st  = 3'b101;

    reg [2:0] current_state, next_state;
    reg [4:0] b_reg, b_next;
    reg [3:0] count_reg, count_next;
    reg [MDW-1:0] data_reg, data_next;
    reg tx_reg, tx_next;

    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            tx_reg <= tx_next;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        tx_next = tx_reg;
        tx_done = 1'b0;

        case (current_state)
            idle_st: begin
                tx_next = 1'b1;
                if (tx_start) begin
                    next_state = start_st;
                    b_next = 0;
                    data_next = d_in;
                end
            end

            start_st: begin
                tx_next = 1'b0;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            data_st: begin
                tx_next = data_reg[0];
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if (count_reg == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 1'b0;
                    3'b101: tx_next = 1'b1;
                    default: tx_next = 1'b0;
                endcase

                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop0_st: begin
                tx_next = 1'b1;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop1_st: begin
                tx_next = 1'b1;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    parameter MDW = 9,
    parameter GFLEN = 8,
    parameter FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_REG_OFFSET = 16'h0000;
    localparam TXDATA_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET = 16'h0008;
    localparam CTRL_REG_OFFSET = 16'h000c;
    localparam CFG_REG_OFFSET = 16'h0010;
    localparam MATCH_REG_OFFSET = 16'h001c;
    localparam RX_FIFO_LEVEL_REG_OFFSET = 16'hfe00;
    localparam RX_FIFO_THRESHOLD_REG_OFFSET = 16'hfe04;
    localparam RX_FIFO_FLUSH_REG_OFFSET = 16'hfe08;
    localparam TX_FIFO_LEVEL_REG_OFFSET = 16'hfe10;
    localparam TX_FIFO_THRESHOLD_REG_OFFSET = 16'hfe14;
    localparam TX_FIFO_FLUSH_REG_OFFSET = 16'hfe18;
    localparam IM_REG_OFFSET = 16'hff00;
    localparam MIS_REG_OFFSET = 16'hff04;
    localparam RIS_REG_OFFSET = 16'hff08;
    localparam IC_REG_OFFSET = 16'hff0c;
    localparam GCLK_REG_OFFSET = 16'hff10;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = apb_valid & PWRITE;
    wire apb_re = apb_valid & ~PWRITE;
    wire [15:0] addr = PADDR[15:0];

    wire clk = PCLK;
    wire rst_n = PRESETn;

    reg [15:0] PR_REG;
    reg [4:0] CTRL_REG;
    reg [13:0] CFG_REG;
    reg [MDW-1:0] MATCH_REG;
    reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
    reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
    reg RX_FIFO_FLUSH_REG, TX_FIFO_FLUSH_REG;
    reg GCLK_REG;
    reg [9:0] IM_REG, IC_REG, RIS_REG;

    wire [MDW-1:0] rdata;
    wire [FAW-1:0] rx_level, tx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag, parity_error_flag;
    wire overrun_flag, timeout_flag;

    wire wr = apb_we && (addr == TXDATA_REG_OFFSET);
    wire rd = apb_re && (addr == RXDATA_REG_OFFSET);

    wire rx_flush_write = apb_we && (addr == RX_FIFO_FLUSH_REG_OFFSET);
    wire tx_flush_write = apb_we && (addr == TX_FIFO_FLUSH_REG_OFFSET);
    wire rx_fifo_flush = RX_FIFO_FLUSH_REG | rx_flush_write;
    wire tx_fifo_flush = TX_FIFO_FLUSH_REG | tx_flush_write;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PR_REG <= 16'd0;
        else if (apb_we && addr == PR_REG_OFFSET)
            PR_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CTRL_REG <= 5'd0;
        else if (apb_we && addr == CTRL_REG_OFFSET)
            CTRL_REG <= PWDATA[4:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CFG_REG <= 14'h3f08;
        else if (apb_we && addr == CFG_REG_OFFSET)
            CFG_REG <= PWDATA[13:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            MATCH_REG <= 'b0;
        else if (apb_we && addr == MATCH_REG_OFFSET)
            MATCH_REG <= PWDATA[MDW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RX_FIFO_THRESHOLD_REG <= 'b0;
        else if (apb_we && addr == RX_FIFO_THRESHOLD_REG_OFFSET)
            RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            TX_FIFO_THRESHOLD_REG <= 'b0;
        else if (apb_we && addr == TX_FIFO_THRESHOLD_REG_OFFSET)
            TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            RX_FIFO_FLUSH_REG <= 1'b0;
            TX_FIFO_FLUSH_REG <= 1'b0;
        end else begin
            RX_FIFO_FLUSH_REG <= rx_flush_write ? PWDATA[0] : 1'b0;
            TX_FIFO_FLUSH_REG <= tx_flush_write ? PWDATA[0] : 1'b0;
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            GCLK_REG <= 1'b0;
        else if (apb_we && addr == GCLK_REG_OFFSET)
            GCLK_REG <= PWDATA[0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IM_REG <= 10'd0;
        else if (apb_we && addr == IM_REG_OFFSET)
            IM_REG <= PWDATA[9:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IC_REG <= 10'd0;
        else if (apb_we && addr == IC_REG_OFFSET)
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 10'd0;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 10'd0;
        else begin
            if (IC_REG[0]) RIS_REG[0] <= 1'b0;
            else if (tx_empty) RIS_REG[0] <= 1'b1;

            if (IC_REG[1]) RIS_REG[1] <= 1'b0;
            else if (rx_full) RIS_REG[1] <= 1'b1;

            if (IC_REG[2]) RIS_REG[2] <= 1'b0;
            else if (tx_level_below) RIS_REG[2] <= 1'b1;

            if (IC_REG[3]) RIS_REG[3] <= 1'b0;
            else if (rx_level_above) RIS_REG[3] <= 1'b1;

            if (IC_REG[4]) RIS_REG[4] <= 1'b0;
            else if (break_flag) RIS_REG[4] <= 1'b1;

            if (IC_REG[5]) RIS_REG[5] <= 1'b0;
            else if (match_flag) RIS_REG[5] <= 1'b1;

            if (IC_REG[6]) RIS_REG[6] <= 1'b0;
            else if (frame_error_flag) RIS_REG[6] <= 1'b1;

            if (IC_REG[7]) RIS_REG[7] <= 1'b0;
            else if (parity_error_flag) RIS_REG[7] <= 1'b1;

            if (IC_REG[8]) RIS_REG[8] <= 1'b0;
            else if (overrun_flag) RIS_REG[8] <= 1'b1;

            if (IC_REG[9]) RIS_REG[9] <= 1'b0;
            else if (timeout_flag) RIS_REG[9] <= 1'b1;
        end
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .prescaler(PR_REG),
        .en(CTRL_REG[0]),
        .tx_en(CTRL_REG[1]),
        .rx_en(CTRL_REG[2]),
        .rd(rd),
        .wr(wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(CFG_REG[3:0]),
        .stop_bits_count(CFG_REG[4]),
        .parity_type(CFG_REG[7:5]),
        .txfifotr(TX_FIFO_THRESHOLD_REG[3:0]),
        .rxfifotr(RX_FIFO_THRESHOLD_REG[3:0]),
        .match_data(MATCH_REG),
        .timeout_bits(CFG_REG[13:8]),
        .loopback_en(CTRL_REG[3]),
        .glitch_filter_en(CTRL_REG[4]),
        .tx_fifo_flush(tx_fifo_flush),
        .rx_fifo_flush(rx_fifo_flush),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA_REG_OFFSET)              ? {{(32-MDW){1'b0}}, rdata} :
        (addr == PR_REG_OFFSET)                  ? {{16{1'b0}}, PR_REG} :
        (addr == CTRL_REG_OFFSET)                ? {{27{1'b0}}, CTRL_REG} :
        (addr == CFG_REG_OFFSET)                 ? {{18{1'b0}}, CFG_REG} :
        (addr == MATCH_REG_OFFSET)               ? {{(32-MDW){1'b0}}, MATCH_REG} :
        (addr == RX_FIFO_LEVEL_REG_OFFSET)       ? {{(32-FAW){1'b0}}, rx_level} :
        (addr == RX_FIFO_THRESHOLD_REG_OFFSET)   ? {{(32-FAW){1'b0}}, RX_FIFO_THRESHOLD_REG} :
        (addr == RX_FIFO_FLUSH_REG_OFFSET)       ? {{31{1'b0}}, RX_FIFO_FLUSH_REG} :
        (addr == TX_FIFO_LEVEL_REG_OFFSET)       ? {{(32-FAW){1'b0}}, tx_level} :
        (addr == TX_FIFO_THRESHOLD_REG_OFFSET)   ? {{(32-FAW){1'b0}}, TX_FIFO_THRESHOLD_REG} :
        (addr == TX_FIFO_FLUSH_REG_OFFSET)       ? {{31{1'b0}}, TX_FIFO_FLUSH_REG} :
        (addr == IM_REG_OFFSET)                  ? {{22{1'b0}}, IM_REG} :
        (addr == MIS_REG_OFFSET)                 ? {{22{1'b0}}, (RIS_REG & IM_REG)} :
        (addr == RIS_REG_OFFSET)                 ? {{22{1'b0}}, RIS_REG} :
        (addr == GCLK_REG_OFFSET)                ? {{31{1'b0}}, GCLK_REG} :
        32'hdeadbeef;

    assign IRQ = |(RIS_REG & IM_REG);
    assign PREADY = 1'b1;
endmodule

