    always @* begin
        tmr_reg_next = tmr_reg;

        if (tmr_run && tmr_en && tick) begin
            if (tmr_cfg[1] && tmr_mode == 2'b01)
                tmr_reg_next = tmr_reload;
            else if (tmr_cfg[1] &&
                     ((tmr_mode == 2'b10) || (tmr_mode == 2'b11)))
