    wire apb_we    = apb_valid & PWRITE;

    reg         GCLK_REG;
    reg [31:0]  RELOAD_REG;
    reg [PRW-1:0] PR_REG;
    reg [31:0]  CMPX_REG;
    reg [31:0]  CMPY_REG;
