        if (!PRESETn)
            PWMDT_REG <= 8'd0;
        else if (apb_we && PADDR[15:0] == PWMDT_REG_OFFSET)
            PWMDT_REG <= PWDATA[7:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PWMFC_REG <= 16'd0;
        else if (apb_we && PADDR[15:0] == PWMFC_REG_OFFSET)
            PWMFC_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            GCLK_REG <= 1'b0;
        else if (apb_we && PADDR[15:0] == GCLK_REG_OFFSET)
            GCLK_REG <= PWDATA[0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IM_REG <= 3'd0;
        else if (apb_we && PADDR[15:0] == IM_REG_OFFSET)
            IM_REG <= PWDATA[2:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IC_REG <= 3'd0;
        else if (apb_we && PADDR[15:0] == IC_REG_OFFSET)
            IC_REG <= PWDATA[2:0];
        else
            IC_REG <= 3'd0;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'd0;
        else begin
            if (IC_REG[0])
                RIS_REG[0] <= 1'b0;
            else if (timeout_flag)
                RIS_REG[0] <= 1'b1;

            if (IC_REG[1])
                RIS_REG[1] <= 1'b0;
            else if (matchx_flag)
                RIS_REG[1] <= 1'b1;

            if (IC_REG[2])
                RIS_REG[2] <= 1'b0;
            else if (matchy_flag)
                RIS_REG[2] <= 1'b1;
        end
    end

    wire [2:0] MIS = RIS_REG & IM_REG;

    /*
     * GCLK is intentionally stored only.  The specified build uses
     * an ungated clock, so the timer always runs from PCLK.
     */
    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk(PCLK),
        .rst_n(PRESETn),
        .tmr_en(CTRL_REG[0]),
        .tmr_start(CTRL_REG[1]),
        .pwm0_en(CTRL_REG[2]),
        .pwm1_en(CTRL_REG[3]),
        .tmr_reload(RELOAD_REG),
        .cmpx(CMPX_REG),
        .cmpy(CMPY_REG),
