    wire rx_filtered;
    wire rx_input;
    wire baud_tick;
    wire tx_done;
    wire rx_done;
    wire [MDW-1:0] tx_data;
    wire [MDW-1:0] rx_data;

    ef_util_sync rx_synchronizer (
        .clk(clk), .in(rx), .out(rx_sync)
    );

    ef_util_glitch_filter #(.N(GFLEN)) glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_sync),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_input = loopback_en ? tx :
                      glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud_generator (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC), .MDW(MDW)) transmitter (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(baud_tick & tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.NUM_SAMPLES(SC), .MDW(MDW)) receiver (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(baud_tick & rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .rx(rx_input),
        .match_data(match_data),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
