    wire do_wr = wr & ~full_reg;
    wire do_rd = rd & ~empty_reg;

    always @(posedge clk) begin
        if (do_wr)
            mem[wptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= 'b0;
            rptr <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
