                2'b01: begin
                    rptr <= rptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg <= 1'b0;
                    if ((rptr + 1'b1) == wptr)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    wptr <= wptr + 1'b1;
                    rptr <= rptr + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;
    assign rdata = mem[rptr];
