        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_tx_reg = tx_reg;
        tx_done = 1'b0;

        case (state)
            IDLE: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state = START;
                    next_sample_count = 0;
                    next_bit_count = 0;
                    next_data_reg = d_in;
                end
            end

            START: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state = DATA;
                        next_sample_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = STOP0;
                            else
                                next_state = PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^parity_data;
                    3'b010: next_tx_reg = ^parity_data;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b0;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                   PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    wire [MDW-1:0] received_data =
        data_reg >> (MDW - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_error_reg <= 0;
            frame_error_reg <= 0;
            break_shift <= 12'hfff;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            parity_error_reg <= next_parity_error;
            frame_error_reg <= next_frame_error;

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    break_shift <= 12'hfff;
                else
                    break_shift <= {break_shift[10:0], rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_parity_error = parity_error_reg;
        next_frame_error = frame_error_reg;
        rx_done = 1'b0;

        if (state == IDLE) begin
            next_parity_error = 1'b0;
            next_frame_error = 1'b0;
        end

        case (state)
            IDLE: begin
                if (b_tick && !rx) begin
                    next_state = START;
                    next_sample_count = 0;
                end
            end

            START: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = STOP0;
                            else
                                next_state = PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                        case (parity_type)
                            3'b001:
                                if ((~^received_data) != rx)
                                    next_parity_error = 1'b1;
                            3'b010:
                                if ((^received_data) != rx)
                                    next_parity_error = 1'b1;
                            3'b100:
                                if (rx != 1'b0)
                                    next_parity_error = 1'b1;
                            3'b101:
                                if (rx != 1'b1)
                                    next_parity_error = 1'b1;
                            default: begin
                            end
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx)
                            next_frame_error = 1'b1;

                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign dout = received_data;
    assign parity_error = rx_done && (parity_error_reg | next_parity_error);
    assign frame_error = rx_done && (frame_error_reg | next_frame_error);
    assign match_flag = rx_done && (received_data == match_data);
    assign break_flag = (break_shift == 12'b0);
endmodule

module EF_UART #(
    parameter MDW=9,
    parameter FAW=4,
    parameter SC=8,
    parameter GFLEN=8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire rx_sync;
    wire rx_filtered;
    wire rx_input;
    wire baud_tick;
    wire tx_done;
    wire rx_done;
    wire [MDW-1:0] tx_data;
    wire [MDW-1:0] rx_data;

    ef_util_sync rx_synchronizer (
        .clk(clk), .in(rx), .out(rx_sync)
    );

    ef_util_glitch_filter #(.N(GFLEN)) glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_sync),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_input = loopback_en ? tx :
                      glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud_generator (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC), .MDW(MDW)) transmitter (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(baud_tick & tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.NUM_SAMPLES(SC), .MDW(MDW)) receiver (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(baud_tick & rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .rx(rx_input),
        .match_data(match_data),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [4:0] timeout_samples;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            timeout_samples <= 0;
        end else if (rx_done) begin
            timeout_count <= 0;
            timeout_samples <= 0;
        end else if (baud_tick) begin
            if (timeout_samples == SC-1) begin
                timeout_samples <= 0;
                if (timeout_flag)
                    timeout_count <= 0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else
                timeout_samples <= timeout_samples + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_done && rx_full;
    assign timeout_flag = (timeout_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC=8,
    parameter MDW=9,
    parameter GFLEN=8,
    parameter FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA = 16'h0000;
    localparam TXDATA = 16'h0004;
    localparam PR = 16'h0008;
    localparam CTRL = 16'h000c;
    localparam CFG = 16'h0010;
    localparam MATCH = 16'h001c;
    localparam RX_LEVEL = 16'hfe00;
    localparam RX_THRESHOLD = 16'hfe04;
    localparam RX_FLUSH = 16'hfe08;
    localparam TX_LEVEL = 16'hfe10;
    localparam TX_THRESHOLD = 16'hfe14;
    localparam TX_FLUSH = 16'hfe18;
    localparam IM = 16'hff00;
    localparam MIS = 16'hff04;
    localparam RIS = 16'hff08;
    localparam IC = 16'hff0c;
    localparam GCLK = 16'hff10;

    wire apb_write = PSEL & PENABLE & PWRITE;
    wire apb_read = PSEL & PENABLE & ~PWRITE;
    wire [15:0] addr = PADDR[15:0];

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg;
    reg [FAW-1:0] tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire tx_empty, tx_full, tx_level_below;
    wire rx_empty, rx_full, rx_level_above;
    wire [FAW-1:0] tx_level, rx_level;
    wire [MDW-1:0] rx_data;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire tx_write = apb_write && (addr == TXDATA);
    wire rx_read = apb_read && (addr == RXDATA);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_threshold_reg <= 0;
            tx_threshold_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 10'b0;

            if (apb_write && addr == PR)
                pr_reg <= PWDATA[15:0];
            if (apb_write && addr == CTRL)
                ctrl_reg <= PWDATA[4:0];
            if (apb_write && addr == CFG)
                cfg_reg <= PWDATA[13:0];
            if (apb_write && addr == MATCH)
                match_reg <= PWDATA[MDW-1:0];
            if (apb_write && addr == RX_THRESHOLD)
                rx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_write && addr == TX_THRESHOLD)
                tx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_write && addr == RX_FLUSH)
                rx_flush_reg <= PWDATA[0];
            if (apb_write && addr == TX_FLUSH)
                tx_flush_reg <= PWDATA[0];
            if (apb_write && addr == GCLK)
                gclk_reg <= PWDATA[0];
            if (apb_write && addr == IM)
                im_reg <= PWDATA[9:0];
            if (apb_write && addr == IC)
                ic_reg <= PWDATA[9:0];
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else begin
            if (ic_reg[0]) ris_reg[0] <= 1'b0;
            else if (tx_empty) ris_reg[0] <= 1'b1;

            if (ic_reg[1]) ris_reg[1] <= 1'b0;
            else if (rx_full) ris_reg[1] <= 1'b1;

            if (ic_reg[2]) ris_reg[2] <= 1'b0;
            else if (tx_level_below) ris_reg[2] <= 1'b1;

            if (ic_reg[3]) ris_reg[3] <= 1'b0;
            else if (rx_level_above) ris_reg[3] <= 1'b1;

            if (ic_reg[4]) ris_reg[4] <= 1'b0;
            else if (break_flag) ris_reg[4] <= 1'b1;

            if (ic_reg[5]) ris_reg[5] <= 1'b0;
            else if (match_flag) ris_reg[5] <= 1'b1;

            if (ic_reg[6]) ris_reg[6] <= 1'b0;
            else if (frame_error_flag) ris_reg[6] <= 1'b1;

            if (ic_reg[7]) ris_reg[7] <= 1'b0;
            else if (parity_error_flag) ris_reg[7] <= 1'b1;

            if (ic_reg[8]) ris_reg[8] <= 1'b0;
            else if (overrun_flag) ris_reg[8] <= 1'b1;

            if (ic_reg[9]) ris_reg[9] <= 1'b0;
            else if (timeout_flag) ris_reg[9] <= 1'b1;
        end
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) uart (
        .clk(PCLK),
        .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]),
        .rx_en(ctrl_reg[2]),
        .rd(rx_read),
        .wr(tx_write),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_threshold_reg),
        .rxfifotr(rx_threshold_reg),
        .match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rx_data),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA)      ? {{(32-MDW){1'b0}}, rx_data} :
        (addr == PR)         ? {{16{1'b0}}, pr_reg} :
        (addr == CTRL)       ? {{27{1'b0}}, ctrl_reg} :
        (addr == CFG)        ? {{18{1'b0}}, cfg_reg} :
        (addr == MATCH)      ? {{(32-MDW){1'b0}}, match_reg} :
        (addr == RX_LEVEL)   ? {{(32-FAW){1'b0}}, rx_level} :
        (addr == RX_THRESHOLD) ? {{(32-FAW){1'b0}}, rx_threshold_reg} :
        (addr == RX_FLUSH)   ? {{31{1'b0}}, rx_flush_reg} :
        (addr == TX_LEVEL)   ? {{(32-FAW){1'b0}}, tx_level} :
        (addr == TX_THRESHOLD) ? {{(32-FAW){1'b0}}, tx_threshold_reg} :
        (addr == TX_FLUSH)   ? {{31{1'b0}}, tx_flush_reg} :
        (addr == IM)         ? {{22{1'b0}}, im_reg} :
        (addr == MIS)        ? {{22{1'b0}}, (ris_reg & im_reg)} :
        (addr == RIS)        ? {{22{1'b0}}, ris_reg} :
        (addr == GCLK)       ? {{31{1'b0}}, gclk_reg} :
        32'hdeadbeef;

    assign IRQ = |(ris_reg & im_reg);
    assign PREADY = 1'b1;
endmodule

