    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&{shifter[N-2:0], in})
                out <= 1'b1;
            else if (!(|{shifter[N-2:0], in}))
                out <= 1'b0;
        end
