module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk, input wire in, output wire out
);
    reg [NUM_STAGES-1:0] sync;
    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0],in};
    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;
    wire zero = (counter == 'b0);
    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            counter <= 'b0;
        else if (en)
            counter <= zero ? clk_div : counter - 1'b1;

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            tick_reg <= 1'b0;
        else if (en)
            tick_reg <= (clk_div == 'b0) ? 1'b1 : zero;
        else
            tick_reg <= 1'b0;

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;
    ef_util_ticker #(.W(8)) ticker (
        .clk(clk), .rst_n(rst_n), .en(en), .clk_div(CLKDIV), .tick(tick)
    );
    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            shifter <= 'b0;
        else if (tick)
            shifter <= {shifter[N-2:0],in};

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            out <= 1'b0;
        else if (&shifter)
            out <= 1'b1;
        else if (~|shifter)
            out <= 1'b0;
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;
    reg [DW-1:0] array_reg [0:DEPTH-1];
    reg [AW-1:0] w_ptr_reg, r_ptr_reg, level_reg;
    reg full_reg, empty_reg;
    reg [AW-1:0] w_ptr_next, r_ptr_next, level_next;
    reg full_next, empty_next;
    wire w_en = wr & ~full_reg;

    always @(posedge clk)
        if (w_en)
            array_reg[w_ptr_reg] <= wdata;

    assign rdata = array_reg[r_ptr_reg];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;

    always @* begin
        w_ptr_next = w_ptr_reg;
        r_ptr_next = r_ptr_reg;
        level_next = level_reg;
        full_next = full_reg;
        empty_next = empty_reg;

        case ({w_en,rd})
            2'b01: begin
                if (!empty_reg) begin
                    r_ptr_next = r_ptr_reg + 1'b1;
                    full_next = 1'b0;
                    level_next = level_reg - 1'b1;
                    if (r_ptr_reg + 1'b1 == w_ptr_reg)
                        empty_next = 1'b1;
                end
            end
            2'b10: begin
                if (!full_reg) begin
                    w_ptr_next = w_ptr_reg + 1'b1;
                    empty_next = 1'b0;
                    level_next = level_reg + 1'b1;
                    if (w_ptr_reg + 1'b1 == r_ptr_reg)
