module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] counter;

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            counter <= 16'd0;
        else if (en)
            if (counter == prescale)
                counter <= 16'd0;
            else
                counter <= counter + 16'd1;
        else
            counter <= 16'd0;

    assign baudtick = en && (counter == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010,
               parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg p_error_reg, p_error_next, f_error_reg, f_error_next;
    reg [11:0] brk;

    always @(posedge clk or negedge resetn)
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            if (current_state == idle_st)
                p_error_reg <= 1'b0;
            else if (p_error_next)
                p_error_reg <= 1'b1;
            if (current_state == idle_st)
                f_error_reg <= 1'b0;
            else if (f_error_next)
                f_error_reg <= 1'b1;
        end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        rx_done = 1'b0;
        p_error_next = 1'b0;
        f_error_next = 1'b0;

        case (current_state)
            idle_st:
                if (!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end

            start_st:
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES/2-1)) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;

            data_st:
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = {rx,data_reg[MDW-1:1]};
                        if (count_reg == data_size-1)
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;

            parity_st:
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if ((~^dout) != rx) p_error_next = 1'b1;
                            3'b010: if ((^dout) != rx)  p_error_next = 1'b1;
                            3'b100: if (rx != 1'b0)      p_error_next = 1'b1;
                            3'b101: if (rx != 1'b1)      p_error_next = 1'b1;
                            default: ;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;

            stop0_st:
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (!rx) f_error_next = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;

            stop1_st:
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx) f_error_next = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            default:
                next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn)
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && b_reg == NUM_SAMPLES-1)
            if (current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0],rx};

    assign dout = data_reg >> (9-data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 12'b0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010,
               parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg tx_reg, tx_next;
    wire [MDW-1:0] pdata = d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn)
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            tx_reg <= tx_next;
        end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        tx_next = tx_reg;
        tx_done = 1'b0;

        case (current_state)
            idle_st: begin
                tx_next = 1'b1;
                if (tx_start) begin
                    next_state = start_st;
                    b_next = 0;
                    data_next = d_in;
                end
            end

            start_st: begin
                tx_next = 1'b0;
                if (b_tick)
                    if (b_reg == NUM_SAMPLES) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
            end

            data_st: begin
                tx_next = data_reg[0];
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if (count_reg == data_size-1)
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end

            parity_st: begin
                case (parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 1'b0;
                    3'b101: tx_next = 1'b1;
                    default: tx_next = 1'b0;
                endcase
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop0_st: begin
                tx_next = 1'b1;
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop1_st: begin
                tx_next = 1'b1;
                if (b_tick)
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end

            default:
                next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART #(parameter MDW=9, FAW=4, SC=8, GFLEN=8) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr, input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en, input wire glitch_filter_en,
    input wire tx_fifo_flush, input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire b_tick, tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_synched, rx_filtered, rx_in;

    ef_util_sync rx_sync (.clk(clk),.in(rx),.out(rx_synched));
    ef_util_glitch_filter #(.N(GFLEN)) rx_filter (
        .clk(clk),.rst_n(rst_n),.in(rx_synched),
        .en(glitch_filter_en),.out(rx_filtered)
    );
    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_synched;

    BAUDGEN baud_gen (
        .clk(clk),.rst_n(rst_n),.prescale(prescaler),
        .en(en),.baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(tx_done),.wr(wr),
        .flush(tx_fifo_flush),.wdata(wdata),.empty(tx_empty),
        .full(tx_full),.rdata(tx_data),.level(tx_level)
    );

    UART_TX #(.MDW(MDW),.NUM_SAMPLES(SC)) transmitter (
        .clk(clk),.resetn(rst_n),.tx_start(~tx_empty),
        .b_tick(b_tick & tx_en),.data_size(data_size),
        .parity_type(parity_type),.stop_bits_count(stop_bits_count),
        .d_in(tx_data),.tx_done(tx_done),.tx(tx)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) rx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(rd),.wr(rx_done),
        .flush(rx_fifo_flush),.wdata(rx_data),.empty(rx_empty),
        .full(rx_full),.rdata(rdata),.level(rx_level)
    );

    UART_RX #(.MDW(MDW),.NUM_SAMPLES(SC)) receiver (
        .clk(clk),.resetn(rst_n),.b_tick(b_tick & rx_en),
        .data_size(data_size),.parity_type(parity_type),
        .stop_bits_count(stop_bits_count),.match_data(match_data),
        .rx(rx_in),.break_flag(break_flag),.match_flag(match_flag),
        .parity_error(parity_error_flag),.frame_error(frame_error_flag),
        .rx_done(rx_done),.dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            bits_count <= 0;
            samples_count <= 0;
        end else if (b_tick)
            if (rx_done) begin
                bits_count <= 0;
                samples_count <= 0;
            end else if (samples_count == SC-1) begin
                samples_count <= 0;
                if (timeout_flag)
                    bits_count <= 0;
                else
                    bits_count <= bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;

    assign tx_level_below = (tx_level < txfifotr) & ~tx_full;
    assign rx_level_above = (rx_level > rxfifotr) | rx_full;
    assign overrun_flag = rx_full & rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC=8, MDW=9, GFLEN=8, FAW=4
) (
    input wire PCLK, input wire PRESETn,
    input wire PWRITE, input wire [31:0] PWDATA,
    input wire [31:0] PADDR, input wire PENABLE, input wire PSEL,
    output wire PREADY, output wire [31:0] PRDATA, output wire IRQ,
    input wire [0:0] rx, output wire [0:0] tx
