    wire wr = apb_we && (PADDR[15:0] == TXDATA);

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PR_REG <= 0;
        else if (apb_we && PADDR[15:0] == PR) PR_REG <= PWDATA[15:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CTRL_REG <= 0;
        else if (apb_we && PADDR[15:0] == CTRL) CTRL_REG <= PWDATA[4:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CFG_REG <= 14'h3f08;
        else if (apb_we && PADDR[15:0] == CFG) CFG_REG <= PWDATA[13:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) MATCH_REG <= 0;
        else if (apb_we && PADDR[15:0] == MATCH) MATCH_REG <= PWDATA[MDW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) RX_THRESH_REG <= 0;
        else if (apb_we && PADDR[15:0] == RX_THRESH)
            RX_THRESH_REG <= PWDATA[FAW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) TX_THRESH_REG <= 0;
        else if (apb_we && PADDR[15:0] == TX_THRESH)
            TX_THRESH_REG <= PWDATA[FAW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) RX_FLUSH_REG <= 0;
        else if (apb_we && PADDR[15:0] == RX_FLUSH)
            RX_FLUSH_REG <= PWDATA[0];
        else
            RX_FLUSH_REG <= 0;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) TX_FLUSH_REG <= 0;
        else if (apb_we && PADDR[15:0] == TX_FLUSH)
            TX_FLUSH_REG <= PWDATA[0];
        else
            TX_FLUSH_REG <= 0;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) GCLK_REG <= 0;
        else if (apb_we && PADDR[15:0] == GCLK)
            GCLK_REG <= PWDATA[0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) IM_REG <= 0;
        else if (apb_we && PADDR[15:0] == IM)
