        match_flag, break_flag, rx_level_above, tx_level_below,
        rx_full, tx_empty
    };

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn)
            RIS_REG <= 0;
        else
            RIS_REG <= (RIS_REG & ~IC_REG) | raw_status;

    wire [9:0] MIS_REG = RIS_REG & IM_REG;

    EF_UART #(.SC(SC),.MDW(MDW),.GFLEN(GFLEN),.FAW(FAW)) uart (
        .clk(clk_g), .rst_n(PRESETn),
        .prescaler(PR_REG),
        .en(CTRL_REG[0]), .tx_en(CTRL_REG[1]), .rx_en(CTRL_REG[2]),
        .rd(rd), .wr(wr), .wdata(PWDATA[MDW-1:0]),
        .data_size(CFG_REG[3:0]), .stop_bits_count(CFG_REG[4]),
        .parity_type(CFG_REG[7:5]), .timeout_bits(CFG_REG[13:8]),
        .txfifotr(TX_THRESH_REG), .rxfifotr(RX_THRESH_REG),
        .match_data(MATCH_REG), .loopback_en(CTRL_REG[3]),
