        (PADDR[15:0] == CTRL)      ? CTRL_REG :
        (PADDR[15:0] == CFG)       ? CFG_REG :
        (PADDR[15:0] == MATCH)     ? MATCH_REG :
        (PADDR[15:0] == RX_LEVEL)  ? rx_level :
        (PADDR[15:0] == RX_THRESH) ? RX_THRESH_REG :
        (PADDR[15:0] == RX_FLUSH)  ? RX_FLUSH_REG :
        (PADDR[15:0] == TX_LEVEL)  ? tx_level :
        (PADDR[15:0] == TX_THRESH) ? TX_THRESH_REG :
        (PADDR[15:0] == TX_FLUSH)  ? TX_FLUSH_REG :
        (PADDR[15:0] == IM)        ? IM_REG :
