module EF_TMR32 #(
    parameter PRW = 16,
    parameter PWM_FAULT_CLR_C0 = 16'hA539,
    parameter PWM_FAULT_CLR_C1 = 16'hA953
) (
    input   wire            clk,
    input   wire            rst_n,
    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [2:0]      tmr_cfg,
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [7:0]      pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,
    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,
    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);

    wire [1:0] tmr_mode = tmr_cfg[1:0];
    wire       tmr_periodic = tmr_cfg[2];

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg tmr_run;
    reg tmr_dir;
    reg fault_reg;

    wire tmr_clr;
    wire tmr_en_pulse = tmr_clr;

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(tmr_clr)
    );

    wire tick = (pr_reg == 0);

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            pr_reg <= 1;
        else if (tmr_en) begin
            if (tick)
                pr_reg <= prescaler;
            else
                pr_reg <= pr_reg - 1;
        end else
            pr_reg <= prescaler;
    end

    wire tmr_eq_reload     = (tmr == tmr_reload);
    wire tmr_eq_zero       = (tmr == 0);
    wire tmr_eq_reload_m_1 = (tmr == (tmr_reload - 1));
    wire tmr_eq_one        = (tmr == 1);
    wire tmr_eq_cmpx       = (tmr == cmpx);
    wire tmr_eq_cmpy       = (tmr == cmpy);

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            tmr_run <= 0;
        else if (tmr_en_pulse)
            tmr_run <= 1;
        else if (~tmr_periodic & tick) begin
            if ((tmr_mode[0] == 1'b1) & tmr_eq_one & ~tmr_dir)
                tmr_run <= 0;
            else if ((tmr_mode == 2'b10) & tmr_eq_reload_m_1 & tmr_dir)
                tmr_run <= 1;
        end
    end

    reg [31:0] tmr_reg_next;

    always @* begin
        tmr_reg_next = tmr_reg;

        if (!tmr_run)
            tmr_reg_next = tmr_reg;
        else if (tmr_start && (tmr_mode == 2'b01))
            tmr_reg_next = tmr_reload;
        else if (tmr_start && ((tmr_mode == 2'b10) ||
                              (tmr_mode == 2'b11)))
            tmr_reg_next = 0;
        else if (tmr_mode == 2'b11) begin
            if (tmr_dir)
                tmr_reg_next = tmr_reg + 1;
            else
                tmr_reg_next = tmr_reg - 1;
        end
        else if (tmr_mode == 2'b01) begin
            if (tmr_eq_zero)
                tmr_reg_next = tmr_periodic ? tmr_reload : tmr_reg;
            else
                tmr_reg_next = tmr_reg - 1;
        end
        else if (tmr_mode == 2'b10) begin
            if (tmr_eq_reload)
                tmr_reg_next = tmr_periodic ? 0 : tmr_reg;
            else
                tmr_reg_next = tmr_reg + 1;
        end
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            tmr_reg <= 0;
        else if (tmr_en) begin
            if (tmr_clr) begin
                if (tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else
                    tmr_reg <= 0;
            end
            else if (tick)
                tmr_reg <= tmr_reg_next;
        end
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            tmr_dir <= 1;
        else if (tmr_clr) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 0;
            else
                tmr_dir <= 1;
        end
        else if (tick) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_eq_one && ~tmr_dir)
                    tmr_dir <= 1;
                else if (tmr_eq_reload_m_1 && tmr_dir)
                    tmr_dir <= 0;
            end
            else if (tmr_mode == 2'b10)
                tmr_dir <= 1'b1;
            else if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end
    end

    function automatic pwm_action;
        input [1:0] action;
        input       sig;
        begin
            case (action)
                2'b00: pwm_action = sig;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                2'b11: pwm_action = ~sig;
            endcase
        end
    endfunction

    reg pwm0_reg, pwm0_reg_next;
    reg pwm1_reg, pwm1_reg_next;

    always @* begin
        casez ({tmr_dir, tmr_eq_zero, tmr_eq_cmpx,
               tmr_eq_cmpy, tmr_eq_reload})
            5'b?_1_00_0: pwm0_reg_next = pwm_action(pwm0_cfg[1:0],   pwm0_reg);
            5'b1_0_10_0: pwm0_reg_next = pwm_action(pwm0_cfg[3:2],   pwm0_reg);
            5'b1_0_01_0: pwm0_reg_next = pwm_action(pwm0_cfg[5:4],   pwm0_reg);
            5'b?_0_00_1: pwm0_reg_next = pwm_action(pwm0_cfg[7:6],   pwm0_reg);
            5'b0_0_01_0: pwm0_reg_next = pwm_action(pwm0_cfg[9:8],   pwm0_reg);
            5'b0_0_10_0: pwm0_reg_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
            default:     pwm0_reg_next = pwm0_reg;
        endcase
    end

    always @* begin
        casez ({tmr_dir, tmr_eq_zero, tmr_eq_cmpx,
               tmr_eq_cmpy, tmr_eq_reload})
            5'b?_1_00_0: pwm1_reg_next = pwm_action(pwm1_cfg[1:0],   pwm1_reg);
            5'b1_0_10_0: pwm1_reg_next = pwm_action(pwm1_cfg[3:2],   pwm1_reg);
            5'b1_0_01_0: pwm1_reg_next = pwm_action(pwm1_cfg[5:4],   pwm1_reg);
            5'b?_0_00_1: pwm1_reg_next = pwm_action(pwm1_cfg[7:6],   pwm1_reg);
            5'b0_0_01_0: pwm1_reg_next = pwm_action(pwm1_cfg[9:8],   pwm1_reg);
            5'b0_0_10_0: pwm1_reg_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
            default:     pwm1_reg_next = pwm1_reg;
        endcase
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            pwm0_reg <= 0;
        else if (pwm0_en && tick) begin
            if (pwm_fault)
                pwm0_reg <= 0;
            else
                pwm0_reg <= pwm0_reg_next;
        end
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            pwm1_reg <= 0;
        else if (pwm1_en && tick) begin
            if (pwm_fault)
                pwm1_reg <= 0;
            else
                pwm1_reg <= pwm1_reg_next;
        end
    end

    reg pwm0_delayed;
    reg [7:0] dly_cntr;

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            dly_cntr <= 0;
        else if (tick) begin
            if (dly_cntr == 0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1;
        end
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            pwm0_delayed <= 0;
        else if (tick && (dly_cntr == 0))
            pwm0_delayed <= pwm0_reg;
    end

    reg pwm0_w_dt, pwm1_w_dt;

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            pwm0_w_dt <= 0;
        else
            pwm0_w_dt <= pwm_dt_en ? (pwm0_delayed & pwm0_reg) : pwm0_reg;
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            pwm1_w_dt <= 0;
        else
            pwm1_w_dt <= pwm_dt_en ? (~pwm0_delayed & ~pwm0_reg) : pwm1_reg;
    end

    reg fault_clr_reg;

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            fault_clr_reg <= 0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_clr_reg <= 1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_clr_reg <= 0;
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 0;
        else if (pwm_fault)
            fault_reg <= 1;
        else if (fault_clr_reg &&
                 (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 0;
    end

    assign tmr          = tmr_reg;
    assign pwm0         = (pwm0_w_dt ^ pwm0_inv) && ~fault_reg && pwm0_en;
    assign pwm1         = (pwm1_w_dt ^ pwm1_inv) && ~fault_reg && pwm1_en;
    assign matchx_flag  = tmr_eq_cmpx;
    assign matchy_flag  = tmr_eq_cmpy;
    assign timeout_flag = tmr_dir ? tmr_eq_reload : tmr_eq_zero;

endmodule

module EF_TMR32_APB #(
    parameter PRW = 16
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [31:0]  PWDATA,
    input  wire [31:0]  PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [31:0]  PRDATA,
    output wire         IRQ,
    output wire [1-1:0] pwm0,
    output wire [1-1:0] pwm1,
    input  wire [1-1:0] pwm_fault
);

    reg [31:0] reload_reg;
    reg [PRW-1:0] pr_reg;
    reg [31:0] cmpx_reg;
    reg [31:0] cmpy_reg;
    reg [6:0] ctrl_reg;
    reg [2:0] cfg_reg;
    reg [11:0] pwm0cfg_reg;
    reg [15:0] pwm1cfg_reg;
    reg [7:0] pwmdt_reg;
    reg [15:0] pwmfc_reg;
    reg [2:0] im_reg;
    reg [0:0] gclk_reg;
    reg [2:0] ic_reg;

    wire apb_write = PSEL && PENABLE && PWRITE;

    wire [31:0] tmr_value;
    wire matchx_flag;
    wire matchy_flag;
    wire timeout_flag;

    wire [2:0] ris;
    wire [2:0] mis;

    EF_TMR32 #(
        .PRW(PRW)
    ) timer_core (
        .clk           (PCLK),
        .rst_n         (PRESETn),
        .tmr_en        (ctrl_reg[0]),
        .tmr_start     (ctrl_reg[1]),
        .pwm0_en       (ctrl_reg[2]),
        .pwm1_en       (ctrl_reg[3]),
        .tmr_reload    (reload_reg),
        .cmpx          (cmpx_reg),
        .cmpy          (cmpy_reg),
        .prescaler     (pr_reg),
        .tmr_cfg       (cfg_reg),
        .pwm0_cfg      (pwm0cfg_reg),
        .pwm1_cfg      (pwm1cfg_reg[11:0]),
        .pwm0_inv      (ctrl_reg[5]),
        .pwm1_inv      (ctrl_reg[6]),
        .pwm_dt        (pwmdt_reg),
        .pwm_fault_clr (pwmfc_reg),
        .pwm_dt_en     (ctrl_reg[4]),
        .tmr           (tmr_value),
        .matchx_flag   (matchx_flag),
        .matchy_flag   (matchy_flag),
        .timeout_flag  (timeout_flag),
        .pwm_fault     (pwm_fault[0]),
        .pwm0          (pwm0[0]),
        .pwm1          (pwm1[0])
    );

    assign ris = {matchy_flag, matchx_flag, timeout_flag};
    assign mis = ris & im_reg;
    assign IRQ = |mis;
    assign PREADY = 1'b1;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            reload_reg  <= 32'b0;
            pr_reg      <= {PRW{1'b0}};
            cmpx_reg    <= 32'b0;
            cmpy_reg    <= 32'b0;
            ctrl_reg    <= 7'b0;
            cfg_reg     <= 3'b0;
            pwm0cfg_reg <= 12'b0;
            pwm1cfg_reg <= 16'b0;
            pwmdt_reg   <= 8'b0;
            pwmfc_reg   <= 16'b0;
            im_reg      <= 3'b0;
            gclk_reg    <= 1'b0;
            ic_reg      <= 3'b0;
        end
        else begin
            ic_reg <= 3'b0;

            if (apb_write) begin
                case (PADDR[15:0])
                    16'h0004: reload_reg  <= PWDATA;
                    16'h0008: pr_reg      <= PWDATA[PRW-1:0];
                    16'h000C: cmpx_reg    <= PWDATA;
                    16'h0010: cmpy_reg    <= PWDATA;
                    16'h0014: ctrl_reg    <= PWDATA[6:0];
                    16'h0018: cfg_reg     <= PWDATA[2:0];
                    16'h001C: pwm0cfg_reg <= PWDATA[11:0];
                    16'h0020: pwm1cfg_reg <= PWDATA[15:0];
                    16'h0024: pwmdt_reg   <= PWDATA[7:0];
                    16'h0028: pwmfc_reg   <= PWDATA[15:0];
                    16'hFF00: im_reg      <= PWDATA[2:0];
                    16'hFF0C: ic_reg      <= PWDATA[2:0];
                    16'hFF10: gclk_reg    <= PWDATA[0];
                    default: ;
                endcase
            end
        end
    end

    reg [2:0] ris_reg;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 3'b0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | ris;
    end

    assign mis = ris_reg & im_reg;
    assign IRQ = |mis;

    always @* begin
        case (PADDR[15:0])
            16'h0000: PRDATA = tmr_value;
            16'h0004: PRDATA = reload_reg;
            16'h0008: PRDATA = {{(32-PRW){1'b0}}, pr_reg};
            16'h000C: PRDATA = cmpx_reg;
            16'h0010: PRDATA = cmpy_reg;
            16'h0014: PRDATA = {{25{1'b0}}, ctrl_reg};
            16'h0018: PRDATA = {{29{1'b0}}, cfg_reg};
            16'h001C: PRDATA = {{20{1'b0}}, pwm0cfg_reg};
            16'h0020: PRDATA = {{16{1'b0}}, pwm1cfg_reg};
            16'h0024: PRDATA = {{24{1'b0}}, pwmdt_reg};
            16'h0028: PRDATA = {{16{1'b0}}, pwmfc_reg};
            16'hFF00: PRDATA = {{29{1'b0}}, im_reg};
            16'hFF04: PRDATA = {{29{1'b0}}, mis};
            16'hFF08: PRDATA = {{29{1'b0}}, ris_reg};
            16'hFF10: PRDATA = {{31{1'b0}}, gclk_reg};
            default:  PRDATA = 32'hDEADBEEF;
        endcase
    end

endmodule

