module ef_util_ticker #(parameter W=8) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [W-1:0] clk_div,
    output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 'b0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (clk_div == 'b0) || (counter == 'b0);
            if (counter == 'b0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk,
    input wire rst_n,
    input wire in,
    input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&shifter)
                out <= 1'b1;
            else if (~|shifter)
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk,
    input wire rst_n,
    input wire rd,
    input wire wr,
    input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty,
    output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam integer DEPTH = (1 << AW);

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rptr;
    reg [AW-1:0] wptr;
    reg [AW:0] count;

    wire do_rd = rd && !empty;
    wire do_wr = wr && !full;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr <= 'b0;
            wptr <= 'b0;
            count <= 'b0;
        end else if (flush) begin
            rptr <= 'b0;
            wptr <= 'b0;
            count <= 'b0;
        end else begin
            if (do_wr) begin
                mem[wptr] <= wdata;
                wptr <= wptr + 1'b1;
            end
            if (do_rd)
                rptr <= rptr + 1'b1;

            case ({do_wr,do_rd})
                2'b10: count <= count + 1'b1;
                2'b01: count <= count - 1'b1;
                default: count <= count;
            endcase
        end
    end

    assign rdata = mem[rptr];
    assign empty = (count == 0);
    assign full = (count == DEPTH);
    assign level = count[AW-1:0];
endmodule

