module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire parity_bit =
        (parity_type == 3'b001) ? ~(^data_reg) :
        (parity_type == 3'b010) ?  (^data_reg) :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b1;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
            tx_done <= 1'b0;
        end else begin
            tx_done <= 1'b0;

            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        data_reg <= d_in;
                        bit_count <= 0;
                        sample_count <= 0;
                        state <= START;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg <= data_reg >> 1;
                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    tx_reg <= parity_bit;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            tx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_bad;
    reg frame_bad;
    reg [11:0] break_reg;

    wire expected_parity =
        (parity_type == 3'b001) ? ~(^data_reg) :
        (parity_type == 3'b010) ?  (^data_reg) :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_bad <= 0;
            frame_bad <= 0;
            break_reg <= 12'hfff;
            rx_done <= 1'b0;
        end else begin
            rx_done <= 1'b0;

            if (b_tick && (sample_count == NUM_SAMPLES-1) &&
                (state != IDLE))
                break_reg <= {break_reg[10:0],rx};

            case (state)
                IDLE: begin
                    sample_count <= 0;
                    parity_bad <= 0;
                    frame_bad <= 0;
                    break_reg <= 12'hfff;
                    if (b_tick && !rx) begin
                        state <= START;
                        sample_count <= 0;
                    end
                end

                START: begin
                    if (b_tick) begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg <= {rx,data_reg[MDW-1:1]};
                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= STOP0;
                                else
                                    state <= PARITY;
