module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010,
               parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg p_error_reg, p_error_next, f_error_reg, f_error_next;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            if (current_state == idle_st)
                p_error_reg <= 0;
            else if (p_error_next)
                p_error_reg <= 1;
            if (current_state == idle_st)
                f_error_reg <= 0;
            else if (f_error_next)
                f_error_reg <= 1;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        rx_done = 1'b0;
        p_error_next = 1'b0;
        f_error_next = 1'b0;

        case (current_state)
            idle_st:
                if (!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end

            start_st:
                if (b_tick) begin
                    if (b_reg == (NUM_SAMPLES/2 - 1)) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end

            data_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if (count_reg == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end

            parity_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if (~^dout != rx) p_error_next = 1'b1;
                            3'b010: if (^dout != rx) p_error_next = 1'b1;
                            3'b100: if (rx != 1'b0) p_error_next = 1'b1;
                            3'b101: if (rx != 1'b1) p_error_next = 1'b1;
                            default: p_error_next = 1'b0;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;
                end

            stop0_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (!rx) f_error_next = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end

            stop1_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx) f_error_next = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end

            default:
                next_state = idle_st;
        endcase
    end

    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && b_reg == NUM_SAMPLES-1) begin
            if (current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout = data_reg >> (9-data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 12'd0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam TX_IDLE=3'd0, TX_START=3'd1, TX_DATA=3'd2,
               TX_PARITY=3'd3, TX_STOP0=3'd4, TX_STOP1=3'd5;

    reg [2:0] state;
    reg [MDW-1:0] data_reg;
    reg [3:0] data_size_reg;
    reg stop_bits_reg;
    reg [2:0] parity_reg;
    reg parity_value;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg tx_reg;

    integer i;
    reg parity_calc;

    always @* begin
        parity_calc = 1'b0;
        for (i = 0; i < MDW; i = i + 1)
            if (i < data_size)
                parity_calc = parity_calc ^ d_in[i];

        case (parity_type)
            3'b001: parity_value = ~parity_calc;
            3'b010: parity_value = parity_calc;
            3'b100: parity_value = 1'b0;
            3'b101: parity_value = 1'b1;
            default: parity_value = 1'b0;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= TX_IDLE;
            data_reg <= 'b0;
            data_size_reg <= 4'd8;
            stop_bits_reg <= 1'b0;
            parity_reg <= 3'b000;
            sample_count <= 0;
            bit_count <= 0;
            tx_reg <= 1'b1;
            tx_done <= 1'b0;
        end else begin
            tx_done <= 1'b0;

            case (state)
                TX_IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    bit_count <= 0;
                    if (tx_start && b_tick) begin
                        data_reg <= d_in;
                        data_size_reg <= data_size;
                        stop_bits_reg <= stop_bits_count;
                        parity_reg <= parity_type;
                        tx_reg <= 1'b0;
                        state <= TX_START;
                    end
                end

                TX_START:
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            tx_reg <= data_reg[0];
                            state <= TX_DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                TX_DATA:
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (bit_count == data_size_reg-1) begin
                                if (parity_reg == 3'b000) begin
                                    tx_reg <= 1'b1;
                                    state <= TX_STOP0;
                                end else begin
                                    tx_reg <= parity_value;
                                    state <= TX_PARITY;
                                end
                            end else begin
                                bit_count <= bit_count + 1'b1;
                                tx_reg <= data_reg[bit_count + 1'b1];
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                TX_PARITY:
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            tx_reg <= 1'b1;
                            state <= TX_STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                TX_STOP0:
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_reg)
                                state <= TX_STOP1;
                            else begin
                                state <= TX_IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                TX_STOP1:
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= TX_IDLE;
                            tx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                default:
                    state <= TX_IDLE;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC=8,
    parameter MDW=9,
    parameter GFLEN=8,
    parameter FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA=16'h0000, TXDATA=16'h0004, PR=16'h0008,
               CTRL=16'h000c, CFG=16'h0010, MATCH=16'h001c,
               RX_LEVEL=16'hfe00, RX_THRESHOLD=16'hfe04,
               RX_FLUSH=16'hfe08, TX_LEVEL=16'hfe10,
               TX_THRESHOLD=16'hfe14, TX_FLUSH=16'hfe18,
               IM=16'hff00, MIS=16'hff04, RIS=16'hff08,
               IC=16'hff0c, GCLK=16'hff10;

    wire apb_write = PSEL & PENABLE & PWRITE;
    wire apb_read = PSEL & PENABLE & ~PWRITE;

    reg [15:0] prescaler;
    reg [4:0] ctrl;
    reg [13:0] cfg;
    reg [8:0] match_data;
    reg [3:0] rx_threshold, tx_threshold;
    reg rx_flush_reg, tx_flush_reg;
    reg [9:0] im_reg, ic_reg;
    reg gclk_reg;
    reg [9:0] ris_reg;

    wire tx_empty, tx_full, rx_empty, rx_full;
    wire [FAW-1:0] tx_level, rx_level;
    wire [8:0] rx_data;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire uart_wr = apb_write && (PADDR[15:0] == TXDATA);
    wire uart_rd = apb_read && (PADDR[15:0] == RXDATA);

    wire [9:0] ris_conditions = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    EF_UART #(
        .MDW(MDW),
        .FAW(FAW),
        .SC(SC),
        .GFLEN(GFLEN)
    ) uart (
        .clk(PCLK),
        .rst_n(PRESETn),
        .prescaler(prescaler),
        .en(ctrl[0]),
        .tx_en(ctrl[1]),
        .rx_en(ctrl[2]),
        .rd(uart_rd),
        .wr(uart_wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg[3:0]),
        .stop_bits_count(cfg[4]),
        .parity_type(cfg[7:5]),
        .txfifotr(tx_threshold),
        .rxfifotr(rx_threshold),
        .match_data(match_data),
        .timeout_bits(cfg[13:8]),
        .loopback_en(ctrl[3]),
        .glitch_filter_en(ctrl[4]),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rx_data),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx[0]),
        .tx(tx[0])
    );

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            prescaler <= 16'd0;
            ctrl <= 5'd0;
            cfg <= 14'h3f08;
            match_data <= 9'd0;
            rx_threshold <= 4'd0;
            tx_threshold <= 4'd0;
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            im_reg <= 10'd0;
            ic_reg <= 10'd0;
            gclk_reg <= 1'b0;
            ris_reg <= 10'd0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 10'd0;

            if (apb_write) begin
                case (PADDR[15:0])
                    PR: prescaler <= PWDATA[15:0];
                    CTRL: ctrl <= PWDATA[4:0];
                    CFG: cfg <= PWDATA[13:0];
                    MATCH: match_data <= PWDATA[8:0];
                    RX_THRESHOLD: rx_threshold <= PWDATA[3:0];
                    TX_THRESHOLD: tx_threshold <= PWDATA[3:0];
                    RX_FLUSH: rx_flush_reg <= PWDATA[0];
                    TX_FLUSH: tx_flush_reg <= PWDATA[0];
                    IM: im_reg <= PWDATA[9:0];
                    IC: ic_reg <= PWDATA[9:0];
                    GCLK: gclk_reg <= PWDATA[0];
                    default: begin
                    end
                endcase
            end

            if (apb_write && (PADDR[15:0] == IC))
                ris_reg <= (ris_reg | ris_conditions) & ~PWDATA[9:0];
            else
                ris_reg <= ris_reg | ris_conditions;
        end
    end

    always @* begin
        case (PADDR[15:0])
            RXDATA: PRDATA = {23'd0, rx_data};
            PR: PRDATA = {16'd0, prescaler};
            CTRL: PRDATA = {27'd0, ctrl};
            CFG: PRDATA = {18'd0, cfg};
            MATCH: PRDATA = {23'd0, match_data};
            RX_LEVEL: PRDATA = {28'd0, rx_level};
            RX_THRESHOLD: PRDATA = {28'd0, rx_threshold};
            RX_FLUSH: PRDATA = {31'd0, rx_flush_reg};
            TX_LEVEL: PRDATA = {28'd0, tx_level};
            TX_THRESHOLD: PRDATA = {28'd0, tx_threshold};
            TX_FLUSH: PRDATA = {31'd0, tx_flush_reg};
            IM: PRDATA = {22'd0, im_reg};
            MIS: PRDATA = {22'd0, (ris_reg & im_reg)};
            RIS: PRDATA = {22'd0, ris_reg};
            GCLK: PRDATA = {31'd0, gclk_reg};
            default: PRDATA = 32'hdeadbeef;
        endcase
    end

    assign PREADY = 1'b1;
    assign IRQ = |(ris_reg & im_reg);
endmodule

