module EF_TMR32 #(
    parameter PRW = 16,
    parameter PWM_FAULT_CLR_C0 = 16'hA539,
    parameter PWM_FAULT_CLR_C1 = 16'hA953
) (
    input wire clk,
    input wire rst_n,

    input wire tmr_en,
    input wire tmr_start,
    input wire pwm0_en,
    input wire pwm1_en,
    input wire [31:0] tmr_reload,
    input wire [31:0] cmpx,
    input wire [31:0] cmpy,
    input wire [PRW-1:0] prescaler,
    input wire [2:0] tmr_cfg,
    input wire [11:0] pwm0_cfg,
    input wire [11:0] pwm1_cfg,
    input wire pwm0_inv,
    input wire pwm1_inv,
    input wire [7:0] pwm_dt,
    input wire [15:0] pwm_fault_clr,
    input wire pwm_dt_en,

    output wire [31:0] tmr,
    output wire matchx_flag,
    output wire matchy_flag,
    output wire timeout_flag,

    input wire pwm_fault,
    output wire pwm0,
    output wire pwm1
);

    wire [1:0] mode = tmr_cfg[1:0];
    wire periodic = tmr_cfg[2];

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg tmr_dir;
    reg tmr_run;
    reg pwm0_reg;
    reg pwm1_reg;
    reg pwm0_delayed;
    reg [7:0] dly_cntr;
    reg pwm0_w_dt;
    reg pwm1_w_dt;
    reg fault_reg;
    reg fault_armed;

    wire start_pulse;
    wire tick = (pr_reg == {PRW{1'b0}});
    wire eq_zero = (tmr_reg == 32'd0);
    wire eq_reload = (tmr_reg == tmr_reload);
    wire eq_reload_m1 = (tmr_reg == (tmr_reload - 32'd1));
    wire eq_one = (tmr_reg == 32'd1);
    wire eq_cmpx = (tmr_reg == cmpx);
    wire eq_cmpy = (tmr_reg == cmpy);

    ef_util_ped te_edge (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}},1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tmr_reg <= 32'd0;
            tmr_dir <= 1'b1;
            tmr_run <= 1'b0;
        end else begin
            if (start_pulse) begin
                tmr_run <= 1'b1;
                if (mode == 2'b01) begin
                    tmr_reg <= tmr_reload;
                    tmr_dir <= 1'b0;
                end else begin
                    tmr_reg <= 32'd0;
                    tmr_dir <= 1'b1;
                end
            end else begin
                if (tick) begin
                    if (mode == 2'b11) begin
                        if (tmr_dir && eq_reload_m1)
                            tmr_dir <= 1'b0;
                        else if (!tmr_dir && eq_one)
                            tmr_dir <= 1'b1;
                    end else if (mode == 2'b01) begin
                        tmr_dir <= 1'b0;
                    end else begin
                        tmr_dir <= 1'b1;
                    end

                    if (tmr_en && tmr_run) begin
                        if (tmr_start && (mode == 2'b01)) begin
                            tmr_reg <= tmr_reload;
                        end else if (tmr_start &&
                                     ((mode == 2'b10) || (mode == 2'b11))) begin
                            tmr_reg <= 32'd0;
                        end else begin
                            case (mode)
                                2'b11: begin
                                    if (tmr_dir)
                                        tmr_reg <= tmr_reg + 1'b1;
                                    else
                                        tmr_reg <= tmr_reg - 1'b1;
                                end
                                2'b01: begin
                                    if (eq_zero) begin
                                        if (periodic)
