    localparam RIS_OFFSET     = 16'hFF08;
    localparam IC_OFFSET      = 16'hFF0C;
    localparam GCLK_OFFSET    = 16'hFF10;

    wire apb_we = PSEL & PENABLE & PWRITE;

    reg [31:0] reload_reg;
    reg [PRW-1:0] pr_reg;
    reg [31:0] cmpx_reg;
    reg [31:0] cmpy_reg;
    reg [6:0] ctrl_reg;
    reg [2:0] cfg_reg;
    reg [11:0] pwm0cfg_reg;
    reg [15:0] pwm1cfg_reg;
    reg [7:0] pwm_dt_reg;
    reg [15:0] pwmfc_reg;
    reg gclk_reg;
    reg [2:0] im_reg;
    reg [2:0] ic_reg;
    reg [2:0] ris_reg;

    wire [31:0] tmr;
    wire mx, my, to;
    wire [2:0] mis = ris_reg & im_reg;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            reload_reg  <= 32'd0;
            pr_reg      <= 'd0;
            cmpx_reg    <= 32'd0;
            cmpy_reg    <= 32'd0;
            ctrl_reg    <= 7'd0;
            cfg_reg     <= 3'd0;
            pwm0cfg_reg <= 12'd0;
            pwm1cfg_reg <= 16'd0;
            pwm_dt_reg  <= 8'd0;
            pwmfc_reg   <= 16'd0;
            gclk_reg    <= 1'b0;
            im_reg      <= 3'd0;
        end else begin
            if (apb_we && PADDR[15:0] == RELOAD_OFFSET)  reload_reg  <= PWDATA;
            if (apb_we && PADDR[15:0] == PR_OFFSET)      pr_reg      <= PWDATA[PRW-1:0];
            if (apb_we && PADDR[15:0] == CMPX_OFFSET)    cmpx_reg    <= PWDATA;
            if (apb_we && PADDR[15:0] == CMPY_OFFSET)    cmpy_reg    <= PWDATA;
            if (apb_we && PADDR[15:0] == CTRL_OFFSET)    ctrl_reg    <= PWDATA[6:0];
            if (apb_we && PADDR[15:0] == CFG_OFFSET)     cfg_reg     <= PWDATA[2:0];
            if (apb_we && PADDR[15:0] == PWM0CFG_OFFSET) pwm0cfg_reg <= PWDATA[11:0];
            if (apb_we && PADDR[15:0] == PWM1CFG_OFFSET) pwm1cfg_reg <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == PWMDT_OFFSET)   pwm_dt_reg  <= PWDATA[7:0];
            if (apb_we && PADDR[15:0] == PWMFC_OFFSET)   pwmfc_reg   <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == GCLK_OFFSET)    gclk_reg    <= PWDATA[0];
            if (apb_we && PADDR[15:0] == IM_OFFSET)      im_reg      <= PWDATA[2:0];
