    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ic_reg <= 3'd0;
        else if (apb_we && PADDR[15:0] == IC_OFFSET)
            ic_reg <= PWDATA[2:0];
        else
            ic_reg <= 3'd0;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 3'd0;
        else begin
            if (ic_reg[0]) ris_reg[0] <= 1'b0;
            else if (to)   ris_reg[0] <= 1'b1;

            if (ic_reg[1]) ris_reg[1] <= 1'b0;
            else if (mx)   ris_reg[1] <= 1'b1;

            if (ic_reg[2]) ris_reg[2] <= 1'b0;
            else if (my)   ris_reg[2] <= 1'b1;
        end
    end

    EF_TMR32 #(.PRW(PRW)) timer (
        .clk(PCLK),
        .rst_n(PRESETn),
        .tmr_en(ctrl_reg[0]),
        .tmr_start(ctrl_reg[1]),
        .pwm0_en(ctrl_reg[2]),
        .pwm1_en(ctrl_reg[3]),
        .tmr_reload(reload_reg),
        .cmpx(cmpx_reg),
        .cmpy(cmpy_reg),
        .prescaler(pr_reg),
        .tmr_cfg(cfg_reg),
        .pwm0_cfg(pwm0cfg_reg),
        .pwm1_cfg(pwm1cfg_reg[11:0]),
        .pwm0_inv(ctrl_reg[5]),
        .pwm1_inv(ctrl_reg[6]),
        .pwm_dt(pwm_dt_reg),
        .pwm_fault_clr(pwmfc_reg),
        .pwm_dt_en(ctrl_reg[4]),
        .tmr(tmr),
        .matchx_flag(mx),
        .matchy_flag(my),
        .timeout_flag(to),
        .pwm_fault(pwm_fault[0]),
        .pwm0(pwm0[0]),
        .pwm1(pwm1[0])
    );

    assign IRQ = |mis;
    assign PREADY = 1'b1;

    assign PRDATA =
