module EF_TMR32 #(
    parameter PRW = 16,
    parameter PWM_FAULT_CLR_C0 = 16'hA539,
    parameter PWM_FAULT_CLR_C1 = 16'hA953
) (
    input  wire           clk,
    input  wire           rst_n,

    input  wire           tmr_en,
    input  wire           tmr_start,
    input  wire           pwm0_en,
    input  wire           pwm1_en,
    input  wire [31:0]    tmr_reload,
    input  wire [31:0]    cmpx,
    input  wire [31:0]    cmpy,
    input  wire [PRW-1:0] prescaler,
    input  wire [2:0]     tmr_cfg,
    input  wire [11:0]    pwm0_cfg,
    input  wire [11:0]    pwm1_cfg,
    input  wire           pwm0_inv,
    input  wire           pwm1_inv,
    input  wire [7:0]     pwm_dt,
    input  wire [15:0]    pwm_fault_clr,
    input  wire           pwm_dt_en,

    output wire [31:0]    tmr,
    output wire           matchx_flag,
    output wire           matchy_flag,
    output wire           timeout_flag,

    input  wire           pwm_fault,
    output wire           pwm0,
    output wire           pwm1
);

    wire [1:0] tmr_mode = tmr_cfg[1:0];
    wire       periodic = tmr_cfg[2];

    reg [31:0]  tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg          tmr_run;
    reg          tmr_dir;
    reg          te_d;

    wire te_rise = tmr_en & ~te_d;
    wire tick = (pr_reg == {PRW{1'b0}});

    wire eq_zero   = (tmr_reg == 32'd0);
    wire eq_reload = (tmr_reg == tmr_reload);
    wire eq_cmpx   = (tmr_reg == cmpx);
    wire eq_cmpy   = (tmr_reg == cmpy);
    wire eq_one    = (tmr_reg == 32'd1);
    wire eq_rel_m1 = (tmr_reg == (tmr_reload - 32'd1));

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            te_d <= 1'b0;
        else
            te_d <= tmr_en;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}},1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - {{(PRW-1){1'b0}},1'b1};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tmr_run <= 1'b0;
            tmr_reg <= 32'd0;
            tmr_dir <= 1'b1;
        end else begin
            if (te_rise) begin
                tmr_run <= 1'b1;
                if (tmr_mode == 2'b01) begin
                    tmr_reg <= tmr_reload;
                    tmr_dir <= 1'b0;
                end else begin
                    tmr_reg <= 32'd0;
                    tmr_dir <= 1'b1;
                end
            end else if (tmr_en && tick) begin
                if (!periodic && tmr_cfg[0] && eq_one && !tmr_dir)
                    tmr_run <= 1'b0;

                if (tmr_start && (tmr_mode == 2'b01)) begin
                    tmr_reg <= tmr_reload;
                end else if (tmr_start &&
                             ((tmr_mode == 2'b10) || (tmr_mode == 2'b11))) begin
                    tmr_reg <= 32'd0;
                end else if (tmr_run) begin
                    case (tmr_mode)
                        2'b11: begin
                            if (tmr_dir)
                                tmr_reg <= tmr_reg + 32'd1;
                            else
                                tmr_reg <= tmr_reg - 32'd1;
                        end

                        2'b01: begin
                            if (eq_zero) begin
                                if (periodic)
                                    tmr_reg <= tmr_reload;
                            end else begin
                                tmr_reg <= tmr_reg - 32'd1;
                            end
                        end

                        2'b10: begin
                            if (eq_reload) begin
                                if (periodic)
                                    tmr_reg <= 32'd0;
                            end else begin
                                tmr_reg <= tmr_reg + 32'd1;
                            end
                        end

                        default: begin
                            tmr_reg <= tmr_reg;
                        end
                    endcase
                end

                if (tmr_mode == 2'b11) begin
                    if (tmr_dir && eq_rel_m1)
                        tmr_dir <= 1'b0;
                    else if (!tmr_dir && eq_one)
                        tmr_dir <= 1'b1;
                end else if (tmr_mode == 2'b01) begin
                    tmr_dir <= 1'b0;
                end else begin
                    tmr_dir <= 1'b1;
                end
            end
        end
    end

    function automatic [1:0] get_action;
        input [2:0] mode;
        input [11:0] cfg;
        begin
            case (mode)
                3'd0: get_action = cfg[1:0];
                3'd1: get_action = cfg[3:2];
                3'd2: get_action = cfg[5:4];
                3'd3: get_action = cfg[7:6];
                3'd4: get_action = cfg[9:8];
                default: get_action = cfg[11:10];
            endcase
        end
    endfunction

    function automatic apply_action;
        input [1:0] action;
        input       value;
        begin
            case (action)
                2'b00: apply_action = value;
                2'b01: apply_action = 1'b0;
                2'b10: apply_action = 1'b1;
                default: apply_action = ~value;
            endcase
        end
    endfunction

    reg pwm0_reg;
    reg pwm1_reg;

    reg event_valid;
    reg [2:0] event_code;

    always @* begin
        event_valid = 1'b0;
        event_code = 3'd0;

        if (eq_zero && !eq_cmpx && !eq_cmpy && !eq_reload) begin
            event_valid = 1'b1;
            event_code = 3'd0;
        end else if (tmr_dir && eq_cmpx && !eq_zero &&
                     !eq_cmpy && !eq_reload) begin
            event_valid = 1'b1;
            event_code = 3'd1;
        end else if (tmr_dir && eq_cmpy && !eq_zero &&
                     !eq_cmpx && !eq_reload) begin
            event_valid = 1'b1;
            event_code = 3'd2;
        end else if (eq_reload && !eq_zero && !eq_cmpx && !eq_cmpy) begin
            event_valid = 1'b1;
            event_code = 3'd3;
        end else if (!tmr_dir && eq_cmpy && !eq_zero &&
                     !eq_cmpx && !eq_reload) begin
            event_valid = 1'b1;
            event_code = 3'd4;
        end else if (!tmr_dir && eq_cmpx && !eq_zero &&
                     !eq_cmpy && !eq_reload) begin
            event_valid = 1'b1;
            event_code = 3'd5;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_reg <= 1'b0;
            pwm1_reg <= 1'b0;
        end else if (tick) begin
            if (pwm0_en) begin
                if (pwm_fault)
                    pwm0_reg <= 1'b0;
                else if (event_valid)
                    pwm0_reg <= apply_action(get_action(event_code, pwm0_cfg),
                                             pwm0_reg);
            end

            if (pwm1_en) begin
                if (pwm_fault)
                    pwm1_reg <= 1'b0;
                else if (event_valid)
                    pwm1_reg <= apply_action(get_action(event_code, pwm1_cfg),
                                             pwm1_reg);
            end
        end
    end

    reg [7:0] dead_count;
    reg       pwm0_delayed;
    reg       pwm0_out_reg;
    reg       pwm1_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dead_count    <= 8'd0;
            pwm0_delayed  <= 1'b0;
        end else if (tick) begin
            if (dead_count == 8'd0) begin
                dead_count <= pwm_dt;
                pwm0_delayed <= pwm0_reg;
            end else begin
                dead_count <= dead_count - 8'd1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_out_reg <= 1'b0;
            pwm1_out_reg <= 1'b0;
        end else if (pwm_dt_en) begin
            pwm0_out_reg <= pwm0_delayed & pwm0_reg;
            pwm1_out_reg <= ~pwm0_delayed & ~pwm0_reg;
        end else begin
            pwm0_out_reg <= pwm0_reg;
            pwm1_out_reg <= pwm1_reg;
        end
    end

    reg fault_reg;
    reg fault_armed;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fault_armed <= 1'b0;
            fault_reg   <= 1'b0;
        end else begin
            if (pwm_fault_clr == PWM_FAULT_CLR_C0)
                fault_armed <= 1'b1;
            else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
                fault_armed <= 1'b0;

            if (pwm_fault)
                fault_reg <= 1'b1;
            else if (fault_armed &&
                     (pwm_fault_clr == PWM_FAULT_CLR_C1))
                fault_reg <= 1'b0;
        end
    end

    assign tmr = tmr_reg;
    assign matchx_flag = eq_cmpx;
    assign matchy_flag = eq_cmpy;
    assign timeout_flag = tmr_dir ? eq_reload : eq_zero;

    assign pwm0 = (pwm0_out_reg ^ pwm0_inv) & ~fault_reg & pwm0_en;
    assign pwm1 = (pwm1_out_reg ^ pwm1_inv) & ~fault_reg & pwm1_en;

endmodule


module EF_TMR32_APB #(
    parameter PRW = 16
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [31:0]  PWDATA,
    input  wire [31:0]  PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [31:0]  PRDATA,
    output wire         IRQ,
    output wire [0:0]   pwm0,
    output wire [0:0]   pwm1,
    input  wire [0:0]   pwm_fault
);

    localparam TMR_REG_OFFSET    = 16'h0000;
    localparam RELOAD_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET     = 16'h0008;
    localparam CMPX_REG_OFFSET   = 16'h000C;
    localparam CMPY_REG_OFFSET   = 16'h0010;
    localparam CTRL_REG_OFFSET   = 16'h0014;
    localparam CFG_REG_OFFSET    = 16'h0018;
    localparam PWM0CFG_REG_OFFSET = 16'h001C;
    localparam PWM1CFG_REG_OFFSET = 16'h0020;
    localparam PWMDT_REG_OFFSET  = 16'h0024;
    localparam PWMFC_REG_OFFSET  = 16'h0028;
    localparam IM_REG_OFFSET     = 16'hFF00;
    localparam MIS_REG_OFFSET    = 16'hFF04;
    localparam RIS_REG_OFFSET    = 16'hFF08;
    localparam IC_REG_OFFSET     = 16'hFF0C;
    localparam GCLK_REG_OFFSET   = 16'hFF10;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = apb_valid & PWRITE;

    reg [0:0] GCLK_REG;
    wire clk_g;

    ef_util_gating_cell clk_gate_cell (
        .clk(PCLK),
        .rst_n(PRESETn),
        .clk_en(GCLK_REG[0]),
        .clk_o(clk_g)
    );

    reg [31:0] RELOAD_REG;
    reg [PRW-1:0] PR_REG;
    reg [31:0] CMPX_REG;
    reg [31:0] CMPY_REG;
    reg [6:0] CTRL_REG;
    reg [2:0] CFG_REG;
    reg [11:0] PWM0CFG_REG;
    reg [15:0] PWM1CFG_REG;
    reg [7:0] PWMDT_REG;
    reg [15:0] PWMFC_REG;

    reg [2:0] IM_REG;
    reg [2:0] IC_REG;
    reg [2:0] RIS_REG;

    wire [31:0] tmr;
    wire matchx_flag;
    wire matchy_flag;
    wire timeout_flag;

    wire [2:0] MIS_REG = RIS_REG & IM_REG;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RELOAD_REG <= 32'd0;
        else if (apb_we && (PADDR[15:0] == RELOAD_REG_OFFSET))
            RELOAD_REG <= PWDATA;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PR_REG <= 'd0;
        else if (apb_we && (PADDR[15:0] == PR_REG_OFFSET))
            PR_REG <= PWDATA[PRW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CMPX_REG <= 32'd0;
        else if (apb_we && (PADDR[15:0] == CMPX_REG_OFFSET))
            CMPX_REG <= PWDATA;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CMPY_REG <= 32'd0;
        else if (apb_we && (PADDR[15:0] == CMPY_REG_OFFSET))
            CMPY_REG <= PWDATA;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CTRL_REG <= 7'd0;
        else if (apb_we && (PADDR[15:0] == CTRL_REG_OFFSET))
            CTRL_REG <= PWDATA[6:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            CFG_REG <= 3'd0;
        else if (apb_we && (PADDR[15:0] == CFG_REG_OFFSET))
            CFG_REG <= PWDATA[2:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PWM0CFG_REG <= 12'd0;
        else if (apb_we && (PADDR[15:0] == PWM0CFG_REG_OFFSET))
            PWM0CFG_REG <= PWDATA[11:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PWM1CFG_REG <= 16'd0;
        else if (apb_we && (PADDR[15:0] == PWM1CFG_REG_OFFSET))
            PWM1CFG_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PWMDT_REG <= 8'd0;
        else if (apb_we && (PADDR[15:0] == PWMDT_REG_OFFSET))
            PWMDT_REG <= PWDATA[7:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            PWMFC_REG <= 16'd0;
        else if (apb_we && (PADDR[15:0] == PWMFC_REG_OFFSET))
            PWMFC_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            GCLK_REG <= 1'b0;
        else if (apb_we && (PADDR[15:0] == GCLK_REG_OFFSET))
            GCLK_REG <= PWDATA[0:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IM_REG <= 3'd0;
        else if (apb_we && (PADDR[15:0] == IM_REG_OFFSET))
            IM_REG <= PWDATA[2:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            IC_REG <= 3'd0;
        end else if (apb_we && (PADDR[15:0] == IC_REG_OFFSET)) begin
            IC_REG <= PWDATA[2:0];
        end else begin
            IC_REG <= 3'd0;
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'd0;
        else begin
            if (IC_REG[0])
                RIS_REG[0] <= 1'b0;
            else if (timeout_flag)
                RIS_REG[0] <= 1'b1;

            if (IC_REG[1])
                RIS_REG[1] <= 1'b0;
            else if (matchx_flag)
                RIS_REG[1] <= 1'b1;

            if (IC_REG[2])
                RIS_REG[2] <= 1'b0;
            else if (matchy_flag)
                RIS_REG[2] <= 1'b1;
        end
    end

    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk(clk_g),
        .rst_n(PRESETn),
        .tmr_en(CTRL_REG[0]),
