        .pwm0_en(CTRL_REG[2]),
        .pwm1_en(CTRL_REG[3]),
        .tmr_reload(RELOAD_REG),
        .cmpx(CMPX_REG),
        .cmpy(CMPY_REG),
        .prescaler(PR_REG),
