    wire tx_empty,tx_full,rx_empty,rx_full;
    wire tx_level_below,rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag,match_flag,frame_error_flag,parity_error_flag;
    wire overrun_flag,timeout_flag;
    wire rd=apb_re && (PADDR[15:0]==RXDATA_REG_OFFSET);
    wire wr=apb_we && (PADDR[15:0]==TXDATA_REG_OFFSET);

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PR_REG <= 0;
        else if (apb_we && PADDR[15:0]==PR_REG_OFFSET) PR_REG <= PWDATA[15:0];

    always @(posedge PCLK or negedge PRESETn)
