    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) RIS_REG <= 0;
        else
            for (i=0;i<10;i=i+1)
                if (IC_REG[i]) RIS_REG[i] <= 1'b0;
                else if (ris_condition[i]) RIS_REG[i] <= 1'b1;
