    wire [9:0] MIS_REG = RIS_REG & IM_REG;
    assign IRQ = |MIS_REG;

    EF_UART #(.SC(SC),.MDW(MDW),.GFLEN(GFLEN),.FAW(FAW)) instance_to_wrap (
        .clk(clk), .rst_n(rst_n), .prescaler(prescaler),
        .en(en), .tx_en(tx_en), .rx_en(rx_en), .rd(rd), .wr(wr),
        .wdata(wdata), .data_size(data_size),
        .stop_bits_count(stop_bits_count), .parity_type(parity_type),
        .txfifotr(txfifotr), .rxfifotr(rxfifotr),
        .match_data(match_data), .timeout_bits(timeout_bits),
        .loopback_en(loopback_en), .glitch_filter_en(glitch_filter_en),
        .tx_fifo_flush(TX_FIFO_FLUSH_REG),
        .rx_fifo_flush(RX_FIFO_FLUSH_REG),
        .tx_empty(tx_empty), .tx_full(tx_full), .tx_level(tx_level),
        .tx_level_below(tx_level_below), .rdata(rdata),
        .rx_empty(rx_empty), .rx_full(rx_full), .rx_level(rx_level),
