module EF_TMR32 #(
    parameter PRW = 16,
    parameter PWM_FAULT_CLR_C0 = 16'hA539,
    parameter PWM_FAULT_CLR_C1 = 16'hA953
)(
    input wire clk,
    input wire rst_n,

    input wire tmr_en,
    input wire tmr_start,
    input wire pwm0_en,
    input wire pwm1_en,
    input wire [31:0] tmr_reload,
    input wire [31:0] cmpx,
    input wire [31:0] cmpy,
    input wire [PRW-1:0] prescaler,
    input wire [2:0] tmr_cfg,
    input wire [11:0] pwm0_cfg,
    input wire [11:0] pwm1_cfg,
    input wire pwm0_inv,
    input wire pwm1_inv,
    input wire [7:0] pwm_dt,
    input wire [15:0] pwm_fault_clr,
    input wire pwm_dt_en,

    output wire [31:0] tmr,
    output wire matchx_flag,
    output wire matchy_flag,
    output wire timeout_flag,

    input wire pwm_fault,
    output wire pwm0,
    output wire pwm1
);

  reg [31:0] tmr_r;
  reg [PRW-1:0] pr_r;
  reg [1:0] direction;
  reg running;

  reg pwm0_state;
  reg pwm1_state;
  reg fault_latched;
  reg fault_armed;

  reg [7:0] dead_count;
  reg delayed_pwm0;
  reg out0_r;
  reg out1_r;

  wire start_pulse;
  wire tick;
  wire dir_down;

  assign start_pulse = tmr_start & ~tmr_start_d;
  assign tick = (pr_r == {PRW{1'b0}});
  assign dir_down = (direction == 2'b01) ||
                    ((direction == 2'b11) && down_phase);

  reg tmr_start_d;
  reg down_phase;

  always @(posedge clk) begin
    tmr_start_d <= tmr_start;
  end

  assign tmr = tmr_r;
  assign matchx_flag = (tmr_r == cmpx);
  assign matchy_flag = (tmr_r == cmpy);
  assign timeout_flag = dir_down ? (tmr_r == 32'd0) :
                                      (tmr_r == tmr_reload);

  assign pwm0 = (out0_r ^ pwm0_inv) & ~fault_latched &
                ~pwm_fault & pwm0_en;
  assign pwm1 = (out1_r ^ pwm1_inv) & ~fault_latched &
                ~pwm_fault & pwm1_en;

  function [1:0] pwm_action;
    input [11:0] cfg;
    input [2:0] event_num;
    begin
      case (event_num)
        3'd0: pwm_action = cfg[1:0];
        3'd1: pwm_action = cfg[3:2];
        3'd2: pwm_action = cfg[5:4];
        3'd3: pwm_action = cfg[7:6];
        3'd4: pwm_action = cfg[9:8];
        3'd5: pwm_action = cfg[11:10];
        default: pwm_action = 2'b00;
      endcase
    end
  endfunction

  function pwm_apply;
    input old_state;
    input [1:0] action;
    begin
      case (action)
        2'b01: pwm_apply = 1'b0;
        2'b10: pwm_apply = 1'b1;
        2'b11: pwm_apply = ~old_state;
        default: pwm_apply = old_state;
      endcase
    end
  endfunction

  reg event_valid;
  reg [2:0] event_num;
  reg [1:0] action0;
  reg [1:0] action1;

  always @* begin
    event_valid = 1'b0;
    event_num = 3'd0;

    if ((tmr_r == 32'd0) &&
        (tmr_r != cmpx) && (tmr_r != cmpy) &&
        (tmr_r != tmr_reload)) begin
      event_valid = 1'b1;
      event_num = 3'd0;
    end
    else if ((direction != 2'b01) &&
             (tmr_r == cmpx) &&
             (tmr_r != 32'd0) &&
             (tmr_r != cmpy) &&
             (tmr_r != tmr_reload)) begin
      event_valid = 1'b1;
      event_num = 3'd1;
    end
    else if ((direction != 2'b01) &&
             (tmr_r == cmpy) &&
             (tmr_r != 32'd0) &&
             (tmr_r != cmpx) &&
             (tmr_r != tmr_reload)) begin
      event_valid = 1'b1;
      event_num = 3'd2;
    end
    else if ((tmr_r == tmr_reload) &&
             (tmr_r != 32'd0) &&
             (tmr_r != cmpx) &&
             (tmr_r != cmpy)) begin
      event_valid = 1'b1;
      event_num = 3'd3;
    end
    else if ((direction == 2'b01) &&
             (tmr_r == cmpy) &&
             (tmr_r != 32'd0) &&
             (tmr_r != cmpx) &&
             (tmr_r != tmr_reload)) begin
      event_valid = 1'b1;
      event_num = 3'd4;
    end
    else if ((direction == 2'b01) &&
             (tmr_r == cmpx) &&
             (tmr_r != 32'd0) &&
             (tmr_r != cmpy) &&
             (tmr_r != tmr_reload)) begin
      event_valid = 1'b1;
      event_num = 3'd5;
    end

    if (event_valid) begin
      action0 = pwm_action(pwm0_cfg, event_num);
      action1 = pwm_action(pwm1_cfg, event_num);
    end
    else begin
      action0 = 2'b00;
      action1 = 2'b00;
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tmr_r         <= 32'd0;
      pr_r          <= {{(PRW-1){1'b0}},1'b1};
      direction     <= 2'b10;
      running       <= 1'b0;
      pwm0_state    <= 1'b0;
      pwm1_state    <= 1'b0;
      fault_latched <= 1'b0;
      fault_armed   <= 1'b0;
      dead_count    <= 8'd0;
      delayed_pwm0  <= 1'b0;
      out0_r        <= 1'b0;
      out1_r        <= 1'b0;
      down_phase    <= 1'b0;
    end
    else begin
      /*
       * Prescaler.  The zero value is itself a timer tick.
       */
      if (!tmr_en)
        pr_r <= prescaler;
      else if (pr_r == {PRW{1'b0}})
        pr_r <= prescaler;
      else
        pr_r <= pr_r - {{(PRW-1){1'b0}},1'b1};

      /*
       * Fault latch and its two-key clearing sequence.
       */
      if (pwm_fault)
        fault_latched <= 1'b1;
      else if (fault_armed && (pwm_fault_clr == PWM_FAULT_CLR_C1))
        fault_latched <= 1'b0;

      if (pwm_fault_clr == PWM_FAULT_CLR_C0)
        fault_armed <= 1'b1;
      else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
        fault_armed <= 1'b0;

      /*
       * Direction is updated on every tick, including when the timer
       * is disabled.
       */
      if (tick) begin
        case (tmr_cfg[1:0])
          2'b00: begin
            direction <= 2'b10;
            down_phase <= 1'b0;
          end
          2'b01: begin
            direction <= 2'b01;
            down_phase <= 1'b1;
          end
          2'b10: begin
            direction <= 2'b10;
            down_phase <= 1'b0;
          end
          default: begin
            if (!down_phase && (tmr_r == (tmr_reload - 32'd1))) begin
              direction <= 2'b01;
              down_phase <= 1'b1;
            end
            else if (down_phase && (tmr_r == 32'd1)) begin
              direction <= 2'b10;
              down_phase <= 1'b0;
            end
          end
        endcase
      end

      /*
       * Start has priority over normal counting.
       */
      if (start_pulse) begin
        if (tmr_cfg[1:0] == 2'b01)
          tmr_r <= tmr_reload;
        else
          tmr_r <= 32'd0;

        if (tmr_cfg[1:0] == 2'b01) begin
          direction <= 2'b01;
          down_phase <= 1'b1;
        end
        else begin
          direction <= 2'b10;
          down_phase <= 1'b0;
        end

        running <= 1'b1;
      end
      else if (tmr_en && tick && running) begin
        if (tmr_cfg[1:0] == 2'b01) begin
          if (tmr_start)
            tmr_r <= tmr_reload;
          else if (tmr_r == 32'd0) begin
            if (tmr_cfg[2])
              tmr_r <= tmr_reload;
          end
          else
            tmr_r <= tmr_r - 32'd1;
        end
        else if ((tmr_cfg[1:0] == 2'b10) ||
                 (tmr_cfg[1:0] == 2'b11)) begin
          if (tmr_cfg[1:0] == 2'b11 && down_phase)
            tmr_r <= tmr_r - 32'd1;
          else if (tmr_r == tmr_reload) begin
            if (tmr_cfg[2])
              tmr_r <= 32'd0;
          end
          else
            tmr_r <= tmr_r + 32'd1;
        end

        if (!tmr_cfg[2] && direction[0] &&
            (direction == 2'b01 || down_phase) &&
            (tmr_r == 32'd1))
          running <= 1'b0;
      end

      /*
       * PWM state machines.
       */
      if (tick) begin
        if (pwm0_en) begin
          if (pwm_fault)
            pwm0_state <= 1'b0;
          else if (event_valid)
            pwm0_state <= pwm_apply(pwm0_state, action0);
        end

        if (pwm1_en) begin
          if (pwm_fault)
            pwm1_state <= 1'b0;
          else if (event_valid)
            pwm1_state <= pwm_apply(pwm1_state, action1);
        end

        if (dead_count == 8'd0) begin
          dead_count <= pwm_dt;
          delayed_pwm0 <= pwm0_state;
        end
        else begin
          dead_count <= dead_count - 8'd1;
        end
      end

      /*
       * Registered output stage.
       */
      if (pwm_dt_en) begin
        out0_r <= delayed_pwm0 & pwm0_state;
        out1_r <= ~delayed_pwm0 & ~pwm0_state;
      end
      else begin
        out0_r <= pwm0_state;
        out1_r <= pwm1_state;
      end
    end
  end
endmodule

module EF_TMR32_APB #(
    parameter PRW = 16
)(
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    output wire [1-1:0] pwm0,
    output wire [1-1:0] pwm1,
    input wire [1-1:0] pwm_fault
);

  reg [31:0] reload_r;
  reg [PRW-1:0] pr_r;
  reg [31:0] cmpx_r;
  reg [31:0] cmpy_r;
  reg [6:0] ctrl_r;
  reg [2:0] cfg_r;
  reg [11:0] pwm0cfg_r;
  reg [15:0] pwm1cfg_r;
  reg [7:0] pwmdt_r;
  reg [15:0] pwmfc_r;
  reg [2:0] im_r;
  reg [2:0] ic_r;
  reg gclk_r;
  reg [2:0] ris_r;

  wire wr;
  wire [15:0] addr;
  wire [2:0] mis;
  wire tmr_flag;
  wire mx_flag;
  wire my_flag;

  assign addr = PADDR[15:0];
  assign wr = PSEL & PENABLE & PWRITE;
  assign PREADY = 1'b1;

  assign mis = ris_r & im_r;
  assign IRQ = |mis;

  EF_TMR32 #(.PRW(PRW)) u_timer (
    .clk(PCLK),
    .rst_n(PRESETn),
    .tmr_en(ctrl_r[0]),
    .tmr_start(ctrl_r[1]),
    .pwm0_en(ctrl_r[2]),
    .pwm1_en(ctrl_r[3]),
    .tmr_reload(reload_r),
    .cmpx(cmpx_r),
    .cmpy(cmpy_r),
    .prescaler(pr_r),
    .tmr_cfg(cfg_r),
    .pwm0_cfg(pwm0cfg_r),
    .pwm1_cfg(pwm1cfg_r[11:0]),
    .pwm0_inv(ctrl_r[5]),
    .pwm1_inv(ctrl_r[6]),
    .pwm_dt(pwmdt_r),
    .pwm_fault_clr(pwmfc_r),
    .pwm_dt_en(ctrl_r[4]),
    .tmr(),
    .matchx_flag(mx_flag),
    .matchy_flag(my_flag),
    .timeout_flag(tmr_flag),
    .pwm_fault(pwm_fault[0]),
    .pwm0(pwm0[0]),
    .pwm1(pwm1[0])
  );

  wire [31:0] timer_value;

  EF_TMR32 #(.PRW(PRW)) u_timer_read_dummy ();
  assign timer_value = 32'd0;

  /*
   * The timer value is exported through a direct internal connection
   * to avoid making the APB wrapper dependent on implementation details.
   */
  wire [31:0] tmr_value;
  assign tmr_value = u_timer.tmr;

  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      reload_r <= 32'd0;
      pr_r <= {PRW{1'b0}};
      cmpx_r <= 32'd0;
      cmpy_r <= 32'd0;
      ctrl_r <= 7'd0;
      cfg_r <= 3'd0;
      pwm0cfg_r <= 12'd0;
      pwm1cfg_r <= 16'd0;
      pwmdt_r <= 8'd0;
      pwmfc_r <= 16'd0;
      im_r <= 3'd0;
      ic_r <= 3'd0;
      gclk_r <= 1'b0;
      ris_r <= 3'd0;
    end
    else begin
      if (wr) begin
        case (addr)
          16'h0004: reload_r <= PWDATA;
          16'h0008: pr_r <= PWDATA[PRW-1:0];
          16'h000C: cmpx_r <= PWDATA;
          16'h0010: cmpy_r <= PWDATA;
          16'h0014: ctrl_r <= PWDATA[6:0];
          16'h0018: cfg_r <= PWDATA[2:0];
          16'h001C: pwm0cfg_r <= PWDATA[11:0];
          16'h0020: pwm1cfg_r <= PWDATA[15:0];
          16'h0024: pwmdt_r <= PWDATA[7:0];
          16'h0028: pwmfc_r <= PWDATA[15:0];
          16'hFF00: im_r <= PWDATA[2:0];
          16'hFF0C: ic_r <= PWDATA[2:0];
          16'hFF10: gclk_r <= PWDATA[0];
          default: ;
        endcase
      end
      else begin
        ic_r <= 3'd0;
      end

      if (ic_r[0])
        ris_r[0] <= 1'b0;
      else if (tmr_flag)
        ris_r[0] <= 1'b1;

      if (ic_r[1])
        ris_r[1] <= 1'b0;
      else if (mx_flag)
        ris_r[1] <= 1'b1;

      if (ic_r[2])
        ris_r[2] <= 1'b0;
      else if (my_flag)
        ris_r[2] <= 1'b1;
    end
  end

  always @* begin
    case (addr)
      16'h0000: PRDATA = tmr_value;
      16'h0004: PRDATA = reload_r;
      16'h0008: PRDATA = {{(32-PRW){1'b0}},pr_r};
      16'h000C: PRDATA = cmpx_r;
      16'h0010: PRDATA = cmpy_r;
      16'h0014: PRDATA = {25'd0,ctrl_r};
      16'h0018: PRDATA = {29'd0,cfg_r};
      16'h001C: PRDATA = {20'd0,pwm0cfg_r};
      16'h0020: PRDATA = {16'd0,pwm1cfg_r};
      16'h0024: PRDATA = {24'd0,pwmdt_r};
      16'h0028: PRDATA = {16'd0,pwmfc_r};
      16'hFF00: PRDATA = {29'd0,im_r};
      16'hFF04: PRDATA = {29'd0,mis};
      16'hFF08: PRDATA = {29'd0,ris_r};
      16'hFF10: PRDATA = {31'd0,gclk_r};
      default: PRDATA = 32'hDEADBEEF;
    endcase
  end

