module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx_reg;

    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state         <= idle_st;
            sample_count  <= 4'd0;
            bit_count     <= 4'd0;
            data_reg      <= 'b0;
            tx_reg        <= 1'b1;
        end else begin
            state         <= next_state;
            sample_count  <= next_sample_count;
            bit_count     <= next_bit_count;
            data_reg      <= next_data_reg;
            tx_reg        <= next_tx_reg;
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_tx_reg       = tx_reg;
        tx_done           = 1'b0;

        case (state)
            idle_st: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state        = start_st;
                    next_sample_count = 4'd0;
                    next_bit_count    = 4'd0;
                    next_data_reg     = d_in;
                end
            end

            start_st: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state        = data_st;
                        next_sample_count = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 4'd0;
                        next_data_reg     = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^pdata;
                    3'b010: next_tx_reg =  ^pdata;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b0;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 4'd0;
                        next_state = stop0_st;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 4'd0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 4'd0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [4:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    wire [MDW-1:0] data_value =
        data_reg >> (MDW - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state            <= idle_st;
            sample_count     <= 5'd0;
            bit_count        <= 4'd0;
            data_reg         <= 'b0;
            parity_error_reg <= 1'b0;
            frame_error_reg  <= 1'b0;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;

            if (state == idle_st)
                parity_error_reg <= 1'b0;
            else if (next_parity_error)
                parity_error_reg <= 1'b1;

            if (state == idle_st)
                frame_error_reg <= 1'b0;
            else if (next_frame_error)
                frame_error_reg <= 1'b1;
        end
    end

    always @* begin
        next_state         = state;
        next_sample_count  = sample_count;
        next_bit_count     = bit_count;
        next_data_reg      = data_reg;
        next_parity_error  = 1'b0;
        next_frame_error   = 1'b0;
        rx_done            = 1'b0;

        case (state)
            idle_st: begin
                if (!rx && b_tick) begin
                    next_state        = start_st;
                    next_sample_count = 5'd0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state        = data_st;
                        next_sample_count = 5'd0;
                        next_bit_count    = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 5'd0;
                        next_data_reg =
                            {rx, data_reg[MDW-1:1]};

                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 5'd0;
                        next_state = stop0_st;

                        case (parity_type)
                            3'b001:
                                if ((~^data_value) != rx)
                                    next_parity_error = 1'b1;
                            3'b010:
                                if ((^data_value) != rx)
                                    next_parity_error = 1'b1;
                            3'b100:
                                if (rx != 1'b0)
                                    next_parity_error = 1'b1;
                            3'b101:
                                if (rx != 1'b1)
                                    next_parity_error = 1'b1;
                            default:
                                next_parity_error = 1'b0;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 5'd0;
                        if (!rx)
                            next_frame_error = 1'b1;

                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 5'd0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            break_shift <= 12'hfff;
        else if (b_tick && (sample_count == NUM_SAMPLES-1)) begin
            if (state == idle_st)
                break_shift <= 12'hfff;
            else
                break_shift <= {break_shift[10:0], rx};
        end
    end

    assign dout = data_value;
    assign parity_error = rx_done &&
                          (parity_error_reg || next_parity_error);
    assign frame_error = rx_done &&
                         (frame_error_reg || next_frame_error);
    assign break_flag = (break_shift == 12'd0);
    assign match_flag = rx_done && (match_data == data_value);
endmodule

module EF_UART #(
    parameter MDW = 9,
    parameter FAW = 4,
    parameter SC = 8,
    parameter GFLEN = 8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire baud_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_sync, rx_filtered, rx_in;

    ef_util_sync rx_sync_inst (
        .clk(clk),
        .in(rx),
        .out(rx_sync)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_sync),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud_gen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC), .MDW(MDW)) tx_unit (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(baud_tick && tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.NUM_SAMPLES(SC), .MDW(MDW)) rx_unit (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(baud_tick && rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .rx(rx_in),
        .match_data(match_data),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count    <= 6'd0;
            samples_count <= 5'd0;
        end else if (baud_tick) begin
            if (rx_done) begin
                bits_count    <= 6'd0;
                samples_count <= 5'd0;
            end else if (samples_count == SC-1) begin
                samples_count <= 5'd0;
                if (timeout_flag)
                    bits_count <= 6'd0;
                else
                    bits_count <= bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_done && rx_full;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_OFFSET = 16'h0000;
    localparam TXDATA_OFFSET = 16'h0004;
    localparam PR_OFFSET = 16'h0008;
    localparam CTRL_OFFSET = 16'h000c;
    localparam CFG_OFFSET = 16'h0010;
    localparam MATCH_OFFSET = 16'h001c;
    localparam RX_LEVEL_OFFSET = 16'hfe00;
    localparam RX_THRESHOLD_OFFSET = 16'hfe04;
    localparam RX_FLUSH_OFFSET = 16'hfe08;
    localparam TX_LEVEL_OFFSET = 16'hfe10;
    localparam TX_THRESHOLD_OFFSET = 16'hfe14;
    localparam TX_FLUSH_OFFSET = 16'hfe18;
    localparam IM_OFFSET = 16'hff00;
    localparam MIS_OFFSET = 16'hff04;
    localparam RIS_OFFSET = 16'hff08;
    localparam IC_OFFSET = 16'hff0c;
    localparam GCLK_OFFSET = 16'hff10;

    wire clk = PCLK;
    wire apb_valid = PSEL && PENABLE;
    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;
    wire [15:0] addr = PADDR[15:0];

    reg [15:0] PR_REG;
    reg [4:0] CTRL_REG;
    reg [13:0] CFG_REG;
    reg [MDW-1:0] MATCH_REG;
    reg [FAW-1:0] RX_THRESHOLD_REG;
    reg [FAW-1:0] TX_THRESHOLD_REG;
    reg RX_FLUSH_REG, TX_FLUSH_REG;
    reg GCLK_REG;
    reg [9:0] IM_REG, IC_REG, RIS_REG;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;
    wire [MDW-1:0] rdata;

    wire tx_fifo_write = apb_we && (addr == TXDATA_OFFSET);
    wire rx_fifo_read  = apb_re && (addr == RXDATA_OFFSET);

    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn) begin
            PR_REG           <= 16'd0;
            CTRL_REG         <= 5'd0;
            CFG_REG          <= 14'h3f08;
            MATCH_REG        <= 'b0;
            RX_THRESHOLD_REG <= 'b0;
            TX_THRESHOLD_REG <= 'b0;
            RX_FLUSH_REG     <= 1'b0;
            TX_FLUSH_REG     <= 1'b0;
            GCLK_REG         <= 1'b0;
            IM_REG           <= 10'd0;
            IC_REG           <= 10'd0;
        end else begin
            if (apb_we && (addr == PR_OFFSET))
                PR_REG <= PWDATA[15:0];
            if (apb_we && (addr == CTRL_OFFSET))
                CTRL_REG <= PWDATA[4:0];
            if (apb_we && (addr == CFG_OFFSET))
                CFG_REG <= PWDATA[13:0];
            if (apb_we && (addr == MATCH_OFFSET))
                MATCH_REG <= PWDATA[MDW-1:0];
            if (apb_we && (addr == RX_THRESHOLD_OFFSET))
                RX_THRESHOLD_REG <= PWDATA[FAW-1:0];
            if (apb_we && (addr == TX_THRESHOLD_OFFSET))
                TX_THRESHOLD_REG <= PWDATA[FAW-1:0];

            if (apb_we && (addr == RX_FLUSH_OFFSET))
                RX_FLUSH_REG <= PWDATA[0];
            else
                RX_FLUSH_REG <= 1'b0;

            if (apb_we && (addr == TX_FLUSH_OFFSET))
                TX_FLUSH_REG <= PWDATA[0];
            else
                TX_FLUSH_REG <= 1'b0;

            if (apb_we && (addr == GCLK_OFFSET))
                GCLK_REG <= PWDATA[0];

            if (apb_we && (addr == IM_OFFSET))
                IM_REG <= PWDATA[9:0];

            if (apb_we && (addr == IC_OFFSET))
                IC_REG <= PWDATA[9:0];
            else
                IC_REG <= 10'd0;
        end
    end

    wire [9:0] raw_events = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    integer i;
    always @(posedge clk or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 10'd0;
        else begin
            for (i = 0; i < 10; i = i + 1) begin
                if (IC_REG[i])
                    RIS_REG[i] <= 1'b0;
                else if (raw_events[i])
                    RIS_REG[i] <= 1'b1;
            end
        end
    end

    wire [9:0] MIS = RIS_REG & IM_REG;

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) uart_core (
        .clk(clk),
        .rst_n(PRESETn),
        .prescaler(PR_REG),
        .en(CTRL_REG[0]),
        .tx_en(CTRL_REG[1]),
        .rx_en(CTRL_REG[2]),
        .rd(rx_fifo_read),
        .wr(tx_fifo_write),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(CFG_REG[3:0]),
        .stop_bits_count(CFG_REG[4]),
        .parity_type(CFG_REG[7:5]),
        .txfifotr(TX_THRESHOLD_REG[3:0]),
        .rxfifotr(RX_THRESHOLD_REG[3:0]),
        .match_data(MATCH_REG),
        .timeout_bits(CFG_REG[13:8]),
        .loopback_en(CTRL_REG[3]),
        .glitch_filter_en(CTRL_REG[4]),
        .tx_fifo_flush(TX_FLUSH_REG),
        .rx_fifo_flush(RX_FLUSH_REG),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA_OFFSET)        ? {{(32-MDW){1'b0}}, rdata} :
        (addr == PR_OFFSET)            ? {{16{1'b0}}, PR_REG} :
        (addr == CTRL_OFFSET)          ? {{27{1'b0}}, CTRL_REG} :
        (addr == CFG_OFFSET)           ? {{18{1'b0}}, CFG_REG} :
        (addr == MATCH_OFFSET)         ? {{(32-MDW){1'b0}}, MATCH_REG} :
        (addr == RX_LEVEL_OFFSET)      ? {{(32-FAW){1'b0}}, rx_level} :
        (addr == RX_THRESHOLD_OFFSET)  ? {{(32-FAW){1'b0}}, RX_THRESHOLD_REG} :
        (addr == RX_FLUSH_OFFSET)      ? {31'd0, RX_FLUSH_REG} :
        (addr == TX_LEVEL_OFFSET)      ? {{(32-FAW){1'b0}}, tx_level} :
        (addr == TX_THRESHOLD_OFFSET)  ? {{(32-FAW){1'b0}}, TX_THRESHOLD_REG} :
        (addr == TX_FLUSH_OFFSET)      ? {31'd0, TX_FLUSH_REG} :
        (addr == IM_OFFSET)            ? {22'd0, IM_REG} :
        (addr == MIS_OFFSET)           ? {22'd0, MIS} :
        (addr == RIS_OFFSET)           ? {22'd0, RIS_REG} :
        (addr == GCLK_OFFSET)          ? {31'd0, GCLK_REG} :
        32'hdeadbeef;

    assign PREADY = 1'b1;
    assign IRQ = |MIS;
endmodule

