module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk,
    input wire rst_n,
    input wire rd,
    input wire wr,
    input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty,
    output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam integer DEPTH = 1 << AW;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] w_ptr, r_ptr;
    reg [AW-1:0] level_reg;
    reg empty_reg, full_reg;
    wire write_accept = wr && !full_reg;

    assign rdata = mem[r_ptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;

    always @(posedge clk) begin
        if (write_accept)
            mem[w_ptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr     <= 'b0;
            r_ptr     <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg  <= 1'b0;
        end else if (flush) begin
            w_ptr     <= 'b0;
            r_ptr     <= 'b0;
            level_reg <= 'b0;
            empty_reg <= 1'b1;
            full_reg  <= 1'b0;
        end else begin
            case ({write_accept, rd && !empty_reg})
                2'b10: begin
                    w_ptr     <= w_ptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((w_ptr + 1'b1) == r_ptr)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    r_ptr     <= r_ptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg  <= 1'b0;
                    if ((r_ptr + 1'b1) == w_ptr)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    w_ptr <= w_ptr + 1'b1;
                    r_ptr <= r_ptr + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end
