        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}}, 1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
