    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, parameter MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick, input wire [3:0] data_size,
    input wire stop_bits_count, input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done, output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state;
    reg [3:0] sample_count, bit_count;
    reg [MDW-1:0] data;
    reg tx_reg;

    wire [MDW-1:0] parity_data =
        d_in & ({MDW{1'b1}} >> (MDW-data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data <= 0;
            tx_reg <= 1'b1;
        end else begin
            tx_done <= 1'b0;
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        state <= START;
                        sample_count <= 0;
                        data <= d_in;
                    end
                end
                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                DATA: begin
                    tx_reg <= data[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data <= data >> 1;
                            if (bit_count == data_size-1)
                                state <= (parity_type == 3'b000) ? STOP0 : PARITY;
                            else
                                bit_count <= bit_count + 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^parity_data;
                        3'b010: tx_reg <= ^parity_data;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b1;
                    endcase
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            tx_done <= 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, parameter MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size, input wire stop_bits_count,
    input wire [2:0] parity_type, input wire rx,
    input wire [MDW-1:0] match_data,
    output wire rx_done, output wire parity_error,
    output wire frame_error, output wire break_flag,
    output wire match_flag, output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state;
    reg [4:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data;
    reg parity_bad;
    reg [11:0] break_count;

    wire sample_end = b_tick && (sample_count == NUM_SAMPLES-1);
    wire [MDW-1:0] received = data >> (MDW-data_size);
    wire parity_expected =
        (parity_type == 3'b001) ? ~^received :
        (parity_type == 3'b010) ? ^received :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    assign dout = received;
    assign rx_done = sample_end &&
                     (((state == STOP0) && !stop_bits_count) ||
                      ((state == STOP1) && stop_bits_count));
    assign parity_error = rx_done && parity_bad;
    assign frame_error = rx_done && !rx;
    assign match_flag = rx_done && (received == match_data);
    assign break_flag = &break_count;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data <= 0;
            parity_bad <= 1'b0;
            break_count <= 0;
        end else if (b_tick) begin
            case (state)
                IDLE: begin
                    sample_count <= 0;
                    parity_bad <= 1'b0;
                    if (!rx) state <= START;
                    break_count <= 0;
                end
                START: begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        sample_count <= 0;
                        bit_count <= 0;
                        state <= DATA;
                    end else sample_count <= sample_count + 1'b1;
                end
                DATA: begin
                    if (sample_end) begin
                        sample_count <= 0;
                        data <= {data[MDW-2:0],rx};
                        if (bit_count == data_size-1)
                            state <= (parity_type == 3'b000) ? STOP0 : PARITY;
                        else
                            bit_count <= bit_count + 1'b1;
                    end else sample_count <= sample_count + 1'b1;
                end
                PARITY: begin
                    if (sample_end) begin
                        sample_count <= 0;
                        parity_bad <= (rx != parity_expected);
                        state <= STOP0;
                    end else sample_count <= sample_count + 1'b1;
                end
                STOP0: begin
                    if (sample_end) begin
                        sample_count <= 0;
                        state <= stop_bits_count ? STOP1 : IDLE;
                    end else sample_count <= sample_count + 1'b1;
                end
                STOP1: begin
                    if (sample_end) begin
                        sample_count <= 0;
                        state <= IDLE;
                    end else sample_count <= sample_count + 1'b1;
                end
                default: state <= IDLE;
            endcase

            if (state != IDLE && sample_end)
                break_count <= {break_count[10:0],~rx};
        end
    end
endmodule

module EF_UART #(
    parameter MDW=9, parameter FAW=4, parameter SC=8, parameter GFLEN=8
) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr, input wire [MDW-1:0] wdata,
    input wire [3:0] data_size, input wire stop_bits_count,
    input wire [2:0] parity_type, input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr, input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits, input wire loopback_en,
    input wire glitch_filter_en, input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire sync_rx, filtered_rx, rx_in, baud_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;

    ef_util_sync sync (.clk(clk),.in(rx),.out(sync_rx));
    ef_util_glitch_filter #(.N(GFLEN)) filter (
        .clk(clk),.rst_n(rst_n),.in(sync_rx),
        .en(glitch_filter_en),.out(filtered_rx)
    );
    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? filtered_rx : sync_rx;

    BAUDGEN baud (
        .clk(clk),.rst_n(rst_n),.prescale(prescaler),
        .en(en),.baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(tx_done),.wr(wr),
        .flush(tx_fifo_flush),.wdata(wdata),.empty(tx_empty),
        .full(tx_full),.rdata(tx_data),.level(tx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC),.MDW(MDW)) transmitter (
        .clk(clk),.resetn(rst_n),.tx_start(!tx_empty),
        .b_tick(baud_tick && tx_en),.data_size(data_size),
        .stop_bits_count(stop_bits_count),.parity_type(parity_type),
        .d_in(tx_data),.tx_done(tx_done),.tx(tx)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) rx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(rd),.wr(rx_done),
        .flush(rx_fifo_flush),.wdata(rx_data),.empty(rx_empty),
        .full(rx_full),.rdata(rdata),.level(rx_level)
    );

    UART_RX #(.NUM_SAMPLES(SC),.MDW(MDW)) receiver (
        .clk(clk),.resetn(rst_n),.b_tick(baud_tick && rx_en),
        .data_size(data_size),.stop_bits_count(stop_bits_count),
        .parity_type(parity_type),.rx(rx),.match_data(match_data),
        .rx_done(rx_done),.parity_error(parity_error_flag),
        .frame_error(frame_error_flag),.break_flag(break_flag),
        .match_flag(match_flag),.dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [4:0] sample_count;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            sample_count <= 0;
        end else if (baud_tick) begin
            if (rx_done) begin
                timeout_count <= 0;
                sample_count <= 0;
            end else if (sample_count == SC-1) begin
                sample_count <= 0;
                if (timeout_count == timeout_bits)
                    timeout_count <= 0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else
                sample_count <= sample_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_done && rx_full;
    assign timeout_flag = (timeout_count == timeout_bits);
endmodule

