module ef_util_fifo #(parameter DW=8, AW=4)(
    input   wire            clk,
    input   wire            rst_n,
    input   wire            rd,
    input   wire            wr,
    input   wire            flush,
    input   wire [DW-1:0]   wdata,
    output  wire            empty,
    output  wire            full,
    output  wire [DW-1:0]   rdata,
    output  wire [AW-1:0]   level
);

    localparam integer DEPTH = (1 << AW);

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rd_ptr;
    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] level_reg;
    reg          full_reg;

    wire write_accept = wr & ~full_reg;
    wire read_accept  = rd & (|level_reg | full_reg);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rd_ptr    <= {AW{1'b0}};
            wr_ptr    <= {AW{1'b0}};
            level_reg <= {AW{1'b0}};
            full_reg  <= 1'b0;
        end else if (flush) begin
            rd_ptr    <= {AW{1'b0}};
            wr_ptr    <= {AW{1'b0}};
            level_reg <= {AW{1'b0}};
            full_reg  <= 1'b0;
        end else begin
            if (write_accept) begin
                mem[wr_ptr] <= wdata;
                wr_ptr      <= wr_ptr + {{(AW-1){1'b0}}, 1'b1};
            end

            if (read_accept)
                rd_ptr <= rd_ptr + {{(AW-1){1'b0}}, 1'b1};

            case ({write_accept, read_accept})
                2'b10: begin
                    level_reg <= level_reg + {{(AW-1){1'b0}}, 1'b1};
                    if ((wr_ptr + {{(AW-1){1'b0}}, 1'b1}) == rd_ptr)
                        full_reg <= 1'b1;
                end

                2'b01: begin
                    level_reg <= level_reg - {{(AW-1){1'b0}}, 1'b1};
                    full_reg  <= 1'b0;
                end

                2'b11: begin
                    level_reg <= level_reg;
                    full_reg  <= full_reg;
                end

                default: begin
                    level_reg <= level_reg;
                    full_reg  <= full_reg;
                end
            endcase
        end
    end

    assign rdata = mem[rd_ptr];
    assign level = level_reg;
    assign empty = ~full_reg & (level_reg == {AW{1'b0}});
    assign full  = full_reg;

endmodule
