            RX_FIFO_FLUSH_REG <= 1'b0;
        else if(apb_we && PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET)
            RX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            RX_FIFO_FLUSH_REG <= 1'b0;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn)
            TX_FIFO_FLUSH_REG <= 1'b0;
        else if(apb_we && PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET)
            TX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            TX_FIFO_FLUSH_REG <= 1'b0;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn)
            GCLK_REG <= 1'b0;
        else if(apb_we && PADDR[15:0] == GCLK_REG_OFFSET)
            GCLK_REG <= PWDATA[0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn)
            IM_REG <= 10'b0;
        else if(apb_we && PADDR[15:0] == IM_REG_OFFSET)
            IM_REG <= PWDATA[9:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn)
            IC_REG <= 10'b0;
        else if(apb_we && PADDR[15:0] == IC_REG_OFFSET)
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 10'b0;

    wire [9:0] MIS_REG = RIS_REG & IM_REG;

    wire [9:0] interrupt_sources = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn)
            RIS_REG <= 10'b0;
        else
            RIS_REG <= (RIS_REG & ~IC_REG) | interrupt_sources;

    assign IRQ = |MIS_REG;
    assign PREADY = 1'b1;

    always @* begin
        PRDATA = 32'hDEADBEEF;

        case(PADDR[15:0])
            RXDATA_REG_OFFSET:
                PRDATA = {{(32-MDW){1'b0}}, rdata};

            PR_REG_OFFSET:
                PRDATA = {16'b0, PR_REG};

            CTRL_REG_OFFSET:
                PRDATA = {27'b0, CTRL_REG};

            CFG_REG_OFFSET:
                PRDATA = {18'b0, CFG_REG};

            MATCH_REG_OFFSET:
                PRDATA = {{(32-MDW){1'b0}}, MATCH_REG};

            RX_FIFO_LEVEL_REG_OFFSET:
                PRDATA = {{(32-FAW){1'b0}}, rx_level};

            RX_FIFO_THRESHOLD_REG_OFFSET:
                PRDATA = {{(32-FAW){1'b0}}, RX_FIFO_THRESHOLD_REG};

            RX_FIFO_FLUSH_REG_OFFSET:
                PRDATA = {31'b0, RX_FIFO_FLUSH_REG};

            TX_FIFO_LEVEL_REG_OFFSET:
                PRDATA = {{(32-FAW){1'b0}}, tx_level};

            TX_FIFO_THRESHOLD_REG_OFFSET:
                PRDATA = {{(32-FAW){1'b0}}, TX_FIFO_THRESHOLD_REG};

            TX_FIFO_FLUSH_REG_OFFSET:
                PRDATA = {31'b0, TX_FIFO_FLUSH_REG};

            IM_REG_OFFSET:
                PRDATA = {22'b0, IM_REG};

            MIS_REG_OFFSET:
                PRDATA = {22'b0, MIS_REG};

            RIS_REG_OFFSET:
                PRDATA = {22'b0, RIS_REG};

            GCLK_REG_OFFSET:
                PRDATA = {31'b0, GCLK_REG};

            default:
                PRDATA = 32'hDEADBEEF;
        endcase
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .prescaler(prescaler),
        .en(en),
        .tx_en(tx_en),
        .rx_en(rx_en),
        .wdata(wdata),
        .timeout_bits(timeout_bits),
        .loopback_en(loopback_en),
        .glitch_filter_en(glitch_filter_en),
        .tx_level(tx_level),
        .rx_level(rx_level),
        .rd(rd),
        .wr(wr),
        .tx_fifo_flush(tx_fifo_flush),
        .rx_fifo_flush(rx_fifo_flush),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .txfifotr(txfifotr),
        .rxfifotr(rxfifotr),
        .match_data(match_data),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

endmodule

