    localparam [15:0] A_RXDATA      = 16'h0000;
    localparam [15:0] A_TXDATA      = 16'h0004;
    localparam [15:0] A_PR          = 16'h0008;
    localparam [15:0] A_CTRL        = 16'h000c;
    localparam [15:0] A_CFG         = 16'h0010;
    localparam [15:0] A_MATCH       = 16'h001c;
    localparam [15:0] A_RX_LEVEL    = 16'hfe00;
    localparam [15:0] A_RX_THRESH   = 16'hfe04;
    localparam [15:0] A_RX_FLUSH    = 16'hfe08;
    localparam [15:0] A_TX_LEVEL    = 16'hfe10;
    localparam [15:0] A_TX_THRESH   = 16'hfe14;
    localparam [15:0] A_TX_FLUSH    = 16'hfe18;
    localparam [15:0] A_IM          = 16'hff00;
    localparam [15:0] A_MIS         = 16'hff04;
    localparam [15:0] A_RIS         = 16'hff08;
    localparam [15:0] A_IC          = 16'hff0c;
    localparam [15:0] A_GCLK        = 16'hff10;

    wire wr_xfer = PSEL & PENABLE & PWRITE;
    wire rd_xfer = PSEL & PENABLE & ~PWRITE;

