    reg [4:0] ctrl;
    reg [13:0] cfg;
    reg [8:0] match_reg;
    reg [3:0] rx_threshold, tx_threshold;
    reg rx_flush, tx_flush;
    reg [9:0] interrupt_mask;
    reg [9:0] interrupt_clear;
    reg gclk;

    wire tx_empty, tx_full, rx_empty, rx_full;
    wire [FAW-1:0] tx_level, rx_level;
    wire [MDW-1:0] rx_rdata;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire tx_write = wr_xfer && (PADDR[15:0] == A_TXDATA);
    wire rx_read  = rd_xfer && (PADDR[15:0] == A_RXDATA);

    wire [9:0] ris_condition = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
