        if (!PRESETn) begin
            prescaler      <= 16'b0;
            ctrl           <= 5'b0;
            cfg            <= 14'h3f08;
            match_reg      <= 9'b0;
            rx_threshold   <= 4'b0;
            tx_threshold   <= 4'b0;
            rx_flush       <= 1'b0;
            tx_flush       <= 1'b0;
            interrupt_mask <= 10'b0;
            interrupt_clear<= 10'b0;
            gclk           <= 1'b0;
        end else begin
            rx_flush        <= 1'b0;
            tx_flush        <= 1'b0;
            interrupt_clear <= 10'b0;

            if (wr_xfer) begin
                case (PADDR[15:0])
