                        prescaler <= PWDATA[15:0];

                    A_CTRL:
                        ctrl <= PWDATA[4:0];

                    A_CFG:
                        cfg <= PWDATA[13:0];

                    A_MATCH:
                        match_reg <= PWDATA[8:0];

                    A_RX_THRESH:
                        rx_threshold <= PWDATA[3:0];

                    A_TX_THRESH:
                        tx_threshold <= PWDATA[3:0];

                    A_RX_FLUSH:
                        rx_flush <= PWDATA[0];

