        (PADDR[15:0] == A_TX_LEVEL)  ? {28'b0, tx_level} :
        (PADDR[15:0] == A_TX_THRESH) ? {28'b0, tx_threshold} :
        (PADDR[15:0] == A_TX_FLUSH)  ? {31'b0, tx_flush} :
