    wire tick_w = (clk_div == 'b0) ? 1'b1 : counter_is_zero;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            counter <= 'b0;
        else if (en)
            counter <= counter_is_zero ? clk_div : counter - 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tick_reg <= 1'b0;
        else if (en)
            tick_reg <= tick_w;
        else
            tick_reg <= 1'b0;
    end

    assign tick = tick_reg;
