    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'b0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'b0 :
                         count_reg + 1'b1;
    end

    assign baudtick = (count_reg == prescale);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire tx_start, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010;
    localparam parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next;
    reg [3:0] count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg tx_reg, tx_next;
    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            tx_reg <= tx_next;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        tx_next = tx_reg;
        tx_done = 1'b0;

        case (current_state)
            idle_st: begin
                tx_next = 1'b1;
                if (tx_start) begin
                    next_state = start_st;
                    b_next = 0;
                    data_next = d_in;
                end
            end

            start_st: begin
                tx_next = 1'b0;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            data_st: begin
                tx_next = data_reg[0];
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if (count_next == data_size-1)
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 1'b0;
                    3'b101: tx_next = 1'b1;
                    default: tx_next = 1'b0;
                endcase

                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop0_st: begin
                tx_next = 1'b1;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop1_st: begin
                tx_next = 1'b1;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end
        endcase
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010;
    localparam parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg p_error_reg, p_error_next;
    reg f_error_reg, f_error_next;
    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;

            if (current_state == idle_st)
                p_error_reg <= 1'b0;
            else if (p_error_next)
                p_error_reg <= 1'b1;

            if (current_state == idle_st)
                f_error_reg <= 1'b0;
            else if (f_error_next)
                f_error_reg <= 1'b1;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        rx_done = 1'b0;
        p_error_next = 1'b0;
        f_error_next = 1'b0;

        case (current_state)
            idle_st:
                if (!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end

            start_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES/2-1) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end

            data_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if (count_next == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end

            parity_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if (~^dout != rx) p_error_next = 1'b1;
                            3'b010: if (^dout != rx)  p_error_next = 1'b1;
                            3'b100: if (rx != 1'b0)   p_error_next = 1'b1;
                            3'b101: if (rx != 1'b1)   p_error_next = 1'b1;
                            default: ;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;
                end

            stop0_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (!rx) f_error_next = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end

            stop1_st:
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx) f_error_next = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && b_reg == NUM_SAMPLES-1) begin
            if (current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout = data_reg >> (9-data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 12'b0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module EF_UART #(parameter MDW=9, FAW=4, SC=8, GFLEN=8) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr, input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en, input wire glitch_filter_en,
    input wire tx_fifo_flush, input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire b_tick, tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_synched, rx_filtered, rx_in;

    ef_util_sync rx_sync (.clk(clk), .in(rx), .out(rx_synched));

    ef_util_glitch_filter #(.N(GFLEN)) rx_glitch_filter (
        .clk(clk), .rst_n(rst_n), .en(glitch_filter_en),
        .in(rx_synched), .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                    glitch_filter_en ? rx_filtered : rx_synched;

    BAUDGEN baud_gen (
        .clk(clk), .rst_n(rst_n), .prescale(prescaler),
        .en(en), .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_tx (
        .clk(clk), .rst_n(rst_n), .rd(tx_done), .wr(wr),
        .wdata(wdata), .empty(tx_empty), .full(tx_full),
        .rdata(tx_data), .level(tx_level), .flush(tx_fifo_flush)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_tx (
        .clk(clk), .resetn(rst_n), .tx_start(~tx_empty),
        .b_tick(b_tick & tx_en), .data_size(data_size),
        .parity_type(parity_type), .stop_bits_count(stop_bits_count),
        .d_in(tx_data), .tx_done(tx_done), .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_rx (
        .clk(clk), .rst_n(rst_n), .rd(rd), .wr(rx_done),
        .wdata(rx_data), .empty(rx_empty), .full(rx_full),
        .rdata(rdata), .level(rx_level), .flush(rx_fifo_flush)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_rx (
        .clk(clk), .resetn(rst_n), .b_tick(b_tick & rx_en),
        .data_size(data_size), .parity_type(parity_type),
        .stop_bits_count(stop_bits_count), .match_data(match_data),
        .rx(rx_in), .break_flag(break_flag), .match_flag(match_flag),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag), .rx_done(rx_done),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count <= 0;
            samples_count <= 0;
        end else if (b_tick) begin
            if (rx_done) begin
                bits_count <= 0;
                samples_count <= 0;
            end else if (samples_count == SC-1) begin
                samples_count <= 0;
                if (timeout_flag)
                    bits_count <= 0;
                else
                    bits_count <= bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) & ~tx_full;
    assign rx_level_above = (rx_level > rxfifotr) | rx_full;
    assign overrun_flag = rx_full & rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);

    localparam [15:0] A_RXDATA      = 16'h0000;
    localparam [15:0] A_TXDATA      = 16'h0004;
    localparam [15:0] A_PR          = 16'h0008;
    localparam [15:0] A_CTRL        = 16'h000c;
    localparam [15:0] A_CFG         = 16'h0010;
    localparam [15:0] A_MATCH       = 16'h001c;
    localparam [15:0] A_RX_LEVEL    = 16'hfe00;
    localparam [15:0] A_RX_THRESH   = 16'hfe04;
    localparam [15:0] A_RX_FLUSH    = 16'hfe08;
    localparam [15:0] A_TX_LEVEL    = 16'hfe10;
    localparam [15:0] A_TX_THRESH   = 16'hfe14;
    localparam [15:0] A_TX_FLUSH    = 16'hfe18;
    localparam [15:0] A_IM          = 16'hff00;
    localparam [15:0] A_MIS         = 16'hff04;
    localparam [15:0] A_RIS         = 16'hff08;
    localparam [15:0] A_IC          = 16'hff0c;
    localparam [15:0] A_GCLK        = 16'hff10;

    wire wr_xfer = PSEL & PENABLE & PWRITE;
    wire rd_xfer = PSEL & PENABLE & ~PWRITE;

    reg [15:0] prescaler;
    reg [4:0] ctrl;
    reg [13:0] cfg;
    reg [8:0] match_reg;
    reg [3:0] rx_threshold, tx_threshold;
    reg rx_flush, tx_flush;
    reg [9:0] interrupt_mask;
    reg [9:0] interrupt_clear;
    reg gclk;

    wire tx_empty, tx_full, rx_empty, rx_full;
    wire [FAW-1:0] tx_level, rx_level;
    wire [MDW-1:0] rx_rdata;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire tx_write = wr_xfer && (PADDR[15:0] == A_TXDATA);
    wire rx_read  = rd_xfer && (PADDR[15:0] == A_RXDATA);

    wire [9:0] ris_condition = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    reg [9:0] ris;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            prescaler      <= 16'b0;
            ctrl           <= 5'b0;
            cfg            <= 14'h3f08;
            match_reg      <= 9'b0;
            rx_threshold   <= 4'b0;
            tx_threshold   <= 4'b0;
            rx_flush       <= 1'b0;
            tx_flush       <= 1'b0;
            interrupt_mask <= 10'b0;
            interrupt_clear<= 10'b0;
            gclk           <= 1'b0;
        end else begin
            rx_flush        <= 1'b0;
            tx_flush        <= 1'b0;
            interrupt_clear <= 10'b0;

            if (wr_xfer) begin
                case (PADDR[15:0])
                    A_PR:
                        prescaler <= PWDATA[15:0];

                    A_CTRL:
                        ctrl <= PWDATA[4:0];

                    A_CFG:
                        cfg <= PWDATA[13:0];

                    A_MATCH:
                        match_reg <= PWDATA[8:0];

                    A_RX_THRESH:
                        rx_threshold <= PWDATA[3:0];

                    A_TX_THRESH:
                        tx_threshold <= PWDATA[3:0];

                    A_RX_FLUSH:
                        rx_flush <= PWDATA[0];

                    A_TX_FLUSH:
                        tx_flush <= PWDATA[0];

                    A_IM:
                        interrupt_mask <= PWDATA[9:0];

                    A_IC:
                        interrupt_clear <= PWDATA[9:0];

                    A_GCLK:
                        gclk <= PWDATA[0];

                    default:
                        ;
                endcase
            end
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris <= 10'b0;
        else
            ris <= (ris | ris_condition) & ~interrupt_clear;
    end

    assign PREADY = 1'b1;
    assign IRQ = |(ris & interrupt_mask);

    assign PRDATA =
        (PADDR[15:0] == A_RXDATA)    ? {{(32-MDW){1'b0}}, rx_rdata} :
        (PADDR[15:0] == A_PR)        ? {16'b0, prescaler} :
        (PADDR[15:0] == A_CTRL)      ? {27'b0, ctrl} :
        (PADDR[15:0] == A_CFG)       ? {18'b0, cfg} :
        (PADDR[15:0] == A_MATCH)     ? {23'b0, match_reg} :
        (PADDR[15:0] == A_RX_LEVEL)  ? {28'b0, rx_level} :
        (PADDR[15:0] == A_RX_THRESH) ? {28'b0, rx_threshold} :
        (PADDR[15:0] == A_RX_FLUSH)  ? {31'b0, rx_flush} :
        (PADDR[15:0] == A_TX_LEVEL)  ? {28'b0, tx_level} :
        (PADDR[15:0] == A_TX_THRESH) ? {28'b0, tx_threshold} :
        (PADDR[15:0] == A_TX_FLUSH)  ? {31'b0, tx_flush} :
        (PADDR[15:0] == A_IM)        ? {22'b0, interrupt_mask} :
        (PADDR[15:0] == A_MIS)       ? {22'b0, (ris & interrupt_mask)} :
        (PADDR[15:0] == A_RIS)       ? {22'b0, ris} :
        (PADDR[15:0] == A_GCLK)      ? {31'b0, gclk} :
        32'hdeadbeef;

    EF_UART #(
        .MDW(MDW),
        .FAW(FAW),
        .SC(SC),
        .GFLEN(GFLEN)
    ) uart_core (
        .clk(PCLK),
        .rst_n(PRESETn),
        .prescaler(prescaler),
        .en(ctrl[0]),
        .tx_en(ctrl[1]),
        .rx_en(ctrl[2]),
        .rd(rx_read),
        .wr(tx_write),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg[3:0]),
        .stop_bits_count(cfg[4]),
        .parity_type(cfg[7:5]),
        .txfifotr(tx_threshold),
        .rxfifotr(rx_threshold),
        .match_data(match_reg),
        .timeout_bits(cfg[13:8]),
        .loopback_en(ctrl[3]),
        .glitch_filter_en(ctrl[4]),
        .tx_fifo_flush(tx_flush),
        .rx_fifo_flush(rx_flush),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rx_rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx[0]),
        .tx(tx[0])
    );

endmodule

