);

    wire [1:0] tmr_mode = tmr_cfg[1:0];
    wire       tmr_periodic = tmr_cfg[2];

    reg [31:0]    tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg           tmr_run;
    reg           tmr_dir;
    reg           fault_reg;
    reg           fault_armed;

    wire tmr_start_pulse;
    wire tick;

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(tmr_start_pulse)
    );

    assign tick = (pr_reg == {PRW{1'b0}});

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}}, 1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
    end

    wire tmr_eq_reload     = (tmr_reg == tmr_reload);
    wire tmr_eq_zero       = (tmr_reg == 32'd0);
    wire tmr_eq_reload_m1  = (tmr_reg == (tmr_reload - 32'd1));
    wire tmr_eq_one        = (tmr_reg == 32'd1);
    wire tmr_eq_cmpx       = (tmr_reg == cmpx);
    wire tmr_eq_cmpy       = (tmr_reg == cmpy);

    reg [31:0] tmr_reg_next;

    always @* begin
        tmr_reg_next = tmr_reg;

        if (tmr_run && tick) begin
            if ((tmr_mode == 2'b01) && tmr_start)
                tmr_reg_next = tmr_reload;
            else if (((tmr_mode == 2'b10) || (tmr_mode == 2'b11)) &&
                     tmr_start)
                tmr_reg_next = 32'd0;
            else if (tmr_mode == 2'b11) begin
                if (tmr_dir)
                    tmr_reg_next = tmr_reg + 32'd1;
                else
                    tmr_reg_next = tmr_reg - 32'd1;
            end
            else if (tmr_mode == 2'b01) begin
                if (tmr_eq_zero)
                    tmr_reg_next = tmr_periodic ? tmr_reload : tmr_reg;
                else
                    tmr_reg_next = tmr_reg - 32'd1;
            end
            else if (tmr_mode == 2'b10) begin
                if (tmr_eq_reload)
                    tmr_reg_next = tmr_periodic ? 32'd0 : tmr_reg;
                else
                    tmr_reg_next = tmr_reg + 32'd1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_reg <= 32'd0;
        else if (tmr_start_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_reg <= tmr_reload;
            else
                tmr_reg <= 32'd0;
        end
        else if (tmr_en && tick && tmr_run)
            tmr_reg <= tmr_reg_next;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_run <= 1'b0;
        else if (tmr_start_pulse)
            tmr_run <= 1'b1;
        else if (!tmr_periodic && tick && tmr_run &&
                 tmr_mode[0] && tmr_eq_one && !tmr_dir)
            tmr_run <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_dir <= 1'b1;
        else if (tmr_start_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end
        else if (tick) begin
            case (tmr_mode)
                2'b11: begin
                    if (tmr_dir && tmr_eq_reload_m1)
                        tmr_dir <= 1'b0;
                    else if (!tmr_dir && tmr_eq_one)
                        tmr_dir <= 1'b1;
                end
                2'b01: tmr_dir <= 1'b0;
                default: tmr_dir <= 1'b1;
            endcase
        end
    end

    function automatic pwm_action;
        input [1:0] action;
        input       sig;
        begin
            case (action)
                2'b00: pwm_action = sig;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                default: pwm_action = ~sig;
            endcase
        end
    endfunction

    wire event_e0 = tmr_eq_zero && !tmr_eq_cmpx && !tmr_eq_cmpy &&
                    !tmr_eq_reload;
    wire event_e1 = tmr_dir && tmr_eq_cmpx && !tmr_eq_zero &&
                    !tmr_eq_cmpy && !tmr_eq_reload;
    wire event_e2 = tmr_dir && tmr_eq_cmpy && !tmr_eq_zero &&
                    !tmr_eq_cmpx && !tmr_eq_reload;
    wire event_e3 = tmr_eq_reload && !tmr_eq_zero &&
                    !tmr_eq_cmpx && !tmr_eq_cmpy;
    wire event_e4 = !tmr_dir && tmr_eq_cmpy && !tmr_eq_zero &&
                    !tmr_eq_cmpx && !tmr_eq_reload;
    wire event_e5 = !tmr_dir && tmr_eq_cmpx && !tmr_eq_zero &&
                    !tmr_eq_cmpy && !tmr_eq_reload;

    reg pwm0_reg;
    reg pwm1_reg;
    reg pwm0_reg_next;
    reg pwm1_reg_next;

    always @* begin
        pwm0_reg_next = pwm0_reg;
        if (event_e0)
            pwm0_reg_next = pwm_action(pwm0_cfg[1:0], pwm0_reg);
        else if (event_e1)
            pwm0_reg_next = pwm_action(pwm0_cfg[3:2], pwm0_reg);
        else if (event_e2)
            pwm0_reg_next = pwm_action(pwm0_cfg[5:4], pwm0_reg);
        else if (event_e3)
            pwm0_reg_next = pwm_action(pwm0_cfg[7:6], pwm0_reg);
        else if (event_e4)
            pwm0_reg_next = pwm_action(pwm0_cfg[9:8], pwm0_reg);
        else if (event_e5)
            pwm0_reg_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
    end

    always @* begin
        pwm1_reg_next = pwm1_reg;
        if (event_e0)
            pwm1_reg_next = pwm_action(pwm1_cfg[1:0], pwm1_reg);
        else if (event_e1)
            pwm1_reg_next = pwm_action(pwm1_cfg[3:2], pwm1_reg);
        else if (event_e2)
            pwm1_reg_next = pwm_action(pwm1_cfg[5:4], pwm1_reg);
        else if (event_e3)
            pwm1_reg_next = pwm_action(pwm1_cfg[7:6], pwm1_reg);
        else if (event_e4)
            pwm1_reg_next = pwm_action(pwm1_cfg[9:8], pwm1_reg);
        else if (event_e5)
            pwm1_reg_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_reg <= 1'b0;
        else if (pwm0_en && tick) begin
            if (pwm_fault)
                pwm0_reg <= 1'b0;
            else
                pwm0_reg <= pwm0_reg_next;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_reg <= 1'b0;
        else if (pwm1_en && tick) begin
            if (pwm_fault)
                pwm1_reg <= 1'b0;
            else
                pwm1_reg <= pwm1_reg_next;
        end
    end

    reg [7:0] dly_cntr;
    reg       pwm0_delayed;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dly_cntr <= 8'd0;
        else if (tick) begin
            if (dly_cntr == 8'd0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 8'd1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_delayed <= 1'b0;
        else if (tick && (dly_cntr == 8'd0))
            pwm0_delayed <= pwm0_reg;
    end

    reg pwm0_w_dt;
    reg pwm1_w_dt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_w_dt <= 1'b0;
        else if (pwm_dt_en)
            pwm0_w_dt <= pwm0_delayed & pwm0_reg;
        else
            pwm0_w_dt <= pwm0_reg;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_w_dt <= 1'b0;
        else if (pwm_dt_en)
            pwm1_w_dt <= ~pwm0_delayed & ~pwm0_reg;
        else
            pwm1_w_dt <= pwm1_reg;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_armed <= 1'b0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_armed <= 1'b1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_armed <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 1'b0;
        else if (pwm_fault)
            fault_reg <= 1'b1;
        else if (fault_armed &&
                 (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 1'b0;
    end

    assign tmr = tmr_reg;
    assign matchx_flag = tmr_eq_cmpx;
    assign matchy_flag = tmr_eq_cmpy;
    assign timeout_flag = tmr_dir ? tmr_eq_reload : tmr_eq_zero;

    assign pwm0 = (pwm0_w_dt ^ pwm0_inv) & ~fault_reg &
                  ~pwm_fault & pwm0_en;
    assign pwm1 = (pwm1_w_dt ^ pwm1_inv) & ~fault_reg &
                  ~pwm_fault & pwm1_en;

endmodule

module EF_TMR32_APB #(
