    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'd0;
        else begin
            if (IC_REG[0])
                RIS_REG[0] <= 1'b0;
            else if (timeout_flag)
                RIS_REG[0] <= 1'b1;

            if (IC_REG[1])
                RIS_REG[1] <= 1'b0;
            else if (matchx_flag)
                RIS_REG[1] <= 1'b1;

            if (IC_REG[2])
                RIS_REG[2] <= 1'b0;
            else if (matchy_flag)
                RIS_REG[2] <= 1'b1;
        end
    end

    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk            (PCLK),
        .rst_n          (PRESETn),
        .tmr_en        (CTRL_REG[0]),
        .tmr_start     (CTRL_REG[1]),
        .pwm0_en       (CTRL_REG[2]),
        .pwm1_en       (CTRL_REG[3]),
        .tmr_reload    (RELOAD_REG),
        .cmpx          (CMPX_REG),
        .cmpy          (CMPY_REG),
        .prescaler     (PR_REG),
