module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size, input wire stop_bits_count,
    input wire [2:0] parity_type, input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done, output wire parity_error,
    output wire frame_error, output wire break_flag,
    output wire match_flag, output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count, bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_bad, frame_bad;
    reg [11:0] break_count;

    wire parity_enabled = parity_type != 3'b000;
    wire last_data_bit = bit_count == data_size - 1'b1;
    wire last_sample = sample_count == NUM_SAMPLES - 1;
    wire mid_start = sample_count == (NUM_SAMPLES/2 - 1);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_bad <= 0;
            frame_bad <= 0;
            break_count <= 0;
        end else begin
            if (b_tick && state != IDLE && sample_count == NUM_SAMPLES-1) begin
                if (!rx)
                    break_count <= (break_count == 12'hfff) ?
                                   break_count : break_count + 1'b1;
                else
                    break_count <= 0;
            end else if (state == IDLE) begin
                break_count <= 0;
            end

            if (b_tick) begin
                case (state)
                    IDLE: begin
                        sample_count <= 0;
                        if (!rx) begin
                            state <= START;
                            parity_bad <= 0;
                            frame_bad <= 0;
                        end
                    end

                    START: begin
                        if (mid_start) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    DATA: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg[bit_count] <= rx;
                            if (last_data_bit)
                                state <= parity_enabled ? PARITY : STOP0;
                            else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    PARITY: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            case (parity_type)
                                3'b001: if (rx != ~^data_reg) parity_bad <= 1'b1;
                                3'b010: if (rx != ^data_reg)  parity_bad <= 1'b1;
                                3'b100: if (rx != 1'b0)        parity_bad <= 1'b1;
                                3'b101: if (rx != 1'b1)        parity_bad <= 1'b1;
                                default: ;
                            endcase
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    STOP0: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            if (!rx) frame_bad <= 1'b1;
                            if (stop_bits_count)
                                state <= STOP1;
                            else
                                state <= IDLE;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    STOP1: begin
                        if (last_sample) begin
                            sample_count <= 0;
                            if (!rx) frame_bad <= 1'b1;
                            state <= IDLE;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end

                    default: state <= IDLE;
                endcase
            end
        end
    end

    always @* begin
        rx_done = 1'b0;
        if (b_tick && (state == STOP0 || state == STOP1) &&
            last_sample && (!stop_bits_count || state == STOP1))
            rx_done = 1'b1;
    end

    assign dout = data_reg;
    assign parity_error = rx_done && parity_bad;
    assign frame_error = rx_done && frame_bad;
    assign match_flag = rx_done && (data_reg == match_data);
    assign break_flag = break_count == 12'd0 && state != IDLE;
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick, input wire [3:0] data_size,
    input wire stop_bits_count, input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in, output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count, bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire last_sample = sample_count == NUM_SAMPLES-1;
    wire last_data = bit_count == data_size-1;
    wire [MDW-1:0] pdata =
        data_reg & ({MDW{1'b1}} >> (MDW-data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    if (tx_start) begin
                        data_reg <= d_in;
                        state <= START;
                        tx_reg <= 1'b0;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg <= data_reg >> 1;
                            if (last_data)
                                state <= parity_type == 3'b000 ? STOP0 : PARITY;
                            else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^pdata;
                        3'b010: tx_reg <= ^pdata;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b0;
                    endcase
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else
                                state <= IDLE;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state <= IDLE;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    always @* begin
        tx_done = 1'b0;
        if (b_tick && ((state == STOP0 && !stop_bits_count) ||
                       (state == STOP1)) && last_sample)
            tx_done = 1'b1;
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC=8, MDW=9, GFLEN=8, FAW=4
) (
