        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_thresh_reg <= 0;
            tx_thresh_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
        end else begin
            ic_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;

