            if (write && addr == CTRL)     ctrl_reg <= PWDATA[4:0];
            if (write && addr == CFG)      cfg_reg <= PWDATA[13:0];
            if (write && addr == MATCH)    match_reg <= PWDATA[MDW-1:0];
            if (write && addr == RXTHRESH) rx_thresh_reg <= PWDATA[FAW-1:0];
            if (write && addr == TXTHRESH) tx_thresh_reg <= PWDATA[FAW-1:0];
            if (write && addr == RXFLUSH)  rx_flush_reg <= PWDATA[0];
            if (write && addr == TXFLUSH)  tx_flush_reg <= PWDATA[0];
            if (write && addr == GCLK)     gclk_reg <= PWDATA[0];
            if (write && addr == IM)       im_reg <= PWDATA[9:0];
            if (write && addr == IC)       ic_reg <= PWDATA[9:0];
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | conditions;
    end

    EF_UART #(.SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)) core (
        .clk(PCLK), .rst_n(PRESETn),
        .prescaler(pr_reg), .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]), .rx_en(ctrl_reg[2]),
        .rd(rd), .wr(wr), .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]), .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_thresh_reg), .rxfifotr(rx_thresh_reg),
        .match_data(match_reg), .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]), .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg), .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty), .tx_full(tx_full), .tx_level(tx_level),
        .tx_level_below(tx_below), .rdata(rx_data),
        .rx_empty(rx_empty), .rx_full(rx_full), .rx_level(rx_level),
        .rx_level_above(rx_above), .break_flag(brk), .match_flag(match),
        .frame_error_flag(fe), .parity_error_flag(pre),
        .overrun_flag(overrun), .timeout_flag(rto),
        .rx(rx), .tx(tx)
    );

    always @* begin
        case (addr)
            RXDATA:   PRDATA = {{(32-MDW){1'b0}}, rx_data};
            PR:       PRDATA = {{16{1'b0}}, pr_reg};
            CTRL:     PRDATA = {{27{1'b0}}, ctrl_reg};
            CFG:      PRDATA = {{18{1'b0}}, cfg_reg};
            MATCH:    PRDATA = {{(32-MDW){1'b0}}, match_reg};
            RXLEVEL:  PRDATA = {{(32-FAW){1'b0}}, rx_level};
            RXTHRESH: PRDATA = {{(32-FAW){1'b0}}, rx_thresh_reg};
            RXFLUSH:  PRDATA = {31'b0, rx_flush_reg};
            TXLEVEL:  PRDATA = {{(32-FAW){1'b0}}, tx_level};
            TXTHRESH: PRDATA = {{(32-FAW){1'b0}}, tx_thresh_reg};
            TXFLUSH:  PRDATA = {31'b0, tx_flush_reg};
            IM:       PRDATA = {22'b0, im_reg};
            MIS:      PRDATA = {22'b0, ris_reg & im_reg};
            RIS:      PRDATA = {22'b0, ris_reg};
            GCLK:     PRDATA = {31'b0, gclk_reg};
            default:  PRDATA = 32'hdeadbeef;
        endcase
    end

    assign IRQ = |(ris_reg & im_reg);
    assign PREADY = 1'b1;
