module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick, input wire [3:0] data_size,
    input wire stop_bits_count, input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in, output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [3:0] sample_count, bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire last_sample = sample_count == NUM_SAMPLES-1;
    wire last_data = bit_count == data_size-1;
    wire [MDW-1:0] pdata =
        data_reg & ({MDW{1'b1}} >> (MDW-data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    if (tx_start) begin
                        data_reg <= d_in;
                        state <= START;
                        tx_reg <= 1'b0;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            data_reg <= data_reg >> 1;
                            if (last_data)
                                state <= parity_type == 3'b000 ? STOP0 : PARITY;
                            else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^pdata;
                        3'b010: tx_reg <= ^pdata;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b0;
                    endcase
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else
                                state <= IDLE;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (last_sample) begin
                            sample_count <= 0;
                            state <= IDLE;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    always @* begin
        tx_done = 1'b0;
        if (b_tick && ((state == STOP0 && !stop_bits_count) ||
                       (state == STOP1)) && last_sample)
            tx_done = 1'b1;
    end

    assign tx = tx_reg;
endmodule

