        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out <= 1'b0;
