    localparam DEPTH = 2**AW;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr, rptr;
    reg [AW-1:0] count;

    wire write_accept = wr && !full;
    wire read_accept = rd && !empty;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= 'b0;
            rptr <= 'b0;
            count <= 'b0;
        end else if (flush) begin
            wptr <= 'b0;
            rptr <= 'b0;
            count <= 'b0;
        end else begin
            if (write_accept)
                mem[wptr] <= wdata;

            if (write_accept)
                wptr <= wptr + 1'b1;
            if (read_accept)
                rptr <= rptr + 1'b1;

            if (write_accept && !read_accept)
                count <= count + 1'b1;
            else if (!write_accept && read_accept)
                count <= count - 1'b1;
        end
    end

    assign rdata = mem[rptr];
    assign empty = (count == 'b0);
    assign full = (count == {AW{1'b1}});
    assign level = count;
