module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire tx_start, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                   PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx_reg;
    wire [MDW-1:0] parity_data =
        data_reg & ({MDW{1'b1}} >> (MDW - data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            tx_reg <= next_tx_reg;
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_tx_reg = tx_reg;
        tx_done = 1'b0;

        case (state)
            IDLE: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state = START;
                    next_sample_count = 0;
                    next_bit_count = 0;
                    next_data_reg = d_in;
                end
            end

            START: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^parity_data;
                    3'b010: next_tx_reg =  ^parity_data;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b0;
                endcase
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                   PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [4:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, frame_error_reg;
    reg parity_error_next, frame_error_next;
    reg [11:0] break_reg;

    wire [MDW-1:0] received_data =
        data_reg >> (MDW - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_error_reg <= 0;
            frame_error_reg <= 0;
            break_reg <= 12'hfff;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;

            if (state == IDLE) begin
                parity_error_reg <= 1'b0;
                frame_error_reg <= 1'b0;
            end else begin
                if (parity_error_next)
                    parity_error_reg <= 1'b1;
                if (frame_error_next)
                    frame_error_reg <= 1'b1;
            end

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    break_reg <= 12'hfff;
                else
                    break_reg <= {break_reg[10:0], rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        parity_error_next = 1'b0;
        frame_error_next = 1'b0;
        rx_done = 1'b0;

        case (state)
            IDLE: begin
                if (b_tick && !rx) begin
                    next_state = START;
                    next_sample_count = 0;
                end
            end

            START: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                        case (parity_type)
                            3'b001: parity_error_next = ((~^received_data) != rx);
                            3'b010: parity_error_next = (( ^received_data) != rx);
                            3'b100: parity_error_next = (1'b0 != rx);
                            3'b101: parity_error_next = (1'b1 != rx);
                            default: parity_error_next = 1'b0;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        frame_error_next = !rx;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        frame_error_next = !rx;
                        rx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign dout = received_data;
    assign parity_error = parity_error_next && rx_done;
    assign frame_error = frame_error_next && rx_done;
    assign match_flag = (received_data == match_data) && rx_done;
    assign break_flag = (break_reg == 12'd0);
endmodule

module EF_UART #(parameter MDW=9, FAW=4, SC=8, GFLEN=8) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
