        if (!rst_n) begin
            counter <= '0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (clk_div == '0) ? 1'b1 : (counter == '0);
            if (counter == '0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
