    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr <= '0;
            wptr <= '0;
            level_reg <= '0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else if (flush) begin
            rptr <= '0;
            wptr <= '0;
            level_reg <= '0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else begin
            case ({wr_en, rd_en})
                2'b10: begin
                    wptr <= wptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((wptr + 1'b1) == rptr)
                        full_reg <= 1'b1;
