    wire parity_error_flag, overrun_flag, timeout_flag;
    wire tx_fifo_flush = TX_FLUSH_REG;
    wire rx_fifo_flush = RX_FLUSH_REG;
    wire tx_wr = apb_we && (addr == TXDATA);
    wire rx_rd = apb_re && (addr == RXDATA);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            PR_REG <= 0;
            CTRL_REG <= 0;
            CFG_REG <= 14'h3f08;
            MATCH_REG <= 0;
            RX_THRESHOLD_REG <= 0;
            TX_THRESHOLD_REG <= 0;
            RX_FLUSH_REG <= 0;
            TX_FLUSH_REG <= 0;
            GCLK_REG <= 0;
            IM_REG <= 0;
            IC_REG <= 0;
        end else begin
            IC_REG <= 0;
            RX_FLUSH_REG <= 0;
            TX_FLUSH_REG <= 0;

            if (apb_we && addr == PR) PR_REG <= PWDATA[15:0];
            if (apb_we && addr == CTRL) CTRL_REG <= PWDATA[4:0];
            if (apb_we && addr == CFG) CFG_REG <= PWDATA[13:0];
            if (apb_we && addr == MATCH) MATCH_REG <= PWDATA[MDW-1:0];
            if (apb_we && addr == RX_THRESHOLD)
                RX_THRESHOLD_REG <= PWDATA[3:0];
            if (apb_we && addr == TX_THRESHOLD)
                TX_THRESHOLD_REG <= PWDATA[3:0];
            if (apb_we && addr == RX_FLUSH)
                RX_FLUSH_REG <= PWDATA[0];
            if (apb_we && addr == TX_FLUSH)
                TX_FLUSH_REG <= PWDATA[0];
            if (apb_we && addr == GCLK)
                GCLK_REG <= PWDATA[0];
            if (apb_we && addr == IM)
                IM_REG <= PWDATA[9:0];
            if (apb_we && addr == IC)
                IC_REG <= PWDATA[9:0];
