    wire [9:0] raw_status = {
        timeout_flag, overrun_flag, parity_error_flag,
        frame_error_flag, match_flag, break_flag,
        rx_level_above, tx_level_below, rx_full, tx_empty
    };

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 0;
        else
            RIS_REG <= (RIS_REG & ~IC_REG) | raw_status;
