module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);
    reg [NUM_STAGES-1:0] sync;
    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};
    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [W-1:0] clk_div,
    output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= '0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (counter == '0);
            if (counter == '0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk,
    input wire rst_n,
    input wire in,
    input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= '0;
            out <= 1'b0;
        end else begin
            if (tick)
                shifter <= {shifter[N-2:0], in};

            if (&shifter)
                out <= 1'b1;
            else if (~|shifter)
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk,
    input wire rst_n,
    input wire rd,
    input wire wr,
    input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty,
    output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr, rptr;
    reg [AW-1:0] level_reg;
    reg empty_reg, full_reg;

    wire write_accept = wr && !full_reg;
    wire read_accept = rd && !empty_reg;

    always @(posedge clk) begin
        if (write_accept)
            mem[wptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= '0;
            rptr <= '0;
            level_reg <= '0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else if (flush) begin
            wptr <= '0;
            rptr <= '0;
            level_reg <= '0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else begin
            case ({write_accept, read_accept})
                2'b10: begin
                    wptr <= wptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((wptr + 1'b1) == rptr)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    rptr <= rptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg <= 1'b0;
                    if ((rptr + 1'b1) == wptr)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    wptr <= wptr + 1'b1;
                    rptr <= rptr + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

    assign rdata = mem[rptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;
endmodule

module ef_util_gating_cell (
`ifdef USE_POWER_PINS
    input wire vpwr,
    input wire vgnd,
`endif
    input wire clk,
    input wire rst_n,
    input wire clk_en,
    output wire clk_o
);
`ifdef CLKG_SKY130_HD
    sky130_fd_sc_hd__dlclkp_4 clk_gate (
`ifdef USE_POWER_PINS
        .VPWR(vpwr),
        .VGND(vgnd),
        .VNB(vpwr),
        .VPB(vgnd),
`endif
        .GCLK(clk_o),
        .GATE(clk_en),
        .CLK(clk)
    );
`elsif CLKG_GENERIC
    assign clk_o = clk & clk_en;
`else
    assign clk_o = clk;
`endif
endmodule

module EF_UART #(
    parameter MDW=9,
    parameter FAW=4,
    parameter SC=8,
    parameter GFLEN=8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire baud_tick;
    wire [MDW-1:0] tx_data;
    wire [MDW-1:0] rx_data;
    wire rx_syncd, rx_filtered, rx_in;
    wire tx_done, rx_done;

    ef_util_sync rx_sync (
        .clk(clk),
        .in(rx),
        .out(rx_syncd)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_syncd),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_syncd;

    BAUDGEN baudgen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) transmitter (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(baud_tick & tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) receiver (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(baud_tick & rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .match_data(match_data),
        .rx(rx_in),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count <= 6'd0;
            samples_count <= 5'd0;
        end else if (baud_tick && rx_en) begin
            if (rx_done) begin
                bits_count <= 6'd0;
                samples_count <= 5'd0;
            end else if (samples_count == SC-1) begin
                samples_count <= 5'd0;
                if (timeout_flag)
                    bits_count <= 6'd0;
                else
                    bits_count <= bits_count + 1'b1;
            end else begin
                samples_count <= samples_count + 1'b1;
            end
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_full && rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 :
                         count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    wire [MDW-1:0] received_data = data_reg >> (MDW-data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_error_reg <= 0;
            frame_error_reg <= 0;
            break_shift <= 12'hfff;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data;
            parity_error_reg <= next_parity_error;
            frame_error_reg <= next_frame_error;

            if (b_tick && sample_count == NUM_SAMPLES-1) begin
                if (state == IDLE)
                    break_shift <= 12'hfff;
                else
                    break_shift <= {break_shift[10:0], rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data = data_reg;
        next_parity_error = parity_error_reg;
        next_frame_error = frame_error_reg;
        rx_done = 1'b0;

        if (state == IDLE) begin
            next_parity_error = 1'b0;
            next_frame_error = 1'b0;
        end

        case (state)
            IDLE: begin
                if (b_tick && !rx) begin
                    next_state = START;
                    next_sample_count = 0;
                end
            end

            START: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                        case (parity_type)
                            3'b001: next_parity_error = ((~^received_data) != rx);
                            3'b010: next_parity_error = (( ^received_data) != rx);
                            3'b100: next_parity_error = (1'b0 != rx);
                            3'b101: next_parity_error = (1'b1 != rx);
                            default: next_parity_error = 1'b0;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx)
                            next_frame_error = 1'b1;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign dout = received_data;
    assign parity_error = parity_error_reg && rx_done;
    assign frame_error = frame_error_reg && rx_done;
    assign break_flag = (break_shift == 12'd0);
    assign match_flag = (received_data == match_data) && rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data;
    reg tx_reg, next_tx;

    wire [MDW-1:0] parity_data =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data;
            tx_reg <= next_tx;
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data = data_reg;
        next_tx = tx_reg;
        tx_done = 1'b0;

        case (state)
            IDLE: begin
                next_tx = 1'b1;
                if (tx_start) begin
                    next_state = START;
                    next_sample_count = 0;
                    next_data = d_in;
                end
            end

            START: begin
                next_tx = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                next_tx = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                case (parity_type)
                    3'b001: next_tx = ~^parity_data;
                    3'b010: next_tx =  ^parity_data;
                    3'b100: next_tx = 1'b0;
                    3'b101: next_tx = 1'b1;
                    default: next_tx = 1'b0;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0, STOP1: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (state == STOP0 && stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC=8,
    parameter MDW=9,
    parameter GFLEN=8,
    parameter FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA=16'h0000, TXDATA=16'h0004, PR=16'h0008,
               CTRL=16'h000c, CFG=16'h0010, MATCH=16'h001c,
               RX_LEVEL=16'hfe00, RX_THRESHOLD=16'hfe04,
               RX_FLUSH=16'hfe08, TX_LEVEL=16'hfe10,
               TX_THRESHOLD=16'hfe14, TX_FLUSH=16'hfe18,
               IM=16'hff00, MIS=16'hff04, RIS=16'hff08,
               IC=16'hff0c, GCLK=16'hff10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg, tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire clk_g;
    ef_util_gating_cell gate (
        .clk(PCLK),
        .rst_n(PRESETn),
        .clk_en(gclk_reg),
        .clk_o(clk_g)
    );

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag, parity_error_flag;
    wire overrun_flag, timeout_flag;

    wire rx_rd = apb_re && (PADDR[15:0] == RXDATA);
    wire tx_wr = apb_we && (PADDR[15:0] == TXDATA);

    EF_UART #(.SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)) uart (
        .clk(clk_g),
        .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]),
        .rx_en(ctrl_reg[2]),
        .rd(rx_rd),
        .wr(tx_wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_threshold_reg),
        .rxfifotr(rx_threshold_reg),
        .match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_threshold_reg <= 0;
            tx_threshold_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 10'd0;

            if (apb_we && PADDR[15:0] == PR)
                pr_reg <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == CTRL)
                ctrl_reg <= PWDATA[4:0];
            if (apb_we && PADDR[15:0] == CFG)
                cfg_reg <= PWDATA[13:0];
            if (apb_we && PADDR[15:0] == MATCH)
                match_reg <= PWDATA[MDW-1:0];
            if (apb_we && PADDR[15:0] == RX_THRESHOLD)
                rx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == TX_THRESHOLD)
                tx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == RX_FLUSH)
                rx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == TX_FLUSH)
                tx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == GCLK)
                gclk_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == IM)
                im_reg <= PWDATA[9:0];
            if (apb_we && PADDR[15:0] == IC)
                ic_reg <= PWDATA[9:0];
        end
    end

    wire [9:0] raw_events = {
        timeout_flag, overrun_flag, parity_error_flag, frame_error_flag,
        match_flag, break_flag, rx_level_above, tx_level_below,
        rx_full, tx_empty
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'd0;
        else begin
            for (i=0; i<10; i=i+1) begin
                if (ic_reg[i])
                    ris_reg[i] <= 1'b0;
                else if (raw_events[i])
                    ris_reg[i] <= 1'b1;
            end
        end
    end

    assign PRDATA =
        (PADDR[15:0] == RXDATA)       ? rdata :
        (PADDR[15:0] == PR)           ? {{16{1'b0}}, pr_reg} :
        (PADDR[15:0] == CTRL)         ? {{27{1'b0}}, ctrl_reg} :
        (PADDR[15:0] == CFG)          ? {{18{1'b0}}, cfg_reg} :
        (PADDR[15:0] == MATCH)        ? {{(32-MDW){1'b0}}, match_reg} :
        (PADDR[15:0] == RX_LEVEL)     ? {{(32-FAW){1'b0}}, rx_level} :
        (PADDR[15:0] == RX_THRESHOLD) ? {{(32-FAW){1'b0}}, rx_threshold_reg} :
