            data_st: begin
                tx_next = data_reg[0];
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if (count_reg == (data_size - 1)) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end

            parity_st: begin
                case (parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 1'b0;
                    3'b101: tx_next = 1'b1;
                    default: tx_next = 1'b0;
                endcase
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop0_st: begin
                tx_next = 1'b1;
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop1_st: begin
                tx_next = 1'b1;
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end
