    input wire [2:0] parity_type,input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,input wire loopback_en,
    input wire glitch_filter_en,input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,output wire tx_full,output wire [FAW-1:0] tx_level,
    output wire tx_level_below,output wire [MDW-1:0] rdata,
    output wire rx_empty,output wire rx_full,output wire [FAW-1:0] rx_level,
    output wire rx_level_above,output wire break_flag,
    output wire match_flag,output wire frame_error_flag,
    output wire parity_error_flag,output wire overrun_flag,
    output wire timeout_flag,input wire rx,output wire tx
);
    wire tick,tx_done,rx_done;
    wire [MDW-1:0] tx_data,rx_data;
    wire rx_sync,rx_filter,rx_in;
    reg [5:0] timeout_count;
    reg [4:0] sample_count;

    ef_util_sync sync_i(.clk(clk),.in(rx),.out(rx_sync));
    ef_util_glitch_filter #(.N(GFLEN)) filter_i(
        .clk(clk),.rst_n(rst_n),.in(rx_sync),
        .en(glitch_filter_en),.out(rx_filter)
    );
    assign rx_in = loopback_en ? tx : glitch_filter_en ? rx_filter : rx_sync;

    BAUDGEN baud_i(
        .clk(clk),.rst_n(rst_n),.prescale(prescaler),
        .en(en),.baudtick(tick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo(
        .clk(clk),.rst_n(rst_n),.rd(tx_done),.wr(wr),
        .flush(tx_fifo_flush),.wdata(wdata),
        .empty(tx_empty),.full(tx_full),
        .rdata(tx_data),.level(tx_level)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) rx_fifo(
        .clk(clk),.rst_n(rst_n),.rd(rd),.wr(rx_done),
        .flush(rx_fifo_flush),.wdata(rx_data),
        .empty(rx_empty),.full(rx_full),
        .rdata(rdata),.level(rx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC),.MDW(MDW)) tx_i(
        .clk(clk),.resetn(rst_n),.tx_start(~tx_empty),
        .b_tick(tick & tx_en),.data_size(data_size),
        .stop_bits_count(stop_bits_count),.parity_type(parity_type),
        .d_in(tx_data),.tx_done(tx_done),.tx(tx)
    );

    UART_RX #(.NUM_SAMPLES(SC),.MDW(MDW)) rx_i(
        .clk(clk),.resetn(rst_n),.b_tick(tick & rx_en),
        .data_size(data_size),.stop_bits_count(stop_bits_count),
        .parity_type(parity_type),.rx(rx_in),
        .match_data(match_data),.rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),.break_flag(break_flag),
        .match_flag(match_flag),.dout(rx_data)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            sample_count <= 0;
        end else if (tick) begin
            if (rx_done) begin
                timeout_count <= 0;
                sample_count <= 0;
            end else if (sample_count == SC-1) begin
                sample_count <= 0;
                if (timeout_count == timeout_bits)
                    timeout_count <= 0;
