    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 1 << AW;
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rp,wp;
    reg [AW-1:0] level_r;
    reg empty_r,full_r;
    wire do_wr = wr & ~full_r;
    wire do_rd = rd & ~empty_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rp <= '0;
            wp <= '0;
            level_r <= '0;
            empty_r <= 1'b1;
            full_r <= 1'b0;
        end else if (flush) begin
            rp <= '0;
            wp <= '0;
            level_r <= '0;
            empty_r <= 1'b1;
            full_r <= 1'b0;
        end else begin
            if (do_wr)
                mem[wp] <= wdata;
            case ({do_wr,do_rd})
                2'b10: begin
                    wp <= wp + 1'b1;
                    level_r <= level_r + 1'b1;
                    empty_r <= 1'b0;
                    if ((wp + 1'b1) == rp)
                        full_r <= 1'b1;
                end
                2'b01: begin
                    rp <= rp + 1'b1;
                    level_r <= level_r - 1'b1;
                    full_r <= 1'b0;
                    if ((rp + 1'b1) == wp)
                        empty_r <= 1'b1;
                end
                2'b11: begin
                    wp <= wp + 1'b1;
                    rp <= rp + 1'b1;
                end
                default: ;
            endcase
