        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data <= 0;
            parity_err_r <= 0;
            frame_err_r <= 0;
            brk <= 12'hfff;
            rx_done <= 0;
        end else begin
            rx_done <= 1'b0;
            if (b_tick) begin
                case (state)
                    IDLE: begin
                        parity_err_r <= 0;
                        frame_err_r <= 0;
                        brk <= 12'hfff;
                        if (!rx) begin
                            state <= START;
                            sample_count <= 0;
                        end
                    end
                    START: begin
                        if (sample_count == NUM_SAMPLES/2-1) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else sample_count <= sample_count + 1'b1;
                    end
                    DATA: begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data <= {rx,data[MDW-1:1]};
                            if (bit_count == data_size-1)
                                state <= (parity_type == 3'b000) ? STOP0 : PARITY;
                            else bit_count <= bit_count + 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                    PARITY: begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            case (parity_type)
                                3'b001: parity_err_r <= ((~^data) != rx);
                                3'b010: parity_err_r <= (( ^data) != rx);
                                3'b100: parity_err_r <= (rx != 1'b0);
                                3'b101: parity_err_r <= (rx != 1'b1);
                                default: parity_err_r <= 1'b0;
                            endcase
                            state <= STOP0;
                        end else sample_count <= sample_count + 1'b1;
