module ef_util_ticker #(parameter W=8) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [W-1:0] clk_div,
    output wire tick
);
    reg [W-1:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count <= {W{1'b0}};
        else if (!en)
            count <= {W{1'b0}};
        else if (count >= (clk_div - 1'b1))
            count <= {W{1'b0}};
        else
            count <= count + 1'b1;
    end

    assign tick = en && (count >= (clk_div - 1'b1));
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input wire clk,
