module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [4:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_reg;
    reg tx_reg;

    wire last_sample = (sample_count == NUM_SAMPLES-1);

    function automatic parity_value;
        input [MDW-1:0] value;
        input [3:0] width;
        integer k;
        reg x;
        begin
            x = 1'b0;
            for (k = 0; k < MDW; k = k + 1)
                if (k < width)
                    x = x ^ value[k];

            case (parity_type)
                3'b001: parity_value = ~x;
                3'b010: parity_value = x;
                3'b100: parity_value = 1'b0;
                3'b101: parity_value = 1'b1;
                default: parity_value = 1'b0;
            endcase
        end
    endfunction

    always @* begin
        tx_done = 1'b0;
        if (b_tick && last_sample) begin
            if ((state == STOP0) && !stop_bits_count)
                tx_done = 1'b1;
            else if (state == STOP1)
                tx_done = 1'b1;
        end
    end

    assign tx = tx_reg;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_reg <= 0;
            tx_reg <= 1'b1;
        end else if (b_tick) begin
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    if (tx_start) begin
                        data_reg <= d_in;
                        parity_reg <= parity_value(d_in, data_size);
                        bit_count <= 0;
                        tx_reg <= 1'b0;
                        state <= START;
                    end
                end

                START: begin
                    if (last_sample) begin
                        sample_count <= 0;
                        bit_count <= 0;
                        tx_reg <= data_reg[0];
                        state <= DATA;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                DATA: begin
                    if (last_sample) begin
                        sample_count <= 0;
                        if (bit_count == data_size - 1) begin
                            if (parity_type != 3'b000) begin
                                tx_reg <= parity_reg;
                                state <= PARITY;
                            end else begin
                                tx_reg <= 1'b1;
                                state <= STOP0;
                            end
                        end else begin
                            bit_count <= bit_count + 1'b1;
                            tx_reg <= data_reg[bit_count + 1'b1];
                        end
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                PARITY: begin
                    if (last_sample) begin
                        sample_count <= 0;
                        tx_reg <= 1'b1;
                        state <= STOP0;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (last_sample) begin
                        sample_count <= 0;
                        if (stop_bits_count)
                            state <= STOP1;
                        else
                            state <= IDLE;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (last_sample) begin
                        sample_count <= 0;
                        state <= IDLE;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                default: begin
                    state <= IDLE;
                    tx_reg <= 1'b1;
                end
            endcase
        end
    end
endmodule

