            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
            level_reg <= 'd0;
        end else begin
            w_ptr_reg <= w_ptr_next;
            r_ptr_reg <= r_ptr_next;
            full_reg <= full_next;
            empty_reg <= empty_next;
            level_reg <= level_next;
