                if (!full_reg) begin
                    w_ptr_next = w_ptr_succ;
                    empty_next = 1'b0;
                    level_next = level_reg + 1'b1;
                    if (w_ptr_succ == r_ptr_reg)
                        full_next = 1'b1;
                end
