    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_glitch_filter (
        .clk(clk), .rst_n(rst_n), .en(glitch_filter_en),
        .in(rx_synched), .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_synched;

    BAUDGEN baud_gen (
        .clk(clk), .rst_n(rst_n), .prescale(prescaler),
        .en(en), .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_tx (
        .clk(clk), .rst_n(rst_n), .rd(tx_done), .wr(wr),
        .wdata(wdata), .empty(tx_empty), .full(tx_full),
        .rdata(tx_data), .level(tx_level), .flush(tx_fifo_flush)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_tx (
        .clk(clk), .resetn(rst_n), .tx_start(~tx_empty),
        .b_tick(b_tick & tx_en), .data_size(data_size),
        .parity_type(parity_type), .stop_bits_count(stop_bits_count),
        .d_in(tx_data), .tx_done(tx_done), .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_rx (
        .clk(clk), .rst_n(rst_n), .rd(rd), .wr(rx_done),
        .wdata(rx_data), .empty(rx_empty), .full(rx_full),
        .rdata(rdata), .level(rx_level), .flush(rx_fifo_flush)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_rx (
        .clk(clk), .resetn(rst_n), .b_tick(b_tick & rx_en),
        .data_size(data_size), .parity_type(parity_type),
        .stop_bits_count(stop_bits_count), .match_data(match_data),
        .rx(rx_in), .break_flag(break_flag), .match_flag(match_flag),
        .parity_error(parity_error_flag), .frame_error(frame_error_flag),
        .rx_done(rx_done), .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count <= 0;
            samples_count <= 0;
        end else if (b_tick) begin
            if (rx_done) begin
                bits_count <= 0;
                samples_count <= 0;
            end else if (samples_count == (SC - 1)) begin
                samples_count <= 0;
                if (timeout_flag)
                    bits_count <= 0;
                else
                    bits_count <= bits_count + 1'b1;
            end else begin
                samples_count <= samples_count + 1'b1;
            end
        end
    end

    assign tx_level_below = (tx_level < txfifotr) & ~tx_full;
    assign rx_level_above = (rx_level > rxfifotr) | rx_full;
    assign overrun_flag = rx_full & rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 0 : count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st=3'b000, start_st=3'b001, data_st=3'b010,
               parity_st=3'b011, stop0_st=3'b100, stop1_st=3'b101;

    reg [2:0] current_state, next_state;
    reg [3:0] b_reg, b_next, count_reg, count_next;
    reg [8:0] data_reg, data_next;
    reg p_error_reg, p_error_next, f_error_reg, f_error_next;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            if (current_state == idle_st)
                p_error_reg <= 0;
            else if (p_error_next)
                p_error_reg <= 1;
            if (current_state == idle_st)
                f_error_reg <= 0;
            else if (f_error_next)
                f_error_reg <= 1;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        rx_done = 0;
        p_error_next = 0;
        f_error_next = 0;

        case (current_state)
            idle_st:
                if (!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end

            start_st:
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES/2 - 1)) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;

            data_st:
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if (count_reg == (data_size - 1)) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;

            parity_st:
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if (~^dout != rx) p_error_next = 1'b1;
                            3'b010: if (^dout != rx) p_error_next = 1'b1;
                            3'b100: if (1'b0 != rx) p_error_next = 1'b1;
                            3'b101: if (1'b1 != rx) p_error_next = 1'b1;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;

            stop0_st:
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        if (!rx) f_error_next = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;

            stop1_st:
                if (b_tick)
                    if (b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx) f_error_next = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
        endcase
    end

    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && (b_reg == NUM_SAMPLES - 1)) begin
            if (current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout = data_reg >> (9-data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [4:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_reg;
    reg tx_reg;

    wire last_sample = (sample_count == NUM_SAMPLES-1);

    function automatic parity_value;
        input [MDW-1:0] value;
        input [3:0] width;
        integer k;
        reg x;
        begin
            x = 1'b0;
            for (k = 0; k < MDW; k = k + 1)
                if (k < width)
                    x = x ^ value[k];

            case (parity_type)
                3'b001: parity_value = ~x;
                3'b010: parity_value = x;
                3'b100: parity_value = 1'b0;
                3'b101: parity_value = 1'b1;
                default: parity_value = 1'b0;
            endcase
        end
    endfunction

    always @* begin
        tx_done = 1'b0;
        if (b_tick && last_sample) begin
            if ((state == STOP0) && !stop_bits_count)
                tx_done = 1'b1;
            else if (state == STOP1)
                tx_done = 1'b1;
        end
    end

    assign tx = tx_reg;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_reg <= 0;
            tx_reg <= 1'b1;
        end else if (b_tick) begin
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    if (tx_start) begin
                        data_reg <= d_in;
                        parity_reg <= parity_value(d_in, data_size);
                        bit_count <= 0;
                        tx_reg <= 1'b0;
                        state <= START;
                    end
                end

                START: begin
                    if (last_sample) begin
                        sample_count <= 0;
                        bit_count <= 0;
                        tx_reg <= data_reg[0];
                        state <= DATA;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                DATA: begin
                    if (last_sample) begin
                        sample_count <= 0;
                        if (bit_count == data_size - 1) begin
                            if (parity_type != 3'b000) begin
                                tx_reg <= parity_reg;
                                state <= PARITY;
                            end else begin
                                tx_reg <= 1'b1;
                                state <= STOP0;
                            end
                        end else begin
                            bit_count <= bit_count + 1'b1;
                            tx_reg <= data_reg[bit_count + 1'b1];
                        end
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                PARITY: begin
                    if (last_sample) begin
                        sample_count <= 0;
                        tx_reg <= 1'b1;
                        state <= STOP0;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (last_sample) begin
                        sample_count <= 0;
                        if (stop_bits_count)
                            state <= STOP1;
                        else
                            state <= IDLE;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (last_sample) begin
                        sample_count <= 0;
                        state <= IDLE;
                    end else
                        sample_count <= sample_count + 1'b1;
                end

                default: begin
                    state <= IDLE;
                    tx_reg <= 1'b1;
                end
            endcase
        end
    end
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    parameter MDW = 9,
    parameter GFLEN = 8,
    parameter FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [0:0] rx,
    output wire [0:0] tx
);
    localparam RXDATA_REG_OFFSET=16'h0000;
    localparam TXDATA_REG_OFFSET=16'h0004;
    localparam PR_REG_OFFSET=16'h0008;
    localparam CTRL_REG_OFFSET=16'h000c;
    localparam CFG_REG_OFFSET=16'h0010;
    localparam MATCH_REG_OFFSET=16'h001c;
    localparam RX_FIFO_LEVEL_REG_OFFSET=16'hfe00;
    localparam RX_FIFO_THRESHOLD_REG_OFFSET=16'hfe04;
    localparam RX_FIFO_FLUSH_REG_OFFSET=16'hfe08;
    localparam TX_FIFO_LEVEL_REG_OFFSET=16'hfe10;
    localparam TX_FIFO_THRESHOLD_REG_OFFSET=16'hfe14;
    localparam TX_FIFO_FLUSH_REG_OFFSET=16'hfe18;
    localparam IM_REG_OFFSET=16'hff00;
    localparam MIS_REG_OFFSET=16'hff04;
    localparam RIS_REG_OFFSET=16'hff08;
    localparam IC_REG_OFFSET=16'hff0c;
    localparam GCLK_REG_OFFSET=16'hff10;

    reg GCLK_REG;
    wire clk_g;
    wire clk_gated_en = GCLK_REG;

    ef_util_gating_cell clk_gate_cell (
        .clk(PCLK),
        .rst_n(PRESETn),
        .clk_en(clk_gated_en),
        .clk_o(clk_g)
    );

    wire clk = clk_g;
    wire rst_n = PRESETn;
    wire apb_valid = PSEL & PENABLE;
    wire apb_we = PWRITE & apb_valid;
    wire apb_re = ~PWRITE & apb_valid;

    reg [15:0] PR_REG;
    reg [4:0] CTRL_REG;
    reg [13:0] CFG_REG;
    reg [MDW-1:0] MATCH_REG;
    reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
    reg RX_FIFO_FLUSH_REG;
    reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
    reg TX_FIFO_FLUSH_REG;
    reg [9:0] IM_REG, IC_REG, RIS_REG;

    wire [15:0] prescaler = PR_REG;
    wire en = CTRL_REG[0];
    wire tx_en = CTRL_REG[1];
    wire rx_en = CTRL_REG[2];
    wire loopback_en = CTRL_REG[3];
    wire glitch_filter_en = CTRL_REG[4];
    wire [3:0] data_size = CFG_REG[3:0];
    wire stop_bits_count = CFG_REG[4];
    wire [2:0] parity_type = CFG_REG[7:5];
    wire [5:0] timeout_bits = CFG_REG[13:8];
    wire [MDW-1:0] match_data = MATCH_REG;
    wire [FAW-1:0] txfifotr = TX_FIFO_THRESHOLD_REG;
    wire [FAW-1:0] rxfifotr = RX_FIFO_THRESHOLD_REG;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;
    wire rd, wr;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PR_REG <= 0;
        else if (apb_we && PADDR[15:0] == PR_REG_OFFSET)
            PR_REG <= PWDATA[15:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CTRL_REG <= 0;
        else if (apb_we && PADDR[15:0] == CTRL_REG_OFFSET)
            CTRL_REG <= PWDATA[4:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CFG_REG <= 14'h3f08;
        else if (apb_we && PADDR[15:0] == CFG_REG_OFFSET)
            CFG_REG <= PWDATA[13:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) MATCH_REG <= 0;
        else if (apb_we && PADDR[15:0] == MATCH_REG_OFFSET)
            MATCH_REG <= PWDATA[MDW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) RX_FIFO_THRESHOLD_REG <= 0;
        else if (apb_we && PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET)
            RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) RX_FIFO_FLUSH_REG <= 0;
        else if (apb_we && PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET)
            RX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            RX_FIFO_FLUSH_REG <= 0;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) TX_FIFO_THRESHOLD_REG <= 0;
        else if (apb_we && PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET)
            TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) TX_FIFO_FLUSH_REG <= 0;
        else if (apb_we && PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET)
            TX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            TX_FIFO_FLUSH_REG <= 0;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) GCLK_REG <= 0;
        else if (apb_we && PADDR[15:0] == GCLK_REG_OFFSET)
            GCLK_REG <= PWDATA[0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) IM_REG <= 0;
        else if (apb_we && PADDR[15:0] == IM_REG_OFFSET)
            IM_REG <= PWDATA[9:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) IC_REG <= 0;
        else if (apb_we && PADDR[15:0] == IC_REG_OFFSET)
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 0;

    wire [9:0] raw_status = {
        timeout_flag, overrun_flag, parity_error_flag, frame_error_flag,
        match_flag, break_flag, rx_level_above, tx_level_below,
        rx_full, tx_empty
    };

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn)
            RIS_REG <= 0;
        else
            RIS_REG <= (RIS_REG & ~IC_REG) | raw_status;

    wire [9:0] MIS_REG = RIS_REG & IM_REG;

    EF_UART #(
        .SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .prescaler(prescaler),
        .en(en),
        .tx_en(tx_en),
        .rx_en(rx_en),
        .rd(rd),
        .wr(wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .txfifotr(txfifotr),
        .rxfifotr(rxfifotr),
        .match_data(match_data),
        .timeout_bits(timeout_bits),
        .loopback_en(loopback_en),
        .glitch_filter_en(glitch_filter_en),
        .tx_fifo_flush(TX_FIFO_FLUSH_REG),
        .rx_fifo_flush(RX_FIFO_FLUSH_REG),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign rd = apb_re && (PADDR[15:0] == RXDATA_REG_OFFSET);
    assign wr = apb_we && (PADDR[15:0] == TXDATA_REG_OFFSET);

    assign PRDATA =
        (PADDR[15:0] == RXDATA_REG_OFFSET) ? rdata :
        (PADDR[15:0] == PR_REG_OFFSET) ? PR_REG :
        (PADDR[15:0] == CTRL_REG_OFFSET) ? CTRL_REG :
        (PADDR[15:0] == CFG_REG_OFFSET) ? CFG_REG :
        (PADDR[15:0] == MATCH_REG_OFFSET) ? MATCH_REG :
        (PADDR[15:0] == RX_FIFO_LEVEL_REG_OFFSET) ? rx_level :
        (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET) ? RX_FIFO_THRESHOLD_REG :
        (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET) ? RX_FIFO_FLUSH_REG :
        (PADDR[15:0] == TX_FIFO_LEVEL_REG_OFFSET) ? tx_level :
        (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET) ? TX_FIFO_THRESHOLD_REG :
        (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET) ? TX_FIFO_FLUSH_REG :
        (PADDR[15:0] == IM_REG_OFFSET) ? IM_REG :
        (PADDR[15:0] == MIS_REG_OFFSET) ? MIS_REG :
        (PADDR[15:0] == RIS_REG_OFFSET) ? RIS_REG :
        (PADDR[15:0] == GCLK_REG_OFFSET) ? GCLK_REG :
        32'hDEADBEEF;

    assign PREADY = 1'b1;
    assign IRQ = |MIS_REG;
endmodule

