module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk, input wire in, output wire out
);
    reg [NUM_STAGES-1:0] sync;
    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0],in};
    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
    reg [W-1:0] counter;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) counter <= '0;
        else if (en)
            counter <= (counter == '0) ? clk_div : counter - 1'b1;
    assign tick = en && ((clk_div == '0) || (counter == '0));
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;
    ef_util_ticker #(.W(8)) ticker (
        .clk(clk), .rst_n(rst_n), .en(en), .clk_div(CLKDIV), .tick(tick)
    );
    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            shifter <= '0;
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0],in};
            if (&{shifter[N-2:0],in}) out <= 1'b1;
            else if (!(|{shifter[N-2:0],in})) out <= 1'b0;
        end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 1 << AW;
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rp, wp, level_r;
    reg empty_r, full_r;
    wire write_ok = wr && !full_r;

    assign empty = empty_r;
    assign full = full_r;
    assign level = level_r;
    assign rdata = mem[rp];

    always @(posedge clk)
        if (write_ok)
            mem[wp] <= wdata;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rp <= '0;
            wp <= '0;
            level_r <= '0;
            empty_r <= 1'b1;
            full_r <= 1'b0;
        end else if (flush) begin
            rp <= '0;
            wp <= '0;
            level_r <= '0;
            empty_r <= 1'b1;
            full_r <= 1'b0;
        end else begin
            case ({write_ok,rd})
                2'b10: begin
                    wp <= wp + 1'b1;
                    level_r <= level_r + 1'b1;
                    empty_r <= 1'b0;
                    if ((wp + 1'b1) == rp) full_r <= 1'b1;
                end
                2'b01: begin
                    if (!empty_r) begin
                        rp <= rp + 1'b1;
                        level_r <= level_r - 1'b1;
                        full_r <= 1'b0;
                        if ((rp + 1'b1) == wp) empty_r <= 1'b1;
                    end
                end
                2'b11: begin
                    wp <= wp + 1'b1;
                    rp <= rp + 1'b1;
                end
                default: ;
            endcase
        end
    end
endmodule

