module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick, input wire [3:0] data_size,
    input wire stop_bits_count, input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done, output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire [MDW-1:0] parity_data =
        data_reg & ~({MDW{1'b1}} << data_size);

    assign tx = tx_reg;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            tx_done <= 1'b0;
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    if (tx_start) begin
                        state <= START;
                        sample_count <= 0;
                        bit_count <= 0;
                        data_reg <= d_in;
                    end
                end
                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            state <= DATA;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg <= data_reg >> 1;
                            if (bit_count == data_size-1) begin
                                state <= (parity_type == 3'b000) ? STOP0 : PARITY;
                            end else bit_count <= bit_count + 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                PARITY: begin
                    case (parity_type)
                        3'b001: tx_reg <= ~^parity_data;
                        3'b010: tx_reg <= ^parity_data;
                        3'b100: tx_reg <= 1'b0;
                        3'b101: tx_reg <= 1'b1;
                        default: tx_reg <= 1'b0;
                    endcase
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count) state <= STOP1;
                            else begin
                                state <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            tx_done <= 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size, input wire stop_bits_count,
    input wire [2:0] parity_type, input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done, output wire parity_error,
    output wire frame_error, output wire break_flag,
    output wire match_flag, output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_err_reg, frame_err_reg;
    reg [11:0] break_shift;

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = parity_err_reg && rx_done;
    assign frame_error = frame_err_reg && rx_done;
    assign match_flag = (dout == match_data) && rx_done;
    assign break_flag = (break_shift == 12'd0);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_err_reg <= 0;
            frame_err_reg <= 0;
            break_shift <= 12'hfff;
            rx_done <= 0;
        end else begin
            rx_done <= 1'b0;
