            case (state)
                IDLE: begin
                    parity_err_reg <= 0;
                    frame_err_reg <= 0;
                    if (b_tick && !rx) begin
                        state <= START;
                        sample_count <= 0;
                    end
                end
                START: begin
                    if (b_tick) begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                DATA: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg <= {rx,data_reg[MDW-1:1]};
                            if (bit_count == data_size-1)
                                state <= (parity_type == 3'b000) ? STOP0 : PARITY;
