                PARITY: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            case (parity_type)
                                3'b001: if ((~^dout) != rx) parity_err_reg <= 1'b1;
                                3'b010: if ((^dout) != rx) parity_err_reg <= 1'b1;
                                3'b100: if (rx != 1'b0) parity_err_reg <= 1'b1;
                                3'b101: if (rx != 1'b1) parity_err_reg <= 1'b1;
                                default: ;
                            endcase
                            state <= STOP0;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP0: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (!rx) frame_err_reg <= 1'b1;
                            if (stop_bits_count) state <= STOP1;
                            else begin
                                state <= IDLE;
                                rx_done <= 1'b1;
                            end
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                STOP1: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (!rx) frame_err_reg <= 1'b1;
                            state <= IDLE;
                            rx_done <= 1'b1;
                        end else sample_count <= sample_count + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
