module ef_util_sync #(parameter NUM_STAGES = 2) (
    input  wire clk,
    input  wire in,
    output wire out
);
    reg [NUM_STAGES-1:0] sync;

    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};

    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W = 8) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [W-1:0] clk_div,
    output wire         tick
);
    reg [W-1:0] counter;
    reg         tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter  <= 'b0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (clk_div == 'b0) ? 1'b1 : (counter == 'b0);
            if (counter == 'b0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input  wire clk,
    input  wire rst_n,
    input  wire in,
    input  wire en,
    output reg  out
);
    reg [N-1:0] shifter;
    wire tick;
    wire all_ones  = &shifter;
    wire all_zeros = ~|shifter;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            shifter <= 'b0;
        else if (tick)
            shifter <= {shifter[N-2:0], in};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            out <= 1'b0;
        else if (all_ones)
            out <= 1'b1;
        else if (all_zeros)
            out <= 1'b0;
    end
endmodule

module ef_util_fifo #(parameter DW = 8, AW = 4) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         rd,
    input  wire         wr,
    input  wire         flush,
    input  wire [DW-1:0] wdata,
    output wire         empty,
    output wire         full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;

    reg [DW-1:0] array_reg [0:DEPTH-1];
    reg [AW-1:0] w_ptr;
    reg [AW-1:0] r_ptr;
    reg [AW-1:0] level_reg;
    reg           full_reg;
    reg           empty_reg;

    wire write_accept = wr & ~full_reg;
    wire read_accept  = rd & ~empty_reg;

    assign rdata = array_reg[r_ptr];
    assign empty = empty_reg;
    assign full  = full_reg;
    assign level = level_reg;

    always @(posedge clk) begin
        if (write_accept)
            array_reg[w_ptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr      <= 'b0;
            r_ptr      <= 'b0;
            level_reg  <= 'b0;
            full_reg   <= 1'b0;
            empty_reg  <= 1'b1;
        end else if (flush) begin
            w_ptr      <= 'b0;
            r_ptr      <= 'b0;
            level_reg  <= 'b0;
            full_reg   <= 1'b0;
            empty_reg  <= 1'b1;
        end else begin
            case ({write_accept, read_accept})
                2'b10: begin
                    w_ptr     <= w_ptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((w_ptr + 1'b1) == r_ptr)
                        full_reg <= 1'b1;
                end

                2'b01: begin
                    r_ptr     <= r_ptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg  <= 1'b0;
                    if ((r_ptr + 1'b1) == w_ptr)
                        empty_reg <= 1'b1;
                end

                2'b11: begin
                    w_ptr <= w_ptr + 1'b1;
                    r_ptr <= r_ptr + 1'b1;
                end

                default: begin
                end
            endcase
        end
    end
endmodule

