    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 :
                         count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    wire [MDW-1:0] received_data =
        data_reg >> (9 - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state            <= idle_st;
            sample_count     <= 16'd0;
            bit_count        <= 4'd0;
            data_reg         <= 'b0;
            parity_error_reg <= 1'b0;
            frame_error_reg  <= 1'b0;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;

            if (state == idle_st) begin
                parity_error_reg <= 1'b0;
                frame_error_reg  <= 1'b0;
            end else begin
                if (next_parity_error)
                    parity_error_reg <= 1'b1;
                if (next_frame_error)
                    frame_error_reg <= 1'b1;
            end
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_parity_error = 1'b0;
        next_frame_error  = 1'b0;
        rx_done           = 1'b0;

        case (state)
            idle_st: begin
                if (b_tick && !rx) begin
                    next_state        = start_st;
                    next_sample_count = 16'd0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state        = data_st;
                        next_sample_count = 16'd0;
                        next_bit_count    = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg =
                            {rx, data_reg[MDW-1:1]};

                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = stop0_st;

                        case (parity_type)
                            3'b001: if ((~^received_data) != rx)
                                next_parity_error = 1'b1;
                            3'b010: if (( ^received_data) != rx)
                                next_parity_error = 1'b1;
                            3'b100: if (rx != 1'b0)
                                next_parity_error = 1'b1;
                            3'b101: if (rx != 1'b1)
                                next_parity_error = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        if (!rx)
                            next_frame_error = 1'b1;

                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            break_shift <= 12'hfff;
        else if (b_tick && sample_count == NUM_SAMPLES-1) begin
            if (state == idle_st)
                break_shift <= 12'hfff;
            else
                break_shift <= {break_shift[10:0], rx};
        end
    end

    assign dout         = received_data;
    assign parity_error = parity_error_reg && rx_done;
    assign frame_error  = frame_error_reg && rx_done;
    assign match_flag   = (received_data == match_data) && rx_done;
    assign break_flag   = (break_shift == 12'd0);
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx;

    wire [MDW-1:0] parity_data =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= idle_st;
            sample_count <= 16'd0;
            bit_count    <= 4'd0;
            data_reg     <= 'b0;
            tx_reg       <= 1'b1;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;
            tx_reg       <= next_tx;
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_tx           = tx_reg;
        tx_done           = 1'b0;

        case (state)
            idle_st: begin
                next_tx = 1'b1;
                if (tx_start) begin
                    next_state        = start_st;
                    next_sample_count = 16'd0;
                    next_data_reg     = d_in;
                end
            end

            start_st: begin
                next_tx = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state        = data_st;
                        next_sample_count = 16'd0;
                        next_bit_count    = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                next_tx = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg     = data_reg >> 1;

                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx = ~^parity_data;
                    3'b010: next_tx =  ^parity_data;
                    3'b100: next_tx = 1'b0;
                    3'b101: next_tx = 1'b1;
                    default: next_tx = 1'b0;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = stop0_st;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

