module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    wire [MDW-1:0] received_data =
        data_reg >> (9 - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state            <= idle_st;
            sample_count     <= 16'd0;
            bit_count        <= 4'd0;
            data_reg         <= 'b0;
            parity_error_reg <= 1'b0;
            frame_error_reg  <= 1'b0;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;

            if (state == idle_st) begin
                parity_error_reg <= 1'b0;
                frame_error_reg  <= 1'b0;
            end else begin
                if (next_parity_error)
                    parity_error_reg <= 1'b1;
                if (next_frame_error)
                    frame_error_reg <= 1'b1;
            end
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_parity_error = 1'b0;
        next_frame_error  = 1'b0;
        rx_done           = 1'b0;

        case (state)
            idle_st: begin
                if (b_tick && !rx) begin
                    next_state        = start_st;
                    next_sample_count = 16'd0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state        = data_st;
                        next_sample_count = 16'd0;
                        next_bit_count    = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg =
                            {rx, data_reg[MDW-1:1]};

                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = stop0_st;

                        case (parity_type)
                            3'b001: if ((~^received_data) != rx)
                                next_parity_error = 1'b1;
                            3'b010: if (( ^received_data) != rx)
                                next_parity_error = 1'b1;
                            3'b100: if (rx != 1'b0)
                                next_parity_error = 1'b1;
                            3'b101: if (rx != 1'b1)
                                next_parity_error = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        if (!rx)
                            next_frame_error = 1'b1;

                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            break_shift <= 12'hfff;
        else if (b_tick && sample_count == NUM_SAMPLES-1) begin
            if (state == idle_st)
                break_shift <= 12'hfff;
            else
                break_shift <= {break_shift[10:0], rx};
        end
    end

    assign dout         = received_data;
    assign parity_error = parity_error_reg && rx_done;
    assign frame_error  = frame_error_reg && rx_done;
    assign match_flag   = (received_data == match_data) && rx_done;
    assign break_flag   = (break_shift == 12'd0);
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx;

    wire [MDW-1:0] parity_data =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= idle_st;
            sample_count <= 16'd0;
            bit_count    <= 4'd0;
            data_reg     <= 'b0;
            tx_reg       <= 1'b1;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;
            tx_reg       <= next_tx;
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_tx           = tx_reg;
        tx_done           = 1'b0;

        case (state)
            idle_st: begin
                next_tx = 1'b1;
                if (tx_start) begin
                    next_state        = start_st;
                    next_sample_count = 16'd0;
                    next_data_reg     = d_in;
                end
            end

            start_st: begin
                next_tx = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state        = data_st;
                        next_sample_count = 16'd0;
                        next_bit_count    = 4'd0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                next_tx = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_data_reg     = data_reg >> 1;

                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx = ~^parity_data;
                    3'b010: next_tx =  ^parity_data;
                    3'b100: next_tx = 1'b0;
                    3'b101: next_tx = 1'b1;
                    default: next_tx = 1'b0;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = stop0_st;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 16'd0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_OFFSET       = 16'h0000;
    localparam TXDATA_OFFSET       = 16'h0004;
    localparam PR_OFFSET           = 16'h0008;
    localparam CTRL_OFFSET         = 16'h000c;
    localparam CFG_OFFSET          = 16'h0010;
    localparam MATCH_OFFSET        = 16'h001c;
    localparam RX_LEVEL_OFFSET     = 16'hfe00;
    localparam RX_THRESHOLD_OFFSET = 16'hfe04;
    localparam RX_FLUSH_OFFSET     = 16'hfe08;
    localparam TX_LEVEL_OFFSET     = 16'hfe10;
    localparam TX_THRESHOLD_OFFSET = 16'hfe14;
    localparam TX_FLUSH_OFFSET     = 16'hfe18;
    localparam IM_OFFSET           = 16'hff00;
    localparam MIS_OFFSET          = 16'hff04;
    localparam RIS_OFFSET          = 16'hff08;
    localparam IC_OFFSET           = 16'hff0c;
    localparam GCLK_OFFSET         = 16'hff10;

    wire apb_we = PSEL && PENABLE && PWRITE;
    wire apb_re = PSEL && PENABLE && !PWRITE;
    wire clk = PCLK;

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg;
    reg [FAW-1:0] tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg gclk_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire tx_write = apb_we && (PADDR[15:0] == TXDATA_OFFSET);
    wire rx_read  = apb_re && (PADDR[15:0] == RXDATA_OFFSET);

    wire [9:0] raw_status = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            pr_reg <= 16'd0;
        else if (apb_we && PADDR[15:0] == PR_OFFSET)
            pr_reg <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ctrl_reg <= 5'd0;
        else if (apb_we && PADDR[15:0] == CTRL_OFFSET)
            ctrl_reg <= PWDATA[4:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            cfg_reg <= 14'h3f08;
        else if (apb_we && PADDR[15:0] == CFG_OFFSET)
            cfg_reg <= PWDATA[13:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            match_reg <= 'b0;
        else if (apb_we && PADDR[15:0] == MATCH_OFFSET)
            match_reg <= PWDATA[MDW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            rx_threshold_reg <= 'b0;
        else if (apb_we && PADDR[15:0] == RX_THRESHOLD_OFFSET)
            rx_threshold_reg <= PWDATA[FAW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            tx_threshold_reg <= 'b0;
        else if (apb_we && PADDR[15:0] == TX_THRESHOLD_OFFSET)
            tx_threshold_reg <= PWDATA[FAW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            rx_flush_reg <= 1'b0;
        else if (apb_we && PADDR[15:0] == RX_FLUSH_OFFSET)
            rx_flush_reg <= PWDATA[0];
        else
            rx_flush_reg <= 1'b0;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            tx_flush_reg <= 1'b0;
        else if (apb_we && PADDR[15:0] == TX_FLUSH_OFFSET)
            tx_flush_reg <= PWDATA[0];
        else
            tx_flush_reg <= 1'b0;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            gclk_reg <= 1'b0;
        else if (apb_we && PADDR[15:0] == GCLK_OFFSET)
            gclk_reg <= PWDATA[0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            im_reg <= 10'b0;
        else if (apb_we && PADDR[15:0] == IM_OFFSET)
            im_reg <= PWDATA[9:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ic_reg <= 10'b0;
        else if (apb_we && PADDR[15:0] == IC_OFFSET)
            ic_reg <= PWDATA[9:0];
        else
            ic_reg <= 10'b0;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | raw_status;
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) uart_core (
        .clk(clk),
        .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]),
        .rx_en(ctrl_reg[2]),
        .rd(rx_read),
        .wr(tx_write),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_threshold_reg),
        .rxfifotr(rx_threshold_reg),
        .match_data(match_reg),
        .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (PADDR[15:0] == RXDATA_OFFSET)       ? {{(32-MDW){1'b0}}, rdata} :
        (PADDR[15:0] == PR_OFFSET)           ? {{16{1'b0}}, pr_reg} :
        (PADDR[15:0] == CTRL_OFFSET)         ? {{27{1'b0}}, ctrl_reg} :
        (PADDR[15:0] == CFG_OFFSET)          ? {{18{1'b0}}, cfg_reg} :
        (PADDR[15:0] == MATCH_OFFSET)        ? {{(32-MDW){1'b0}}, match_reg} :
        (PADDR[15:0] == RX_LEVEL_OFFSET)     ? {{(32-FAW){1'b0}}, rx_level} :
        (PADDR[15:0] == RX_THRESHOLD_OFFSET) ? {{(32-FAW){1'b0}}, rx_threshold_reg} :
        (PADDR[15:0] == RX_FLUSH_OFFSET)     ? {{31{1'b0}}, rx_flush_reg} :
        (PADDR[15:0] == TX_LEVEL_OFFSET)     ? {{(32-FAW){1'b0}}, tx_level} :
        (PADDR[15:0] == TX_THRESHOLD_OFFSET) ? {{(32-FAW){1'b0}}, tx_threshold_reg} :
        (PADDR[15:0] == TX_FLUSH_OFFSET)     ? {{31{1'b0}}, tx_flush_reg} :
        (PADDR[15:0] == IM_OFFSET)           ? {{22{1'b0}}, im_reg} :
        (PADDR[15:0] == MIS_OFFSET)          ? {{22{1'b0}}, (ris_reg & im_reg)} :
        (PADDR[15:0] == RIS_OFFSET)          ? {{22{1'b0}}, ris_reg} :
        (PADDR[15:0] == GCLK_OFFSET)         ? {{31{1'b0}}, gclk_reg} :
        32'hdeadbeef;

    assign PREADY = 1'b1;
    assign IRQ = |(ris_reg & im_reg);
endmodule

