        .VPB(vgnd),
`endif
        .GCLK(clk_o),
        .GATE(clk_en),
        .CLK(clk)
    );
`elsif CLKG_GENERIC
    assign clk_o = clk & clk_en;
`else
    assign clk_o = clk;
`endif
endmodule

module EF_UART #(
    parameter MDW=9,
    parameter FAW=4,
    parameter SC=8,
    parameter GFLEN=8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire b_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_synched, rx_filtered, rx_in;

    ef_util_sync rx_sync (
        .clk(clk),
        .in(rx),
        .out(rx_synched)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_synched),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_synched;

    BAUDGEN baud_gen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_tx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_tx (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(~tx_empty),
        .b_tick(b_tick & tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_rx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_rx (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(b_tick & rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .match_data(match_data),
        .rx(rx_in),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .rx_done(rx_done),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count <= 6'd0;
            samples_count <= 5'd0;
        end else if (b_tick) begin
            if (rx_done) begin
                bits_count <= 6'd0;
                samples_count <= 5'd0;
            end else if (samples_count == SC-1) begin
                samples_count <= 5'd0;
                if (timeout_flag)
                    bits_count <= 6'd0;
                else
                    bits_count <= bits_count + 1'b1;
            end else begin
                samples_count <= samples_count + 1'b1;
            end
        end
    end

    assign tx_level_below = (tx_level < txfifotr) & ~tx_full;
    assign rx_level_above = (rx_level > rxfifotr) | rx_full;
    assign overrun_flag = rx_full & rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 :
                         count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st=3'd0, start_st=3'd1, data_st=3'd2,
               parity_st=3'd3, stop0_st=3'd4, stop1_st=3'd5;

    reg [2:0] current_state, next_state;
    reg [4:0] b_reg, b_next;
    reg [3:0] count_reg, count_next;
    reg [MDW-1:0] data_reg, data_next;
    reg p_error_reg, p_error_next;
    reg f_error_reg, f_error_next;
    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            if (current_state == idle_st)
                p_error_reg <= 1'b0;
            else if (p_error_next)
                p_error_reg <= 1'b1;
            if (current_state == idle_st)
                f_error_reg <= 1'b0;
            else if (f_error_next)
                f_error_reg <= 1'b1;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        p_error_next = 1'b0;
        f_error_next = 1'b0;
        rx_done = 1'b0;

        case (current_state)
            idle_st: begin
                if (!rx && b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (b_reg == (NUM_SAMPLES/2-1)) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if (count_reg == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if ((~^dout) != rx) p_error_next = 1'b1;
                            3'b010: if ((^dout) != rx) p_error_next = 1'b1;
                            3'b100: if (rx != 1'b0) p_error_next = 1'b1;
                            3'b101: if (rx != 1'b1) p_error_next = 1'b1;
                            default: p_error_next = 1'b0;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (!rx)
                            f_error_next = 1'b1;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            f_error_next = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && b_reg == NUM_SAMPLES-1) begin
            if (current_state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 12'd0);
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st=3'd0, start_st=3'd1, data_st=3'd2,
               parity_st=3'd3, stop0_st=3'd4, stop1_st=3'd5;

    reg [2:0] current_state, next_state;
    reg [4:0] b_reg, b_next;
    reg [3:0] count_reg, count_next;
    reg [MDW-1:0] data_reg, data_next;
    reg tx_reg, tx_next;

    wire [MDW-1:0] pdata =
        d_in & ({MDW{1'b1}} >> (MDW-data_size));

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            tx_reg <= tx_next;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        tx_next = tx_reg;
        tx_done = 1'b0;

        case (current_state)
            idle_st: begin
                tx_next = 1'b1;
                if (tx_start) begin
                    next_state = start_st;
                    b_next = 0;
                    data_next = d_in;
                end
            end

            start_st: begin
                tx_next = 1'b0;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            data_st: begin
                tx_next = data_reg[0];
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if (count_reg == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 1'b0;
                    3'b101: tx_next = 1'b1;
                    default: tx_next = 1'b0;
                endcase

                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop0_st: begin
                tx_next = 1'b1;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            stop1_st: begin
                tx_next = 1'b1;
                if (b_tick) begin
                    if (b_reg == NUM_SAMPLES-1) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC=8,
    MDW=9,
    GFLEN=8,
    FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_OFF=16'h0000;
    localparam TXDATA_OFF=16'h0004;
    localparam PR_OFF=16'h0008;
    localparam CTRL_OFF=16'h000c;
    localparam CFG_OFF=16'h0010;
    localparam MATCH_OFF=16'h001c;
    localparam RX_LEVEL_OFF=16'hfe00;
    localparam RX_THRESH_OFF=16'hfe04;
    localparam RX_FLUSH_OFF=16'hfe08;
    localparam TX_LEVEL_OFF=16'hfe10;
    localparam TX_THRESH_OFF=16'hfe14;
    localparam TX_FLUSH_OFF=16'hfe18;
    localparam IM_OFF=16'hff00;
    localparam MIS_OFF=16'hff04;
    localparam RIS_OFF=16'hff08;
    localparam IC_OFF=16'hff0c;
    localparam GCLK_OFF=16'hff10;

    reg gclk_reg;
    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_thresh_reg, tx_thresh_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    wire clk_g;
    wire apb_valid = PSEL & PENABLE;
    wire apb_we = apb_valid & PWRITE;
    wire apb_re = apb_valid & ~PWRITE;
    wire [15:0] addr = PADDR[15:0];

    ef_util_gating_cell clk_gate (
        .clk(PCLK),
        .rst_n(PRESETn),
        .clk_en(gclk_reg),
        .clk_o(clk_g)
    );

    wire [15:0] prescaler = pr_reg;
    wire en = ctrl_reg[0];
    wire tx_en = ctrl_reg[1];
    wire rx_en = ctrl_reg[2];
    wire loopback_en = ctrl_reg[3];
    wire glitch_filter_en = ctrl_reg[4];
    wire [3:0] data_size = cfg_reg[3:0];
    wire stop_bits_count = cfg_reg[4];
    wire [2:0] parity_type = cfg_reg[7:5];
    wire [5:0] timeout_bits = cfg_reg[13:8];
    wire [MDW-1:0] match_data = match_reg;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag, parity_error_flag;
    wire overrun_flag, timeout_flag;

    wire rd = apb_re && (addr == RXDATA_OFF);
    wire wr = apb_we && (addr == TXDATA_OFF);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            gclk_reg <= 1'b0;
            pr_reg <= 16'd0;
            ctrl_reg <= 5'd0;
            cfg_reg <= 14'h3f08;
            match_reg <= 'd0;
            rx_thresh_reg <= 'd0;
            tx_thresh_reg <= 'd0;
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            im_reg <= 10'd0;
            ic_reg <= 10'd0;
        end else begin
            if (apb_we && addr == GCLK_OFF) gclk_reg <= PWDATA[0];
            if (apb_we && addr == PR_OFF) pr_reg <= PWDATA[15:0];
            if (apb_we && addr == CTRL_OFF) ctrl_reg <= PWDATA[4:0];
            if (apb_we && addr == CFG_OFF) cfg_reg <= PWDATA[13:0];
            if (apb_we && addr == MATCH_OFF) match_reg <= PWDATA[MDW-1:0];
            if (apb_we && addr == RX_THRESH_OFF) rx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && addr == TX_THRESH_OFF) tx_thresh_reg <= PWDATA[FAW-1:0];

            if (apb_we && addr == RX_FLUSH_OFF)
                rx_flush_reg <= PWDATA[0];
            else
                rx_flush_reg <= 1'b0;

            if (apb_we && addr == TX_FLUSH_OFF)
                tx_flush_reg <= PWDATA[0];
            else
                tx_flush_reg <= 1'b0;

            if (apb_we && addr == IM_OFF)
                im_reg <= PWDATA[9:0];

            if (apb_we && addr == IC_OFF)
                ic_reg <= PWDATA[9:0];
            else
                ic_reg <= 10'd0;
        end
    end

    wire [9:0] raw_status = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'd0;
        else begin
            for (i=0; i<10; i=i+1) begin
                if (ic_reg[i])
                    ris_reg[i] <= 1'b0;
                else if (raw_status[i])
                    ris_reg[i] <= 1'b1;
            end
        end
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) uart (
        .clk(clk_g),
        .rst_n(PRESETn),
        .prescaler(prescaler),
        .en(en),
        .tx_en(tx_en),
        .rx_en(rx_en),
        .rd(rd),
        .wr(wr),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .txfifotr(tx_thresh_reg),
        .rxfifotr(rx_thresh_reg),
        .match_data(match_data),
        .timeout_bits(timeout_bits),
        .loopback_en(loopback_en),
        .glitch_filter_en(glitch_filter_en),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA_OFF)     ? rdata :
        (addr == PR_OFF)         ? pr_reg :
        (addr == CTRL_OFF)       ? ctrl_reg :
        (addr == CFG_OFF)        ? cfg_reg :
        (addr == MATCH_OFF)      ? match_reg :
        (addr == RX_LEVEL_OFF)   ? rx_level :
        (addr == RX_THRESH_OFF)  ? rx_thresh_reg :
        (addr == RX_FLUSH_OFF)   ? rx_flush_reg :
        (addr == TX_LEVEL_OFF)   ? tx_level :
        (addr == TX_THRESH_OFF)  ? tx_thresh_reg :
        (addr == TX_FLUSH_OFF)   ? tx_flush_reg :
        (addr == IM_OFF)         ? im_reg :
        (addr == MIS_OFF)        ? (ris_reg & im_reg) :
        (addr == RIS_OFF)        ? ris_reg :
        (addr == GCLK_OFF)       ? gclk_reg :
        32'hdeadbeef;

    assign IRQ = |(ris_reg & im_reg);
    assign PREADY = 1'b1;
endmodule

