    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_reg <= 1'b0;
        else if (pwm0_en && tick) begin
            if (pwm_fault)
                pwm0_reg <= 1'b0;
            else
                pwm0_reg <= pwm0_reg_next;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_reg <= 1'b0;
        else if (pwm1_en && tick) begin
            if (pwm_fault)
                pwm1_reg <= 1'b0;
            else
