module ef_util_ticker #(parameter W=8)(
 input wire clk,input wire rst_n,input wire en,input wire [W-1:0] clk_div,
 output wire tick);
 reg [W-1:0] counter;
 reg tick_reg;
 wire zero=(counter=='b0);
 always @(posedge clk or negedge rst_n)
   if(!rst_n) counter<='b0;
   else if(en) counter<=zero?clk_div:counter-1'b1;
 always @(posedge clk or negedge rst_n)
   if(!rst_n) tick_reg<=1'b0;
   else tick_reg<=en && ((clk_div=='b0)?1'b1:zero);
 assign tick=tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8,CLKDIV=8'd1)(
 input wire clk,input wire rst_n,input wire in,input wire en,output reg out);
 reg [N-1:0] shifter;
 wire tick;
 ef_util_ticker #(.W(8)) ticker(.clk(clk),.rst_n(rst_n),.en(en),
   .clk_div(CLKDIV),.tick(tick));
 always @(posedge clk or negedge rst_n)
   if(!rst_n) shifter<='b0;
   else if(tick) shifter<={shifter[N-2:0],in};
 always @(posedge clk or negedge rst_n)
   if(!rst_n) out<=1'b0;
   else if(&shifter) out<=1'b1;
   else if(~|shifter) out<=1'b0;
endmodule

module ef_util_fifo #(parameter DW=8,AW=4)(
 input wire clk,input wire rst_n,input wire rd,input wire wr,input wire flush,
 input wire [DW-1:0] wdata,output wire empty,output wire full,
 output wire [DW-1:0] rdata,output wire [AW-1:0] level);
 localparam DEPTH=2**AW;
 reg [DW-1:0] mem[0:DEPTH-1];
 reg [AW-1:0] wp,rp,lev;
 reg f,e;
 wire wen=wr & ~f;
 assign rdata=mem[rp];
 assign empty=e;
 assign full=f;
 assign level=lev;
 always @(posedge clk)
   if(wen) mem[wp]<=wdata;
 always @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin wp<=0;rp<=0;lev<=0;f<=0;e<=1; end
   else if(flush) begin wp<=0;rp<=0;lev<=0;f<=0;e<=1; end
   else case({wen,rd})
     2'b01: if(!e) begin
       rp<=rp+1'b1; lev<=lev-1'b1; f<=0;
       if(rp+1'b1==wp) e<=1;
     end
     2'b10: begin
       wp<=wp+1'b1; lev<=lev+1'b1; e<=0;
       if(wp+1'b1==rp) f<=1;
     end
     2'b11: begin wp<=wp+1'b1; rp<=rp+1'b1; end
   endcase
 end
endmodule

