  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn)
      RIS_REG <= 3'b0;
    else begin
      if (IC_REG[0])
        RIS_REG[0] <= 1'b0;
      else if (timeout_flag)
        RIS_REG[0] <= 1'b1;

      if (IC_REG[1])
        RIS_REG[1] <= 1'b0;
      else if (matchx_flag)
        RIS_REG[1] <= 1'b1;

      if (IC_REG[2])
        RIS_REG[2] <= 1'b0;
      else if (matchy_flag)
        RIS_REG[2] <= 1'b1;
    end

  assign IRQ = |MIS_REG;

  EF_TMR32 #(
      .PRW(PRW)
  ) instance_to_wrap (
      .clk(clk),
      .rst_n(rst_n),
      .tmr_en(tmr_en),
      .tmr_start(tmr_start),
      .pwm0_en(pwm0_en),
      .pwm1_en(pwm1_en),
      .tmr_reload(tmr_reload),
      .cmpx(cmpx),
      .cmpy(cmpy),
      .prescaler(prescaler),
      .tmr_cfg(tmr_cfg),
      .pwm0_cfg(pwm0_cfg),
      .pwm1_cfg(pwm1_cfg),
      .pwm0_inv(pwm0_inv),
      .pwm1_inv(pwm1_inv),
      .pwm_dt(pwm_dt),
      .pwm_fault_clr(pwm_fault_clr),
      .pwm_dt_en(pwm_dt_en),
      .tmr(tmr),
      .matchx_flag(matchx_flag),
      .matchy_flag(matchy_flag),
      .timeout_flag(timeout_flag),
      .pwm0(pwm0),
      .pwm1(pwm1),
      .pwm_fault(pwm_fault)
  );

  assign PRDATA =
      (PADDR[15:0] == TMR_REG_OFFSET)     ? TMR_WIRE :
      (PADDR[15:0] == RELOAD_REG_OFFSET)  ? RELOAD_REG :
      (PADDR[15:0] == PR_REG_OFFSET)      ? {{(32-PRW){1'b0}}, PR_REG} :
