module EF_TMR32 #(
    parameter PRW = 16,
    parameter PWM_FAULT_CLR_C0 = 16'hA539,
    parameter PWM_FAULT_CLR_C1 = 16'hA953
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            tmr_en,
    input  wire            tmr_start,
    input  wire            pwm0_en,
    input  wire            pwm1_en,
    input  wire [31:0]     tmr_reload,
    input  wire [31:0]     cmpx,
    input  wire [31:0]     cmpy,
    input  wire [PRW-1:0]  prescaler,
    input  wire [2:0]      tmr_cfg,
    input  wire [11:0]     pwm0_cfg,
    input  wire [11:0]     pwm1_cfg,
    input  wire            pwm0_inv,
    input  wire            pwm1_inv,
    input  wire [7:0]      pwm_dt,
    input  wire [15:0]     pwm_fault_clr,
    input  wire            pwm_dt_en,
    output wire [31:0]     tmr,
    output wire            matchx_flag,
    output wire            matchy_flag,
    output wire            timeout_flag,
    input  wire            pwm_fault,
    output wire            pwm0,
    output wire            pwm1
);

    wire [1:0] tmr_mode = tmr_cfg[1:0];
    wire       tmr_periodic = tmr_cfg[2];

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg tmr_run;
    reg tmr_dir;
    reg fault_reg;
    reg fault_armed;

    wire start_pulse;
    wire tick = (pr_reg == {PRW{1'b0}});

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}}, 1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
    end

    wire tmr_eq_reload = (tmr_reg == tmr_reload);
    wire tmr_eq_zero   = (tmr_reg == 32'd0);
    wire tmr_eq_reload_m_1 = (tmr_reg == (tmr_reload - 1'b1));
    wire tmr_eq_one    = (tmr_reg == 32'd1);
    wire tmr_eq_cmpx   = (tmr_reg == cmpx);
    wire tmr_eq_cmpy   = (tmr_reg == cmpy);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_run <= 1'b0;
        else if (start_pulse)
            tmr_run <= 1'b1;
        else if (tick && !tmr_periodic &&
                 tmr_cfg[0] &&
                 tmr_eq_one &&
                 !tmr_dir)
            tmr_run <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_reg <= 32'd0;
        else if (tmr_en) begin
            if (start_pulse) begin
                if (tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else
                    tmr_reg <= 32'd0;
            end
            else if (tick && tmr_run) begin
                if (tmr_mode == 2'b11) begin
                    if (tmr_dir)
                        tmr_reg <= tmr_reg + 1'b1;
                    else
                        tmr_reg <= tmr_reg - 1'b1;
                end
                else if (tmr_mode == 2'b01) begin
                    if (tmr_eq_zero)
                        tmr_reg <= tmr_periodic ? tmr_reload : tmr_reg;
                    else
                        tmr_reg <= tmr_reg - 1'b1;
                end
                else if (tmr_mode == 2'b10) begin
                    if (tmr_eq_reload)
                        tmr_reg <= tmr_periodic ? 32'd0 : tmr_reg;
                    else
                        tmr_reg <= tmr_reg + 1'b1;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_dir <= 1'b1;
        else if (start_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end
        else if (tick) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_dir && tmr_eq_reload_m_1)
                    tmr_dir <= 1'b0;
                else if (!tmr_dir && tmr_eq_one)
                    tmr_dir <= 1'b1;
            end
            else if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end
    end

    function [0:0] pwm_action;
        input [1:0] action;
        input       current;
        begin
            case (action)
                2'b00: pwm_action = current;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                default: pwm_action = ~current;
            endcase
        end
    endfunction

    reg pwm0_reg;
    reg pwm1_reg;
    reg pwm0_next;
    reg pwm1_next;

    always @* begin
        casez ({tmr_dir, tmr_eq_zero, tmr_eq_cmpx,
               tmr_eq_cmpy, tmr_eq_reload})
            5'b?_1_00_0: pwm0_next = pwm_action(pwm0_cfg[1:0],   pwm0_reg);
            5'b1_0_10_0: pwm0_next = pwm_action(pwm0_cfg[3:2],   pwm0_reg);
            5'b1_0_01_0: pwm0_next = pwm_action(pwm0_cfg[5:4],   pwm0_reg);
            5'b?_0_00_1: pwm0_next = pwm_action(pwm0_cfg[7:6],   pwm0_reg);
            5'b0_0_01_0: pwm0_next = pwm_action(pwm0_cfg[9:8],   pwm0_reg);
            5'b0_0_10_0: pwm0_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
            default:     pwm0_next = pwm0_reg;
        endcase
    end

    always @* begin
        casez ({tmr_dir, tmr_eq_zero, tmr_eq_cmpx,
               tmr_eq_cmpy, tmr_eq_reload})
            5'b?_1_00_0: pwm1_next = pwm_action(pwm1_cfg[1:0],   pwm1_reg);
            5'b1_0_10_0: pwm1_next = pwm_action(pwm1_cfg[3:2],   pwm1_reg);
            5'b1_0_01_0: pwm1_next = pwm_action(pwm1_cfg[5:4],   pwm1_reg);
            5'b?_0_00_1: pwm1_next = pwm_action(pwm1_cfg[7:6],   pwm1_reg);
            5'b0_0_01_0: pwm1_next = pwm_action(pwm1_cfg[9:8],   pwm1_reg);
            5'b0_0_10_0: pwm1_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
            default:     pwm1_next = pwm1_reg;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_reg <= 1'b0;
        else if (pwm0_en && tick)
            pwm0_reg <= pwm_fault ? 1'b0 : pwm0_next;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_reg <= 1'b0;
        else if (pwm1_en && tick)
            pwm1_reg <= pwm_fault ? 1'b0 : pwm1_next;
    end

    reg [7:0] dly_cntr;
    reg pwm0_delayed;
    reg pwm0_out_reg;
    reg pwm1_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dly_cntr <= 8'd0;
        else if (tick) begin
            if (dly_cntr == 8'd0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_delayed <= 1'b0;
        else if (tick && (dly_cntr == 8'd0))
            pwm0_delayed <= pwm0_reg;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_out_reg <= 1'b0;
            pwm1_out_reg <= 1'b0;
        end
        else begin
            if (pwm_dt_en) begin
                pwm0_out_reg <= pwm0_delayed & pwm0_reg;
                pwm1_out_reg <= ~pwm0_delayed & ~pwm0_reg;
            end
            else begin
                pwm0_out_reg <= pwm0_reg;
                pwm1_out_reg <= pwm1_reg;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_armed <= 1'b0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_armed <= 1'b1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_armed <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 1'b0;
        else if (pwm_fault)
            fault_reg <= 1'b1;
        else if (fault_armed &&
                 (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 1'b0;
    end

    assign tmr = tmr_reg;
    assign matchx_flag = tmr_eq_cmpx;
    assign matchy_flag = tmr_eq_cmpy;
    assign timeout_flag = tmr_dir ? tmr_eq_reload : tmr_eq_zero;

    assign pwm0 = (pwm0_out_reg ^ pwm0_inv) & ~fault_reg & pwm0_en;
    assign pwm1 = (pwm1_out_reg ^ pwm1_inv) & ~fault_reg & pwm1_en;

endmodule

