module EF_TMR32 #(
    parameter PRW = 16,
    parameter PWM_FAULT_CLR_C0 = 16'hA539,
    parameter PWM_FAULT_CLR_C1 = 16'hA953
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            tmr_en,
    input  wire            tmr_start,
    input  wire            pwm0_en,
    input  wire            pwm1_en,
    input  wire [31:0]     tmr_reload,
    input  wire [31:0]     cmpx,
    input  wire [31:0]     cmpy,
    input  wire [PRW-1:0]  prescaler,
    input  wire [2:0]      tmr_cfg,
    input  wire [11:0]     pwm0_cfg,
    input  wire [11:0]     pwm1_cfg,
    input  wire            pwm0_inv,
    input  wire            pwm1_inv,
    input  wire [7:0]      pwm_dt,
    input  wire [15:0]     pwm_fault_clr,
    input  wire            pwm_dt_en,
    output wire [31:0]     tmr,
    output wire            matchx_flag,
    output wire            matchy_flag,
    output wire            timeout_flag,
    input  wire            pwm_fault,
    output wire            pwm0,
    output wire            pwm1
);

    wire [1:0] tmr_mode = tmr_cfg[1:0];
    wire       tmr_periodic = tmr_cfg[2];

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg tmr_run;
    reg tmr_dir;
    reg fault_reg;
    reg fault_armed;

    wire start_pulse;
    wire tick = (pr_reg == {PRW{1'b0}});

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}}, 1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
    end

    wire tmr_eq_reload = (tmr_reg == tmr_reload);
    wire tmr_eq_zero   = (tmr_reg == 32'd0);
    wire tmr_eq_reload_m_1 = (tmr_reg == (tmr_reload - 1'b1));
    wire tmr_eq_one    = (tmr_reg == 32'd1);
    wire tmr_eq_cmpx   = (tmr_reg == cmpx);
    wire tmr_eq_cmpy   = (tmr_reg == cmpy);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_run <= 1'b0;
        else if (start_pulse)
            tmr_run <= 1'b1;
        else if (tick && !tmr_periodic &&
                 tmr_cfg[0] &&
                 tmr_eq_one &&
                 !tmr_dir)
            tmr_run <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_reg <= 32'd0;
        else if (tmr_en) begin
            if (start_pulse) begin
                if (tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else
                    tmr_reg <= 32'd0;
            end
            else if (tick && tmr_run) begin
                if (tmr_mode == 2'b11) begin
                    if (tmr_dir)
                        tmr_reg <= tmr_reg + 1'b1;
                    else
                        tmr_reg <= tmr_reg - 1'b1;
                end
                else if (tmr_mode == 2'b01) begin
                    if (tmr_eq_zero)
                        tmr_reg <= tmr_periodic ? tmr_reload : tmr_reg;
                    else
                        tmr_reg <= tmr_reg - 1'b1;
                end
                else if (tmr_mode == 2'b10) begin
                    if (tmr_eq_reload)
                        tmr_reg <= tmr_periodic ? 32'd0 : tmr_reg;
                    else
                        tmr_reg <= tmr_reg + 1'b1;
                end
            end
        end
