        endcase
    end

    always @* begin
        casez ({tmr_dir, tmr_eq_zero, tmr_eq_cmpx,
               tmr_eq_cmpy, tmr_eq_reload})
            5'b?_1_00_0: pwm1_next = pwm_action(pwm1_cfg[1:0],   pwm1_reg);
            5'b1_0_10_0: pwm1_next = pwm_action(pwm1_cfg[3:2],   pwm1_reg);
            5'b1_0_01_0: pwm1_next = pwm_action(pwm1_cfg[5:4],   pwm1_reg);
            5'b?_0_00_1: pwm1_next = pwm_action(pwm1_cfg[7:6],   pwm1_reg);
            5'b0_0_01_0: pwm1_next = pwm_action(pwm1_cfg[9:8],   pwm1_reg);
            5'b0_0_10_0: pwm1_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
            default:     pwm1_next = pwm1_reg;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_reg <= 1'b0;
        else if (pwm0_en && tick)
            pwm0_reg <= pwm_fault ? 1'b0 : pwm0_next;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_reg <= 1'b0;
        else if (pwm1_en && tick)
            pwm1_reg <= pwm_fault ? 1'b0 : pwm1_next;
    end

    reg [7:0] dly_cntr;
    reg pwm0_delayed;
    reg pwm0_out_reg;
    reg pwm1_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dly_cntr <= 8'd0;
        else if (tick) begin
            if (dly_cntr == 8'd0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_delayed <= 1'b0;
        else if (tick && (dly_cntr == 8'd0))
            pwm0_delayed <= pwm0_reg;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_out_reg <= 1'b0;
            pwm1_out_reg <= 1'b0;
        end
        else begin
            if (pwm_dt_en) begin
                pwm0_out_reg <= pwm0_delayed & pwm0_reg;
                pwm1_out_reg <= ~pwm0_delayed & ~pwm0_reg;
            end
            else begin
                pwm0_out_reg <= pwm0_reg;
                pwm1_out_reg <= pwm1_reg;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_armed <= 1'b0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_armed <= 1'b1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_armed <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 1'b0;
        else if (pwm_fault)
            fault_reg <= 1'b1;
        else if (fault_armed &&
                 (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 1'b0;
    end

    assign tmr = tmr_reg;
    assign matchx_flag = tmr_eq_cmpx;
    assign matchy_flag = tmr_eq_cmpy;
    assign timeout_flag = tmr_dir ? tmr_eq_reload : tmr_eq_zero;

    assign pwm0 = (pwm0_out_reg ^ pwm0_inv) & ~fault_reg & pwm0_en;
    assign pwm1 = (pwm1_out_reg ^ pwm1_inv) & ~fault_reg & pwm1_en;

