            if (pwm_dt_en) begin
                pwm0_out <= pwm0_delayed & pwm0_state;
                pwm1_out <= ~pwm0_delayed & ~pwm0_state;
            end else begin
                pwm0_out <= pwm0_state;
                pwm1_out <= pwm1_state;
            end
