module EF_TMR32 #(parameter PRW = 16,
                                PWM_FAULT_CLR_C0 = 16'hA539,
                                PWM_FAULT_CLR_C1 = 16'hA953 
)
(
    input   wire            clk,
    input   wire            rst_n,

    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [ 2:0]     tmr_cfg,     // [2]: Periodic/OneShot; [1:0]: 10: Up, 01: Down, 11: Up/Down
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [ 7:0]     pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,

    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg [1:0] direction;
    reg running;

    reg pwm0_state;
    reg pwm1_state;
    reg pwm0_delayed;
    reg [7:0] dead_count;
    reg pwm0_out;
    reg pwm1_out;

    reg fault_latched;
    reg fault_armed;

    wire start_pulse;
    wire tick;

    ef_util_ped u_te_ped (
        .clk (clk),
        .in  (tmr_en),
        .out (start_pulse)
    );

    assign tick = (pr_reg == {PRW{1'b0}});
    assign tmr = tmr_reg;

    assign matchx_flag = (tmr_reg == cmpx);
    assign matchy_flag = (tmr_reg == cmpy);
    assign timeout_flag = (direction == 2'b01) ?
                          (tmr_reg == 32'd0) :
                          (tmr_reg == tmr_reload);

    function automatic pwm_apply;
        input pwm_current;
        input [1:0] action;
        begin
            case (action)
                2'b01: pwm_apply = 1'b0;
                2'b10: pwm_apply = 1'b1;
                2'b11: pwm_apply = ~pwm_current;
                default: pwm_apply = pwm_current;
            endcase
        end
    endfunction

    wire event_e0;
    wire event_e1;
    wire event_e2;
    wire event_e3;
    wire event_e4;
    wire event_e5;

    assign event_e0 = (tmr_reg == 32'd0) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != cmpy) &&
                      (tmr_reg != tmr_reload);

    assign event_e1 = (direction == 2'b10) &&
                      (tmr_reg == cmpx) &&
                      (tmr_reg != 32'd0) &&
                      (tmr_reg != cmpy) &&
                      (tmr_reg != tmr_reload);

    assign event_e2 = (direction == 2'b10) &&
                      (tmr_reg == cmpy) &&
                      (tmr_reg != 32'd0) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != tmr_reload);

    assign event_e3 = (tmr_reg == tmr_reload) &&
                      (tmr_reg != 32'd0) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != cmpy);

    assign event_e4 = (direction == 2'b01) &&
                      (tmr_reg == cmpy) &&
                      (tmr_reg != 32'd0) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != tmr_reload);

    assign event_e5 = (direction == 2'b01) &&
                      (tmr_reg == cmpx) &&
                      (tmr_reg != 32'd0) &&
                      (tmr_reg != cmpy) &&
                      (tmr_reg != tmr_reload);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pr_reg        <= {{(PRW-1){1'b0}},1'b1};
            tmr_reg       <= 32'd0;
            direction     <= 2'b10;
            running       <= 1'b0;
            pwm0_state    <= 1'b0;
            pwm1_state    <= 1'b0;
            pwm0_delayed  <= 1'b0;
            dead_count    <= 8'd0;
            pwm0_out      <= 1'b0;
            pwm1_out      <= 1'b0;
            fault_latched <= 1'b0;
            fault_armed   <= 1'b0;
        end else begin
            /*
             * Prescaler.  The current zero value denotes a tick; the
             * prescaler is reloaded on the following clock.
             */
            if (!tmr_en)
                pr_reg <= prescaler;
            else if (pr_reg == {PRW{1'b0}})
                pr_reg <= prescaler;
            else
                pr_reg <= pr_reg - {{(PRW-1){1'b0}},1'b1};

            /*
             * Fault latch and key sequence.
             */
            if (pwm_fault)
                fault_latched <= 1'b1;
            else if (fault_armed && (pwm_fault_clr == PWM_FAULT_CLR_C1))
                fault_latched <= 1'b0;

            if (pwm_fault_clr == PWM_FAULT_CLR_C0)
                fault_armed <= 1'b1;
            else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
                fault_armed <= 1'b0;

            /*
             * Timer start and timer operation.
             */
            if (start_pulse) begin
                running   <= 1'b1;
                direction <= (tmr_cfg[1:0] == 2'b01) ? 2'b01 : 2'b10;
                tmr_reg   <= (tmr_cfg[1:0] == 2'b01) ? tmr_reload : 32'd0;
            end else if (tmr_en && tick) begin
                if (tmr_cfg[1:0] == 2'b11) begin
                    if ((direction == 2'b10) &&
                        (tmr_reg == (tmr_reload - 32'd1)))
                        direction <= 2'b01;
                    else if ((direction == 2'b01) &&
                             (tmr_reg == 32'd1))
                        direction <= 2'b10;
                end else if (tmr_cfg[1:0] == 2'b01) begin
                    direction <= 2'b01;
                end else begin
                    direction <= 2'b10;
                end

                if (running) begin
                    if (tmr_start && (tmr_cfg[1:0] == 2'b01)) begin
                        tmr_reg <= tmr_reload;
                    end else if (tmr_start &&
                                 ((tmr_cfg[1:0] == 2'b10) ||
                                  (tmr_cfg[1:0] == 2'b11))) begin
                        tmr_reg <= 32'd0;
                    end else begin
                        case (tmr_cfg[1:0])
                            2'b11: begin
                                if (direction == 2'b10)
                                    tmr_reg <= tmr_reg + 32'd1;
                                else
                                    tmr_reg <= tmr_reg - 32'd1;
                            end

                            2'b01: begin
                                if (tmr_reg == 32'd0) begin
                                    if (tmr_cfg[2])
                                        tmr_reg <= tmr_reload;
                                end else begin
                                    tmr_reg <= tmr_reg - 32'd1;
                                end
                            end

                            2'b10: begin
                                if (tmr_reg == tmr_reload) begin
                                    if (tmr_cfg[2])
                                        tmr_reg <= 32'd0;
                                end else begin
                                    tmr_reg <= tmr_reg + 32'd1;
                                end
                            end

                            default: begin
                                tmr_reg <= tmr_reg;
                            end
                        endcase
                    end

                    if (!tmr_cfg[2] &&
                        tmr_cfg[1] &&
                        (tmr_reg == 32'd1) &&
                        (direction == 2'b01))
                        running <= 1'b0;
                end
            end

            /*
             * PWM event state machines.
             */
            if (tick && pwm0_en) begin
                if (pwm_fault)
                    pwm0_state <= 1'b0;
                else if (event_e0)
                    pwm0_state <= pwm_apply(pwm0_state, pwm0_cfg[1:0]);
                else if (event_e1)
                    pwm0_state <= pwm_apply(pwm0_state, pwm0_cfg[3:2]);
                else if (event_e2)
                    pwm0_state <= pwm_apply(pwm0_state, pwm0_cfg[5:4]);
                else if (event_e3)
                    pwm0_state <= pwm_apply(pwm0_state, pwm0_cfg[7:6]);
                else if (event_e4)
                    pwm0_state <= pwm_apply(pwm0_state, pwm0_cfg[9:8]);
                else if (event_e5)
                    pwm0_state <= pwm_apply(pwm0_state, pwm0_cfg[11:10]);
            end

            if (tick && pwm1_en) begin
                if (pwm_fault)
                    pwm1_state <= 1'b0;
                else if (event_e0)
                    pwm1_state <= pwm_apply(pwm1_state, pwm1_cfg[1:0]);
                else if (event_e1)
                    pwm1_state <= pwm_apply(pwm1_state, pwm1_cfg[3:2]);
                else if (event_e2)
                    pwm1_state <= pwm_apply(pwm1_state, pwm1_cfg[5:4]);
                else if (event_e3)
                    pwm1_state <= pwm_apply(pwm1_state, pwm1_cfg[7:6]);
                else if (event_e4)
                    pwm1_state <= pwm_apply(pwm1_state, pwm1_cfg[9:8]);
                else if (event_e5)
                    pwm1_state <= pwm_apply(pwm1_state, pwm1_cfg[11:10]);
            end

            /*
             * Shared dead-time generator and registered output stage.
             */
            if (tick) begin
                if (dead_count == 8'd0)
                    dead_count <= pwm_dt;
                else
                    dead_count <= dead_count - 8'd1;

                if (dead_count == 8'd0)
                    pwm0_delayed <= pwm0_state;
            end

            if (pwm_dt_en) begin
                pwm0_out <= pwm0_delayed & pwm0_state;
                pwm1_out <= ~pwm0_delayed & ~pwm0_state;
            end else begin
                pwm0_out <= pwm0_state;
                pwm1_out <= pwm1_state;
            end
        end
    end

    assign pwm0 = (pwm0_out ^ pwm0_inv) & pwm0_en &
                  ~pwm_fault & ~fault_latched;
    assign pwm1 = (pwm1_out ^ pwm1_inv) & pwm1_en &
                  ~pwm_fault & ~fault_latched;

endmodule

