module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);
    reg [NUM_STAGES-1:0] sync;

    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};

    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W = 8) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [W-1:0] clk_div,
    output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter  <= 'b0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (clk_div == 'b0) ? 1'b1 : (counter == 'b0);
            if (counter == 'b0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input wire clk,
    input wire rst_n,
    input wire in,
    input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= 'b0;
            out     <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&shifter)
                out <= 1'b1;
            else if (~|shifter)
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW = 8, AW = 4) (
    input wire clk,
    input wire rst_n,
    input wire rd,
    input wire wr,
    input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty,
    output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;

    reg [DW-1:0] array_reg [0:DEPTH-1];
    reg [AW-1:0] w_ptr_reg, r_ptr_reg;
    reg [AW-1:0] level_reg;
    reg full_reg, empty_reg;

    wire do_write = wr && !full_reg;
    wire do_read  = rd && !empty_reg;

    always @(posedge clk) begin
        if (do_write)
            array_reg[w_ptr_reg] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            level_reg <= 'b0;
            full_reg  <= 1'b0;
            empty_reg <= 1'b1;
        end else if (flush) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            level_reg <= 'b0;
            full_reg  <= 1'b0;
            empty_reg <= 1'b1;
        end else begin
            case ({do_write, do_read})
                2'b10: begin
                    w_ptr_reg <= w_ptr_reg + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((w_ptr_reg + 1'b1) == r_ptr_reg)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    r_ptr_reg <= r_ptr_reg + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg  <= 1'b0;
                    if ((r_ptr_reg + 1'b1) == w_ptr_reg)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    w_ptr_reg <= w_ptr_reg + 1'b1;
                    r_ptr_reg <= r_ptr_reg + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

    assign rdata = array_reg[r_ptr_reg];
    assign empty = empty_reg;
    assign full  = full_reg;
    assign level = level_reg;
endmodule

module ef_util_gating_cell (
`ifdef USE_POWER_PINS
    input wire vpwr,
    input wire vgnd,
`endif
    input wire clk,
    input wire rst_n,
    input wire clk_en,
    output wire clk_o
);
`ifdef CLKG_SKY130_HD
    sky130_fd_sc_hd__dlclkp_4 clk_gate (
`ifdef USE_POWER_PINS
        .VPWR(vpwr),
        .VGND(vgnd),
        .VNB(vpwr),
        .VPB(vgnd),
`endif
        .GCLK(clk_o),
        .GATE(clk_en),
        .CLK(clk)
    );
`elsif CLKG_GENERIC
    assign clk_o = clk & clk_en;
`else
    assign clk_o = clk;
`endif
endmodule

module EF_UART #(
    parameter MDW = 9,
    parameter FAW = 4,
    parameter SC = 8,
    parameter GFLEN = 8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire b_tick;
    wire rx_synched, rx_filtered, rx_in;
    wire [MDW-1:0] tx_data, rx_data;
    wire tx_done, rx_done;

    ef_util_sync rx_sync (
        .clk(clk),
        .in(rx),
        .out(rx_synched)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .en(glitch_filter_en),
        .in(rx_synched),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered :
                   rx_synched;

    BAUDGEN baud_gen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_tx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_tx (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(b_tick && tx_en),
        .data_size(data_size),
        .parity_type(parity_type),
        .stop_bits_count(stop_bits_count),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_rx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_rx (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(b_tick && rx_en),
        .data_size(data_size),
        .parity_type(parity_type),
        .stop_bits_count(stop_bits_count),
        .match_data(match_data),
        .rx(rx_in),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .rx_done(rx_done),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count    <= 6'd0;
            samples_count <= 5'd0;
        end else if (rx_done) begin
            bits_count    <= 6'd0;
            samples_count <= 5'd0;
        end else if (b_tick) begin
            if (samples_count == SC-1) begin
                samples_count <= 5'd0;
                if (timeout_flag)
                    bits_count <= 6'd0;
                else
                    bits_count <= bits_count + 1'b1;
            end else begin
                samples_count <= samples_count + 1'b1;
            end
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag   = rx_full && rx_done;
    assign timeout_flag   = (bits_count == timeout_bits);
endmodule

module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'd0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'd0 :
                         count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [8:0] data_reg, next_data_reg;
    reg parity_err_reg, next_parity_err;
    reg frame_err_reg, next_frame_err;
    reg [11:0] brk;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state          <= idle_st;
            sample_count   <= 0;
            bit_count      <= 0;
            data_reg       <= 0;
            parity_err_reg  <= 0;
            frame_err_reg   <= 0;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;

            if (state == idle_st) begin
                parity_err_reg <= 1'b0;
                frame_err_reg  <= 1'b0;
            end else begin
                if (next_parity_err)
                    parity_err_reg <= 1'b1;
                if (next_frame_err)
                    frame_err_reg <= 1'b1;
            end
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_parity_err   = 1'b0;
        next_frame_err    = 1'b0;
        rx_done           = 1'b0;

        case (state)
            idle_st: begin
                if (b_tick && !rx) begin
                    next_state        = start_st;
                    next_sample_count = 0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state        = data_st;
                        next_sample_count = 0;
                        next_bit_count    = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg     = {rx, data_reg[8:1]};
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = stop0_st;
                        case (parity_type)
                            3'b001: if ((~^dout) != rx) next_parity_err = 1'b1;
                            3'b010: if ((^dout)  != rx) next_parity_err = 1'b1;
                            3'b100: if (rx != 1'b0)      next_parity_err = 1'b1;
                            3'b101: if (rx != 1'b1)      next_parity_err = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx)
                            next_frame_err = 1'b1;

                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_err = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            brk <= 12'hfff;
        else if (b_tick && sample_count == NUM_SAMPLES-1) begin
            if (state == idle_st)
                brk <= 12'hfff;
            else
                brk <= {brk[10:0], rx};
        end
    end

    assign dout         = data_reg >> (9-data_size);
    assign parity_error = parity_err_reg && rx_done;
    assign frame_error  = frame_err_reg && rx_done;
    assign match_flag   = (dout == match_data) && rx_done;
    assign break_flag   = (brk == 12'd0);
endmodule

module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state, next_state;
    reg [3:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [8:0] data_reg, next_data_reg;
    reg tx_reg, next_tx_reg;

    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state        <= idle_st;
            sample_count <= 0;
            bit_count    <= 0;
            data_reg     <= 0;
            tx_reg       <= 1'b1;
        end else begin
            state        <= next_state;
            sample_count <= next_sample_count;
            bit_count    <= next_bit_count;
            data_reg     <= next_data_reg;
            tx_reg       <= next_tx_reg;
        end
    end

    always @* begin
        next_state        = state;
        next_sample_count = sample_count;
        next_bit_count    = bit_count;
        next_data_reg     = data_reg;
        next_tx_reg       = tx_reg;
        tx_done           = 1'b0;

        case (state)
            idle_st: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state        = start_st;
                    next_sample_count = 0;
                    next_data_reg     = d_in;
                end
            end

            start_st: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES) begin
                        next_state        = data_st;
                        next_sample_count = 0;
                        next_bit_count    = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            data_st: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg     = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         stop0_st : parity_st;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^pdata;
                    3'b010: next_tx_reg = ^pdata;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b1;
                endcase

                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = stop0_st;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_OFFSET = 16'h0000;
    localparam TXDATA_OFFSET = 16'h0004;
    localparam PR_OFFSET = 16'h0008;
    localparam CTRL_OFFSET = 16'h000c;
    localparam CFG_OFFSET = 16'h0010;
    localparam MATCH_OFFSET = 16'h001c;
    localparam RX_LEVEL_OFFSET = 16'hfe00;
    localparam RX_THRESHOLD_OFFSET = 16'hfe04;
    localparam RX_FLUSH_OFFSET = 16'hfe08;
    localparam TX_LEVEL_OFFSET = 16'hfe10;
    localparam TX_THRESHOLD_OFFSET = 16'hfe14;
    localparam TX_FLUSH_OFFSET = 16'hfe18;
    localparam IM_OFFSET = 16'hff00;
    localparam MIS_OFFSET = 16'hff04;
    localparam RIS_OFFSET = 16'hff08;
    localparam IC_OFFSET = 16'hff0c;
    localparam GCLK_OFFSET = 16'hff10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg, tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;
    reg gclk_reg;

    wire clk_g;
    ef_util_gating_cell clk_gate (
        .clk(PCLK),
        .rst_n(PRESETn),
        .clk_en(gclk_reg),
        .clk_o(clk_g)
    );

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire tx_fifo_wr = apb_we && (PADDR[15:0] == TXDATA_OFFSET);
    wire rx_fifo_rd = apb_re && (PADDR[15:0] == RXDATA_OFFSET);

    wire [9:0] mis = ris_reg & im_reg;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg            <= 16'd0;
            ctrl_reg          <= 5'd0;
            cfg_reg           <= 14'h3f08;
            match_reg         <= 'd0;
            rx_threshold_reg  <= 'd0;
            tx_threshold_reg  <= 'd0;
            rx_flush_reg      <= 1'b0;
            tx_flush_reg      <= 1'b0;
            im_reg            <= 10'd0;
            ic_reg            <= 10'd0;
            gclk_reg          <= 1'b0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg       <= 10'd0;

            if (apb_we) begin
                case (PADDR[15:0])
                    PR_OFFSET:           pr_reg <= PWDATA[15:0];
                    CTRL_OFFSET:         ctrl_reg <= PWDATA[4:0];
                    CFG_OFFSET:          cfg_reg <= PWDATA[13:0];
                    MATCH_OFFSET:        match_reg <= PWDATA[MDW-1:0];
                    RX_THRESHOLD_OFFSET: rx_threshold_reg <= PWDATA[FAW-1:0];
                    TX_THRESHOLD_OFFSET: tx_threshold_reg <= PWDATA[FAW-1:0];
                    RX_FLUSH_OFFSET:     rx_flush_reg <= PWDATA[0];
                    TX_FLUSH_OFFSET:     tx_flush_reg <= PWDATA[0];
                    IM_OFFSET:           im_reg <= PWDATA[9:0];
                    IC_OFFSET:           ic_reg <= PWDATA[9:0];
                    GCLK_OFFSET:         gclk_reg <= PWDATA[0];
                    default: ;
                endcase
            end
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'd0;
        else begin
            if (ic_reg[0]) ris_reg[0] <= 1'b0;
            else if (tx_empty) ris_reg[0] <= 1'b1;

            if (ic_reg[1]) ris_reg[1] <= 1'b0;
            else if (rx_full) ris_reg[1] <= 1'b1;

            if (ic_reg[2]) ris_reg[2] <= 1'b0;
            else if (tx_level_below) ris_reg[2] <= 1'b1;

            if (ic_reg[3]) ris_reg[3] <= 1'b0;
            else if (rx_level_above) ris_reg[3] <= 1'b1;

            if (ic_reg[4]) ris_reg[4] <= 1'b0;
            else if (break_flag) ris_reg[4] <= 1'b1;

            if (ic_reg[5]) ris_reg[5] <= 1'b0;
            else if (match_flag) ris_reg[5] <= 1'b1;

            if (ic_reg[6]) ris_reg[6] <= 1'b0;
            else if (frame_error_flag) ris_reg[6] <= 1'b1;

