module BAUDGEN (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescale,
    input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'b0;
        else if (en) begin
            if (count_reg == prescale)
                count_reg <= 16'b0;
            else
                count_reg <= count_reg + 1'b1;
        end
    end

    assign baudtick = en && (count_reg == prescale);
