module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire tx_start,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam idle_st   = 3'b000;
    localparam start_st  = 3'b001;
    localparam data_st   = 3'b010;
    localparam parity_st = 3'b011;
    localparam stop0_st  = 3'b100;
    localparam stop1_st  = 3'b101;

    reg [2:0] state, next_state;
    reg [4:0] baud_count, next_baud_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg tx_reg, next_tx_reg;

    wire [MDW-1:0] pdata =
        d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= idle_st;
            baud_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            state <= next_state;
            baud_count <= next_baud_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;
            tx_reg <= next_tx_reg;
        end
    end

    always @* begin
        next_state = state;
        next_baud_count = baud_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_tx_reg = tx_reg;
        tx_done = 1'b0;

        case (state)
            idle_st: begin
                next_tx_reg = 1'b1;
                if (tx_start) begin
                    next_state = start_st;
                    next_baud_count = 0;
                    next_data_reg = d_in;
                end
            end

            start_st: begin
                next_tx_reg = 1'b0;
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES) begin
                        next_state = data_st;
                        next_baud_count = 0;
                        next_bit_count = 0;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            data_st: begin
                next_tx_reg = data_reg[0];
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_data_reg = data_reg >> 1;
                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            parity_st: begin
                case (parity_type)
                    3'b001: next_tx_reg = ~^pdata;
                    3'b010: next_tx_reg = ^pdata;
                    3'b100: next_tx_reg = 1'b0;
                    3'b101: next_tx_reg = 1'b1;
                    default: next_tx_reg = 1'b0;
                endcase

                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = stop0_st;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop0_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop1_st: begin
                next_tx_reg = 1'b1;
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk,
    input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam idle_st   = 3'b000;
    localparam start_st  = 3'b001;
    localparam data_st   = 3'b010;
    localparam parity_st = 3'b011;
    localparam stop0_st  = 3'b100;
    localparam stop1_st  = 3'b101;

    reg [2:0] state, next_state;
    reg [4:0] baud_count, next_baud_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data_reg;
    reg parity_error_reg, next_parity_error;
    reg frame_error_reg, next_frame_error;
    reg [11:0] break_shift;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= idle_st;
            baud_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_error_reg <= 1'b0;
            frame_error_reg <= 1'b0;
            break_shift <= 12'b0;
        end else begin
            state <= next_state;
            baud_count <= next_baud_count;
            bit_count <= next_bit_count;
            data_reg <= next_data_reg;

            if (state == idle_st) begin
                parity_error_reg <= 1'b0;
                frame_error_reg <= 1'b0;
            end else begin
                if (next_parity_error)
                    parity_error_reg <= 1'b1;
                if (next_frame_error)
                    frame_error_reg <= 1'b1;
            end

            if (b_tick && (baud_count == NUM_SAMPLES-1)) begin
                if (state == idle_st)
                    break_shift <= 12'b0;
                else
                    break_shift <= {break_shift[10:0], ~rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_baud_count = baud_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_parity_error = 1'b0;
        next_frame_error = 1'b0;
        rx_done = 1'b0;

        case (state)
            idle_st: begin
                if (!rx && b_tick) begin
                    next_state = start_st;
                    next_baud_count = 0;
                end
            end

            start_st: begin
                if (b_tick) begin
                    if (baud_count == (NUM_SAMPLES/2)-1) begin
                        next_state = data_st;
                        next_baud_count = 0;
                        next_bit_count = 0;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            data_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_data_reg = {rx, data_reg[MDW-1:1]};

                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            parity_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = stop0_st;

                        case (parity_type)
                            3'b001:
                                if ((~^dout) != rx)
                                    next_parity_error = 1'b1;
                            3'b010:
                                if ((^dout) != rx)
                                    next_parity_error = 1'b1;
                            3'b100:
                                if (rx != 1'b0)
                                    next_parity_error = 1'b1;
                            3'b101:
                                if (rx != 1'b1)
                                    next_parity_error = 1'b1;
                            default:
                                next_parity_error = 1'b0;
                        endcase
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop0_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        if (!rx)
                            next_frame_error = 1'b1;

                        if (stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            stop1_st: begin
                if (b_tick) begin
                    if (baud_count == NUM_SAMPLES-1) begin
                        next_baud_count = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                        if (!rx)
                            next_frame_error = 1'b1;
                    end else
                        next_baud_count = baud_count + 1'b1;
                end
            end

            default: next_state = idle_st;
        endcase
    end

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = parity_error_reg & rx_done;
    assign frame_error = frame_error_reg & rx_done;
    assign break_flag = &break_shift;
    assign match_flag = (match_data == dout) & rx_done;
endmodule

module EF_UART #(
    parameter MDW=9,
    parameter FAW=4,
    parameter SC=8,
    parameter GFLEN=8
) (
    input wire clk,
    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire baud_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_sync, rx_filtered, rx_in;

    ef_util_sync rx_sync_inst (
        .clk(clk),
        .in(rx),
        .out(rx_sync)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_sync),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud_gen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC), .MDW(MDW)) tx_inst (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(baud_tick && tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.NUM_SAMPLES(SC), .MDW(MDW)) rx_inst (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(baud_tick && rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .rx(rx_in),
        .match_data(match_data),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] bits_count;
    reg [4:0] samples_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bits_count <= 0;
            samples_count <= 0;
        end else if (baud_tick) begin
            if (rx_done) begin
                bits_count <= 0;
                samples_count <= 0;
            end else if (samples_count == SC-1) begin
                samples_count <= 0;
                if (timeout_flag)
                    bits_count <= 0;
                else
                    bits_count <= bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_full && rx_done;
    assign timeout_flag = (bits_count == timeout_bits);
endmodule

module EF_UART_APB #(
