module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk, input wire in, output wire out
);
  reg [NUM_STAGES-1:0] s;
  always @(posedge clk) s <= {s[NUM_STAGES-2:0],in};
  assign out = s[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
  reg [W-1:0] count;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) count <= {W{1'b0}};
    else if (!en) count <= {W{1'b0}};
    else if (count == clk_div) count <= {W{1'b0}};
    else count <= count + 1'b1;
  end
  assign tick = en && (count == clk_div);
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
  reg [N-1:0] sh;
  reg [7:0] divcnt;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sh <= {N{1'b0}};
      divcnt <= 0;
      out <= 1'b0;
    end else if (en) begin
      if (divcnt == CLKDIV) begin
        divcnt <= 0;
        sh <= {sh[N-2:0],in};
        if (&{sh[N-2:0],in}) out <= 1'b1;
        else if (~|{sh[N-2:0],in}) out <= 1'b0;
      end else divcnt <= divcnt + 1'b1;
    end
  end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4)(
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
  localparam DEPTH = (1 << AW);
  reg [DW-1:0] mem [0:DEPTH-1];
  reg [AW-1:0] rp, wp;
  reg [AW:0] count;
  wire do_rd = rd && !empty;
  wire do_wr = wr && !full;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rp <= 0; wp <= 0; count <= 0;
    end else if (flush) begin
      rp <= 0; wp <= 0; count <= 0;
    end else begin
      if (do_wr) begin mem[wp] <= wdata; wp <= wp + 1'b1; end
      if (do_rd) rp <= rp + 1'b1;
      case ({do_wr,do_rd})
        2'b10: count <= count + 1'b1;
        2'b01: count <= count - 1'b1;
        default: count <= count;
      endcase
    end
  end

  assign empty = (count == 0);
  assign full  = (count == DEPTH);
  assign level = count[AW-1:0];
  assign rdata = mem[rp];
endmodule

