module UART_TX #(parameter NUM_SAMPLES=16, MDW=8)(
    input wire clk, input wire resetn, input wire tx_start,
    input wire b_tick, input wire [3:0] data_size,
    input wire stop_bits_count, input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in, output reg tx_done, output wire tx
);
  reg active;
  reg [MDW-1:0] data;
  reg [3:0] nbits, bitno;
  reg [15:0] samples;
  reg [1:0] state;
  reg parity;
  reg txr;

  localparam S_START=0, S_DATA=1, S_PARITY=2, S_STOP=3;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      active <= 0; data <= 0; nbits <= 8; bitno <= 0;
      samples <= 0; state <= S_START; parity <= 0;
      txr <= 1; tx_done <= 0;
    end else begin
      tx_done <= 0;
      if (!active && tx_start) begin
        active <= 1;
        data <= d_in;
        nbits <= (data_size < 5) ? 5 : ((data_size > MDW) ? MDW : data_size);
        bitno <= 0;
        samples <= 0;
        state <= S_START;
        parity <= 0;
        txr <= 0;
      end else if (active && b_tick) begin
        if (samples == NUM_SAMPLES-1) begin
          samples <= 0;
          case (state)
            S_START: begin
              state <= S_DATA;
              bitno <= 0;
              txr <= data[0];
              parity <= data[0];
            end
            S_DATA: begin
              if (bitno + 1 < nbits) begin
                bitno <= bitno + 1'b1;
                txr <= data[bitno+1];
                parity <= parity ^ data[bitno+1];
              end else if (parity_type != 3'b000) begin
                state <= S_PARITY;
                case (parity_type)
                  3'b001: txr <= ~parity;
                  3'b010: txr <= parity;
                  3'b100: txr <= 1'b0;
                  3'b101: txr <= 1'b1;
                  default: txr <= 1'b1;
                endcase
              end else begin
                state <= S_STOP;
                txr <= 1'b1;
              end
            end
            S_PARITY: begin
              state <= S_STOP;
              txr <= 1'b1;
            end
            default: begin
              if (stop_bits_count && bitno == 0) begin
                bitno <= 1;
                txr <= 1'b1;
              end else begin
                active <= 0;
                tx_done <= 1;
                txr <= 1'b1;
                bitno <= 0;
              end
            end
          endcase
        end else samples <= samples + 1'b1;
      end
    end
