        if (!resetn) begin
            state <= idle_st;
            sample_count <= 16'd0;
            bit_count <= 4'd0;
            data_reg <= 'b0;
            parity_error_reg <= 1'b0;
            frame_error_reg <= 1'b0;
            break_reg <= 12'hfff;
            rx_done <= 1'b0;
        end else begin
            rx_done <= 1'b0;

            if (b_tick) begin
                case (state)
                    idle_st: begin
                        sample_count <= 16'd0;
                        bit_count <= 4'd0;
                        parity_error_reg <= 1'b0;
                        frame_error_reg <= 1'b0;
                        break_reg <= 12'hfff;

                        if (!rx) begin
