                end

                stop0_st: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            if (stop_bits_count)
                                state <= stop1_st;
                            else begin
                                state <= idle_st;
                                tx_done <= 1'b1;
                            end
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end
                end

                stop1_st: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            state <= idle_st;
                            tx_done <= 1'b1;
