        if (!rst_n) begin
            counter <= 'b0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (clk_div == 'b0) ? 1'b1 : (counter == 'b0);
            if (counter == 'b0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
