    localparam idle_st   = 3'd0;
    localparam start_st  = 3'd1;
    localparam data_st   = 3'd2;
    localparam parity_st = 3'd3;
    localparam stop0_st  = 3'd4;
    localparam stop1_st  = 3'd5;

    reg [2:0] state;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_error_reg;
    reg frame_error_reg;
    reg [11:0] break_reg;

    wire [MDW-1:0] received_data =
        data_reg >> (MDW - data_size);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= idle_st;
            sample_count <= 16'd0;
            bit_count <= 4'd0;
            data_reg <= 'b0;
            parity_error_reg <= 1'b0;
            frame_error_reg <= 1'b0;
            break_reg <= 12'hfff;
            rx_done <= 1'b0;
        end else begin
            rx_done <= 1'b0;

            if (b_tick) begin
                case (state)
                    idle_st: begin
                        sample_count <= 16'd0;
                        bit_count <= 4'd0;
                        parity_error_reg <= 1'b0;
                        frame_error_reg <= 1'b0;
                        break_reg <= 12'hfff;

                        if (!rx) begin
                            state <= start_st;
                            sample_count <= 16'd0;
                        end
