                    start_st: begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            sample_count <= 16'd0;
                            bit_count <= 4'd0;
                            state <= data_st;
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
