                    data_st: begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            data_reg <= {rx, data_reg[MDW-1:1]};

                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= stop0_st;
                                else
                                    state <= parity_st;
                            end else begin
                                bit_count <= bit_count + 1'b1;
                            end
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end

                    parity_st: begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;

                            case (parity_type)
                                3'b001:
                                    if ((~^received_data) != rx)
