                                3'b010:
                                    if ((^received_data) != rx)
                                        parity_error_reg <= 1'b1;
                                3'b100:
                                    if (rx != 1'b0)
                                        parity_error_reg <= 1'b1;
                                3'b101:
                                    if (rx != 1'b1)
