                    if (tx_start) begin
                        state <= start_st;
                        sample_count <= 16'd0;
                        bit_count <= 4'd0;
                        data_reg <= d_in;

                        case (parity_type)
                            3'b001: parity_bit <= ~^masked_input;
                            3'b010: parity_bit <= ^masked_input;
                            3'b100: parity_bit <= 1'b0;
                            3'b101: parity_bit <= 1'b1;
                            default: parity_bit <= 1'b0;
                        endcase
                    end
                end

                start_st: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 16'd0;
                            bit_count <= 4'd0;
                            state <= data_st;
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end
                end

                data_st: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            data_reg <= data_reg >> 1;

                            if (bit_count == data_size-1) begin
                                if (parity_type == 3'b000)
                                    state <= stop0_st;
                                else
                                    state <= parity_st;
                            end else begin
                                bit_count <= bit_count + 1'b1;
                            end
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end
                end

                parity_st: begin
                    tx_reg <= parity_bit;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            state <= stop0_st;
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end
                end

                stop0_st: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            if (stop_bits_count)
                                state <= stop1_st;
                            else begin
                                state <= idle_st;
                                tx_done <= 1'b1;
                            end
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end
                end

                stop1_st: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 16'd0;
                            state <= idle_st;
                            tx_done <= 1'b1;
                        end else begin
                            sample_count <= sample_count + 1'b1;
                        end
                    end
                end

                default:
                    state <= idle_st;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module EF_UART_APB #(
    parameter SC = 8,
    parameter MDW = 9,
    parameter GFLEN = 8,
    parameter FAW = 4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_REG_OFFSET = 16'h0000;
    localparam TXDATA_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET = 16'h0008;
    localparam CTRL_REG_OFFSET = 16'h000C;
    localparam CFG_REG_OFFSET = 16'h0010;
    localparam MATCH_REG_OFFSET = 16'h001C;
    localparam RX_FIFO_LEVEL_REG_OFFSET = 16'hFE00;
    localparam RX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE04;
    localparam RX_FIFO_FLUSH_REG_OFFSET = 16'hFE08;
    localparam TX_FIFO_LEVEL_REG_OFFSET = 16'hFE10;
    localparam TX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE14;
    localparam TX_FIFO_FLUSH_REG_OFFSET = 16'hFE18;
    localparam IM_REG_OFFSET = 16'hFF00;
    localparam MIS_REG_OFFSET = 16'hFF04;
    localparam RIS_REG_OFFSET = 16'hFF08;
    localparam IC_REG_OFFSET = 16'hFF0C;
    localparam GCLK_REG_OFFSET = 16'hFF10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;
    wire [15:0] addr = PADDR[15:0];

    reg [15:0] PR_REG;
    reg [4:0] CTRL_REG;
    reg [13:0] CFG_REG;
    reg [MDW-1:0] MATCH_REG;
    reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
    reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
    reg RX_FIFO_FLUSH_REG;
    reg TX_FIFO_FLUSH_REG;
    reg GCLK_REG;
    reg [9:0] IM_REG;
    reg [9:0] IC_REG;
    reg [9:0] RIS_REG;

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rdata;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire rx_read = apb_re && (addr == RXDATA_REG_OFFSET);
    wire tx_write = apb_we && (addr == TXDATA_REG_OFFSET);

    wire [9:0] raw_status = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    wire [9:0] MIS = RIS_REG & IM_REG;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            PR_REG <= 16'd0;
            CTRL_REG <= 5'd0;
            CFG_REG <= 14'h3F08;
            MATCH_REG <= 'b0;
            RX_FIFO_THRESHOLD_REG <= 'b0;
            TX_FIFO_THRESHOLD_REG <= 'b0;
            RX_FIFO_FLUSH_REG <= 1'b0;
            TX_FIFO_FLUSH_REG <= 1'b0;
            GCLK_REG <= 1'b0;
            IM_REG <= 10'd0;
            IC_REG <= 10'd0;
        end else begin
            if (apb_we && (addr == PR_REG_OFFSET))
                PR_REG <= PWDATA[15:0];

            if (apb_we && (addr == CTRL_REG_OFFSET))
                CTRL_REG <= PWDATA[4:0];

            if (apb_we && (addr == CFG_REG_OFFSET))
                CFG_REG <= PWDATA[13:0];

            if (apb_we && (addr == MATCH_REG_OFFSET))
                MATCH_REG <= PWDATA[MDW-1:0];

            if (apb_we && (addr == RX_FIFO_THRESHOLD_REG_OFFSET))
                RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

            if (apb_we && (addr == TX_FIFO_THRESHOLD_REG_OFFSET))
                TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

            if (apb_we && (addr == RX_FIFO_FLUSH_REG_OFFSET))
                RX_FIFO_FLUSH_REG <= PWDATA[0];
            else
                RX_FIFO_FLUSH_REG <= 1'b0;

            if (apb_we && (addr == TX_FIFO_FLUSH_REG_OFFSET))
                TX_FIFO_FLUSH_REG <= PWDATA[0];
            else
                TX_FIFO_FLUSH_REG <= 1'b0;

            if (apb_we && (addr == GCLK_REG_OFFSET))
                GCLK_REG <= PWDATA[0];

            if (apb_we && (addr == IM_REG_OFFSET))
                IM_REG <= PWDATA[9:0];

            if (apb_we && (addr == IC_REG_OFFSET))
                IC_REG <= PWDATA[9:0];
            else
                IC_REG <= 10'd0;
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            RIS_REG <= 10'd0;
        end else begin
            if (IC_REG != 10'd0)
                RIS_REG <= (RIS_REG & ~IC_REG) | (raw_status & ~IC_REG);
            else
                RIS_REG <= RIS_REG | raw_status;
        end
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) uart_core (
        .clk(PCLK),
        .rst_n(PRESETn),
        .prescaler(PR_REG),
        .en(CTRL_REG[0]),
        .tx_en(CTRL_REG[1]),
        .rx_en(CTRL_REG[2]),
        .rd(rx_read),
        .wr(tx_write),
        .wdata(PWDATA[MDW-1:0]),
        .data_size(CFG_REG[3:0]),
        .stop_bits_count(CFG_REG[4]),
        .parity_type(CFG_REG[7:5]),
        .txfifotr(TX_FIFO_THRESHOLD_REG),
        .rxfifotr(RX_FIFO_THRESHOLD_REG),
        .match_data(MATCH_REG),
        .timeout_bits(CFG_REG[13:8]),
        .loopback_en(CTRL_REG[3]),
        .glitch_filter_en(CTRL_REG[4]),
        .tx_fifo_flush(TX_FIFO_FLUSH_REG),
        .rx_fifo_flush(RX_FIFO_FLUSH_REG),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA_REG_OFFSET) ? {{(32-MDW){1'b0}}, rdata} :
        (addr == PR_REG_OFFSET) ? {{16{1'b0}}, PR_REG} :
        (addr == CTRL_REG_OFFSET) ? {{27{1'b0}}, CTRL_REG} :
        (addr == CFG_REG_OFFSET) ? {{18{1'b0}}, CFG_REG} :
        (addr == MATCH_REG_OFFSET) ? {{(32-MDW){1'b0}}, MATCH_REG} :
        (addr == RX_FIFO_LEVEL_REG_OFFSET) ? {{(32-FAW){1'b0}}, rx_level} :
        (addr == RX_FIFO_THRESHOLD_REG_OFFSET) ? {{(32-FAW){1'b0}}, RX_FIFO_THRESHOLD_REG} :
        (addr == RX_FIFO_FLUSH_REG_OFFSET) ? {31'd0, RX_FIFO_FLUSH_REG} :
        (addr == TX_FIFO_LEVEL_REG_OFFSET) ? {{(32-FAW){1'b0}}, tx_level} :
        (addr == TX_FIFO_THRESHOLD_REG_OFFSET) ? {{(32-FAW){1'b0}}, TX_FIFO_THRESHOLD_REG} :
        (addr == TX_FIFO_FLUSH_REG_OFFSET) ? {31'd0, TX_FIFO_FLUSH_REG} :
        (addr == IM_REG_OFFSET) ? {{22{1'b0}}, IM_REG} :
        (addr == MIS_REG_OFFSET) ? {{22{1'b0}}, MIS} :
        (addr == RIS_REG_OFFSET) ? {{22{1'b0}}, RIS_REG} :
        (addr == GCLK_REG_OFFSET) ? {31'd0, GCLK_REG} :
        32'hDEADBEEF;

    assign PREADY = 1'b1;
    assign IRQ = |MIS;
endmodule

