module EF_TMR32 #(
    parameter PRW = 16,
    PWM_FAULT_CLR_C0 = 16'hA539,
    PWM_FAULT_CLR_C1 = 16'hA953
) (
    input  wire           clk,
    input  wire           rst_n,

    input  wire           tmr_en,
    input  wire           tmr_start,
    input  wire           pwm0_en,
    input  wire           pwm1_en,
    input  wire [31:0]    tmr_reload,
    input  wire [31:0]    cmpx,
    input  wire [31:0]    cmpy,
    input  wire [PRW-1:0] prescaler,
    input  wire [2:0]     tmr_cfg,
    input  wire [11:0]    pwm0_cfg,
    input  wire [11:0]    pwm1_cfg,
    input  wire           pwm0_inv,
    input  wire           pwm1_inv,
    input  wire [7:0]     pwm_dt,
    input  wire [15:0]    pwm_fault_clr,
    input  wire           pwm_dt_en,

    output wire [31:0]    tmr,
    output wire           matchx_flag,
    output wire           matchy_flag,
    output wire           timeout_flag,

    input  wire           pwm_fault,
    output wire           pwm0,
    output wire           pwm1
);

    wire [1:0] tmr_mode = tmr_cfg[1:0];
    wire       tmr_periodic = tmr_cfg[2];

    reg [31:0]  tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg         tmr_run;
    reg         tmr_dir;
    reg         fault_reg;
    reg         fault_armed;

    wire start_pulse;
    wire tick = (pr_reg == {PRW{1'b0}});

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}},1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
    end

    wire tmr_eq_reload     = (tmr_reg == tmr_reload);
    wire tmr_eq_zero       = (tmr_reg == 32'b0);
    wire tmr_eq_reload_m_1 = (tmr_reg == (tmr_reload - 1'b1));
    wire tmr_eq_one        = (tmr_reg == 32'd1);
    wire tmr_eq_cmpx       = (tmr_reg == cmpx);
    wire tmr_eq_cmpy       = (tmr_reg == cmpy);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_run <= 1'b0;
        else if (start_pulse)
            tmr_run <= 1'b1;
        else if (!tmr_periodic && tick &&
                 tmr_mode[0] && tmr_eq_one && !tmr_dir)
            tmr_run <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_reg <= 32'b0;
        else if (start_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_reg <= tmr_reload;
            else
                tmr_reg <= 32'b0;
        end
        else if (tmr_en && tick && tmr_run) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_dir)
                    tmr_reg <= tmr_reg + 1'b1;
                else
                    tmr_reg <= tmr_reg - 1'b1;
            end
            else if (tmr_mode == 2'b01) begin
                if (tmr_eq_zero)
                    tmr_reg <= tmr_periodic ? tmr_reload : tmr_reg;
                else
                    tmr_reg <= tmr_reg - 1'b1;
            end
            else if (tmr_mode == 2'b10) begin
                if (tmr_eq_reload)
                    tmr_reg <= tmr_periodic ? 32'b0 : tmr_reg;
                else
                    tmr_reg <= tmr_reg + 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_dir <= 1'b1;
        else if (start_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end
        else if (tick) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_dir && tmr_eq_reload_m_1)
                    tmr_dir <= 1'b0;
                else if (!tmr_dir && tmr_eq_one)
                    tmr_dir <= 1'b1;
            end
            else if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end
    end

    function automatic pwm_action;
        input [1:0] action;
        input       current;
        begin
            case (action)
                2'b00: pwm_action = current;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                default: pwm_action = ~current;
            endcase
        end
    endfunction

    wire e0 = tmr_eq_zero && !tmr_eq_cmpx && !tmr_eq_cmpy &&
              !tmr_eq_reload;
    wire e1 = tmr_dir && tmr_eq_cmpx && !tmr_eq_zero &&
              !tmr_eq_cmpy && !tmr_eq_reload;
    wire e2 = tmr_dir && tmr_eq_cmpy && !tmr_eq_zero &&
              !tmr_eq_cmpx && !tmr_eq_reload;
    wire e3 = tmr_eq_reload && !tmr_eq_zero && !tmr_eq_cmpx &&
              !tmr_eq_cmpy;
    wire e4 = !tmr_dir && tmr_eq_cmpy && !tmr_eq_zero &&
              !tmr_eq_cmpx && !tmr_eq_reload;
    wire e5 = !tmr_dir && tmr_eq_cmpx && !tmr_eq_zero &&
              !tmr_eq_cmpy && !tmr_eq_reload;

    wire [5:0] pwm_event = {e5,e4,e3,e2,e1,e0};

    reg pwm0_reg;
    reg pwm1_reg;
    reg pwm0_reg_next;
    reg pwm1_reg_next;

    always @* begin
        pwm0_reg_next = pwm0_reg;
        if (pwm_event == 6'b000001)
            pwm0_reg_next = pwm_action(pwm0_cfg[1:0], pwm0_reg);
        else if (pwm_event == 6'b000010)
            pwm0_reg_next = pwm_action(pwm0_cfg[3:2], pwm0_reg);
        else if (pwm_event == 6'b000100)
            pwm0_reg_next = pwm_action(pwm0_cfg[5:4], pwm0_reg);
        else if (pwm_event == 6'b001000)
            pwm0_reg_next = pwm_action(pwm0_cfg[7:6], pwm0_reg);
        else if (pwm_event == 6'b010000)
            pwm0_reg_next = pwm_action(pwm0_cfg[9:8], pwm0_reg);
        else if (pwm_event == 6'b100000)
            pwm0_reg_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
    end

    always @* begin
        pwm1_reg_next = pwm1_reg;
        if (pwm_event == 6'b000001)
            pwm1_reg_next = pwm_action(pwm1_cfg[1:0], pwm1_reg);
        else if (pwm_event == 6'b000010)
            pwm1_reg_next = pwm_action(pwm1_cfg[3:2], pwm1_reg);
        else if (pwm_event == 6'b000100)
            pwm1_reg_next = pwm_action(pwm1_cfg[5:4], pwm1_reg);
        else if (pwm_event == 6'b001000)
            pwm1_reg_next = pwm_action(pwm1_cfg[7:6], pwm1_reg);
        else if (pwm_event == 6'b010000)
            pwm1_reg_next = pwm_action(pwm1_cfg[9:8], pwm1_reg);
        else if (pwm_event == 6'b100000)
            pwm1_reg_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_reg <= 1'b0;
        else if (pwm0_en && tick)
            pwm0_reg <= pwm_fault ? 1'b0 : pwm0_reg_next;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_reg <= 1'b0;
        else if (pwm1_en && tick)
            pwm1_reg <= pwm_fault ? 1'b0 : pwm1_reg_next;
    end

    reg [7:0] dly_cntr;
    reg       pwm0_delayed;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dly_cntr <= 8'b0;
        else if (tick) begin
            if (dly_cntr == 8'b0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_delayed <= 1'b0;
        else if (tick && dly_cntr == 8'b0)
            pwm0_delayed <= pwm0_reg;
    end

    reg pwm0_w_dt;
    reg pwm1_w_dt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm0_w_dt <= 1'b0;
        else if (pwm_dt_en)
            pwm0_w_dt <= pwm0_delayed & pwm0_reg;
        else
            pwm0_w_dt <= pwm0_reg;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm1_w_dt <= 1'b0;
        else if (pwm_dt_en)
            pwm1_w_dt <= ~pwm0_delayed & ~pwm0_reg;
        else
            pwm1_w_dt <= pwm1_reg;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_armed <= 1'b0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_armed <= 1'b1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_armed <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 1'b0;
        else if (pwm_fault)
            fault_reg <= 1'b1;
        else if (fault_armed && (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 1'b0;
    end

    assign tmr          = tmr_reg;
    assign matchx_flag  = tmr_eq_cmpx;
    assign matchy_flag  = tmr_eq_cmpy;
    assign timeout_flag = tmr_dir ? tmr_eq_reload : tmr_eq_zero;

    assign pwm0 = (pwm0_w_dt ^ pwm0_inv) & ~fault_reg & pwm0_en;
    assign pwm1 = (pwm1_w_dt ^ pwm1_inv) & ~fault_reg & pwm1_en;

endmodule

module EF_TMR32_APB #(
    parameter PRW = 16
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [31:0]  PWDATA,
    input  wire [31:0]  PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [31:0]  PRDATA,
    output wire         IRQ,
    output wire [0:0]   pwm0,
    output wire [0:0]   pwm1,
    input  wire [0:0]   pwm_fault
);

    localparam TMR_REG_OFFSET    = 16'h0000;
    localparam RELOAD_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET     = 16'h0008;
    localparam CMPX_REG_OFFSET   = 16'h000C;
    localparam CMPY_REG_OFFSET   = 16'h0010;
    localparam CTRL_REG_OFFSET   = 16'h0014;
    localparam CFG_REG_OFFSET    = 16'h0018;
    localparam PWM0CFG_REG_OFFSET = 16'h001C;
    localparam PWM1CFG_REG_OFFSET = 16'h0020;
    localparam PWMDT_REG_OFFSET  = 16'h0024;
    localparam PWMFC_REG_OFFSET  = 16'h0028;
    localparam IM_REG_OFFSET     = 16'hFF00;
    localparam MIS_REG_OFFSET    = 16'hFF04;
    localparam RIS_REG_OFFSET    = 16'hFF08;
    localparam IC_REG_OFFSET     = 16'hFF0C;
    localparam GCLK_REG_OFFSET   = 16'hFF10;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = apb_valid & PWRITE;

    reg [0:0] GCLK_REG;
    reg [31:0] RELOAD_REG;
    reg [PRW-1:0] PR_REG;
    reg [31:0] CMPX_REG;
    reg [31:0] CMPY_REG;
    reg [6:0] CTRL_REG;
    reg [2:0] CFG_REG;
    reg [11:0] PWM0CFG_REG;
    reg [15:0] PWM1CFG_REG;
    reg [7:0] PWMDT_REG;
    reg [15:0] PWMFC_REG;
    reg [2:0] IM_REG;
    reg [2:0] IC_REG;
    reg [2:0] RIS_REG;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) RELOAD_REG <= 32'b0;
        else if (apb_we && PADDR[15:0] == RELOAD_REG_OFFSET)
            RELOAD_REG <= PWDATA;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) PR_REG <= 'b0;
        else if (apb_we && PADDR[15:0] == PR_REG_OFFSET)
            PR_REG <= PWDATA[PRW-1:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) CMPX_REG <= 32'b0;
        else if (apb_we && PADDR[15:0] == CMPX_REG_OFFSET)
            CMPX_REG <= PWDATA;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) CMPY_REG <= 32'b0;
        else if (apb_we && PADDR[15:0] == CMPY_REG_OFFSET)
            CMPY_REG <= PWDATA;
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) CTRL_REG <= 7'b0;
        else if (apb_we && PADDR[15:0] == CTRL_REG_OFFSET)
            CTRL_REG <= PWDATA[6:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) CFG_REG <= 3'b0;
        else if (apb_we && PADDR[15:0] == CFG_REG_OFFSET)
            CFG_REG <= PWDATA[2:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) PWM0CFG_REG <= 12'b0;
        else if (apb_we && PADDR[15:0] == PWM0CFG_REG_OFFSET)
            PWM0CFG_REG <= PWDATA[11:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) PWM1CFG_REG <= 16'b0;
        else if (apb_we && PADDR[15:0] == PWM1CFG_REG_OFFSET)
            PWM1CFG_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) PWMDT_REG <= 8'b0;
        else if (apb_we && PADDR[15:0] == PWMDT_REG_OFFSET)
            PWMDT_REG <= PWDATA[7:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) PWMFC_REG <= 16'b0;
        else if (apb_we && PADDR[15:0] == PWMFC_REG_OFFSET)
            PWMFC_REG <= PWDATA[15:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) GCLK_REG <= 1'b0;
        else if (apb_we && PADDR[15:0] == GCLK_REG_OFFSET)
            GCLK_REG <= PWDATA[0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) IM_REG <= 3'b0;
        else if (apb_we && PADDR[15:0] == IM_REG_OFFSET)
            IM_REG <= PWDATA[2:0];
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            IC_REG <= 3'b0;
        else if (apb_we && PADDR[15:0] == IC_REG_OFFSET)
            IC_REG <= PWDATA[2:0];
        else
            IC_REG <= 3'b0;
    end

    wire [2:0] flags = {
        instance_to_wrap.matchy_flag,
        instance_to_wrap.matchx_flag,
        instance_to_wrap.timeout_flag
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'b0;
        else begin
            for (i = 0; i < 3; i = i + 1) begin
                if (IC_REG[i])
                    RIS_REG[i] <= 1'b0;
                else if (flags[i])
                    RIS_REG[i] <= 1'b1;
            end
        end
    end

    wire [2:0] MIS = RIS_REG & IM_REG;

    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk(PCLK),
        .rst_n(PRESETn),
        .tmr_en(CTRL_REG[0]),
        .tmr_start(CTRL_REG[1]),
        .pwm0_en(CTRL_REG[2]),
        .pwm1_en(CTRL_REG[3]),
        .tmr_reload(RELOAD_REG),
        .cmpx(CMPX_REG),
        .cmpy(CMPY_REG),
        .prescaler(PR_REG),
        .tmr_cfg(CFG_REG),
        .pwm0_cfg(PWM0CFG_REG),
        .pwm1_cfg(PWM1CFG_REG[11:0]),
        .pwm0_inv(CTRL_REG[5]),
        .pwm1_inv(CTRL_REG[6]),
        .pwm_dt(PWMDT_REG),
        .pwm_fault_clr(PWMFC_REG),
        .pwm_dt_en(CTRL_REG[4]),
        .tmr(),
        .matchx_flag(),
        .matchy_flag(),
        .timeout_flag(),
        .pwm_fault(pwm_fault[0]),
        .pwm0(pwm0[0]),
        .pwm1(pwm1[0])
    );

    wire [31:0] tmr_read;
    wire matchx_read;
    wire matchy_read;
    wire timeout_read;

    EF_TMR32 #(
        .PRW(PRW)
    ) unused_read_signals (
        .clk(1'b0),
        .rst_n(1'b1),
        .tmr_en(1'b0),
        .tmr_start(1'b0),
        .pwm0_en(1'b0),
        .pwm1_en(1'b0),
        .tmr_reload(32'b0),
        .cmpx(32'b0),
        .cmpy(32'b0),
        .prescaler({PRW{1'b0}}),
        .tmr_cfg(3'b0),
        .pwm0_cfg(12'b0),
        .pwm1_cfg(12'b0),
        .pwm0_inv(1'b0),
        .pwm1_inv(1'b0),
        .pwm_dt(8'b0),
        .pwm_fault_clr(16'b0),
        .pwm_dt_en(1'b0),
        .tmr(tmr_read),
        .matchx_flag(matchx_read),
        .matchy_flag(matchy_read),
        .timeout_flag(timeout_read),
        .pwm_fault(1'b0),
        .pwm0(),
        .pwm1()
    );

    assign PRDATA =
        (PADDR[15:0] == TMR_REG_OFFSET)     ? tmr_read :
        (PADDR[15:0] == RELOAD_REG_OFFSET)  ? RELOAD_REG :
        (PADDR[15:0] == PR_REG_OFFSET)      ? PR_REG :
        (PADDR[15:0] == CMPX_REG_OFFSET)    ? CMPX_REG :
        (PADDR[15:0] == CMPY_REG_OFFSET)    ? CMPY_REG :
        (PADDR[15:0] == CTRL_REG_OFFSET)    ? CTRL_REG :
        (PADDR[15:0] == CFG_REG_OFFSET)     ? CFG_REG :
        (PADDR[15:0] == PWM0CFG_REG_OFFSET) ? PWM0CFG_REG :
        (PADDR[15:0] == PWM1CFG_REG_OFFSET) ? PWM1CFG_REG :
        (PADDR[15:0] == PWMDT_REG_OFFSET)   ? PWMDT_REG :
        (PADDR[15:0] == PWMFC_REG_OFFSET)   ? PWMFC_REG :
        (PADDR[15:0] == IM_REG_OFFSET)      ? IM_REG :
        (PADDR[15:0] == MIS_REG_OFFSET)     ? MIS :
        (PADDR[15:0] == RIS_REG_OFFSET)     ? RIS_REG :
        (PADDR[15:0] == GCLK_REG_OFFSET)    ? GCLK_REG :
        32'hDEADBEEF;

    assign IRQ = |MIS;
    assign PREADY = 1'b1;

endmodule

