module EF_TMR32 #(parameter PRW = 16,
                                PWM_FAULT_CLR_C0 = 16'hA539,
                                PWM_FAULT_CLR_C1 = 16'hA953 
)
(
    input   wire            clk,
    input   wire            rst_n,

    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [ 2:0]     tmr_cfg,
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [ 7:0]     pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,

    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg direction_down;
    reg running;

    reg pwm0_state;
    reg pwm1_state;
    reg pwm_fault_latched;
    reg pwm_fault_armed;

    reg [7:0] dead_count;
    reg pwm0_delayed;
    reg pwm0_out_reg;
    reg pwm1_out_reg;

    wire start_pulse;
    wire tick;

    wire event_e0;
    wire event_e1;
    wire event_e2;
    wire event_e3;
    wire event_e4;
    wire event_e5;
    wire [5:0] pwm_event;
    wire event_one;

    wire [1:0] dir_cfg = tmr_cfg[1:0];
    wire periodic = tmr_cfg[2];

    assign tmr = tmr_reg;
    assign tick = (pr_reg == {PRW{1'b0}});

    ef_util_ped te_edge_detector (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
    );

    assign matchx_flag = (tmr_reg == cmpx);
    assign matchy_flag = (tmr_reg == cmpy);

    assign timeout_flag = direction_down ?
                          (tmr_reg == 32'h00000000) :
                          (tmr_reg == tmr_reload);

    /*
     * PWM events are deliberately mutually qualified.  If compare,
     * zero, and reload values coincide, no action is taken.
     */
    assign event_e0 = (tmr_reg == 32'h00000000) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != cmpy) &&
                      (tmr_reg != tmr_reload);

    assign event_e1 = !direction_down &&
                      (tmr_reg == cmpx) &&
                      (tmr_reg != 32'h00000000) &&
                      (tmr_reg != cmpy) &&
                      (tmr_reg != tmr_reload);

    assign event_e2 = !direction_down &&
                      (tmr_reg == cmpy) &&
                      (tmr_reg != 32'h00000000) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != tmr_reload);

    assign event_e3 = (tmr_reg == tmr_reload) &&
                      (tmr_reg != 32'h00000000) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != cmpy);

    assign event_e4 = direction_down &&
                      (tmr_reg == cmpy) &&
                      (tmr_reg != 32'h00000000) &&
                      (tmr_reg != cmpx) &&
                      (tmr_reg != tmr_reload);

    assign event_e5 = direction_down &&
                      (tmr_reg == cmpx) &&
                      (tmr_reg != 32'h00000000) &&
                      (tmr_reg != cmpy) &&
                      (tmr_reg != tmr_reload);

    assign pwm_event = {event_e5, event_e4, event_e3,
                        event_e2, event_e1, event_e0};

    assign event_one = (pwm_event == 6'b000001) ||
                       (pwm_event == 6'b000010) ||
                       (pwm_event == 6'b000100) ||
                       (pwm_event == 6'b001000) ||
                       (pwm_event == 6'b010000) ||
                       (pwm_event == 6'b100000);

    function automatic pwm_action;
        input pwm_action;
        input [1:0] action;
        begin
            case (action)
                2'b00: pwm_action = pwm_action;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                2'b11: pwm_action = ~pwm_action;
                default: pwm_action = pwm_action;
            endcase
        end
    endfunction

    /*
     * Prescaler and timer/PWM state.
     */
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pr_reg            <= {{(PRW-1){1'b0}},1'b1};
            tmr_reg           <= 32'h00000000;
            direction_down    <= 1'b0;
            running           <= 1'b0;
            pwm0_state        <= 1'b0;
            pwm1_state        <= 1'b0;
            pwm_fault_latched <= 1'b0;
            pwm_fault_armed   <= 1'b0;
            dead_count        <= 8'h00;
            pwm0_delayed      <= 1'b0;
        end
        else begin
            if (!tmr_en)
                pr_reg <= prescaler;
            else if (pr_reg == {PRW{1'b0}})
                pr_reg <= prescaler;
            else
                pr_reg <= pr_reg - {{(PRW-1){1'b0}},1'b1};

            if (pwm_fault)
                pwm_fault_latched <= 1'b1;
            else if (pwm_fault_armed &&
                     (pwm_fault_clr == PWM_FAULT_CLR_C1))
                pwm_fault_latched <= 1'b0;

            if (pwm_fault_clr == PWM_FAULT_CLR_C0)
                pwm_fault_armed <= 1'b1;
            else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
                pwm_fault_armed <= 1'b0;

            if (start_pulse) begin
                if (dir_cfg == 2'b01) begin
                    tmr_reg        <= tmr_reload;
                    direction_down <= 1'b1;
                end
                else begin
                    tmr_reg        <= 32'h00000000;
                    direction_down <= 1'b0;
                end
                running <= 1'b1;
            end
            else if (tick) begin
                /*
                 * Direction is updated on every tick, including ticks
                 * occurring while the timer is disabled.
                 */
                case (dir_cfg)
                    2'b11: begin
                        if (!direction_down) begin
                            if (tmr_reg == (tmr_reload - 32'd1))
                                direction_down <= 1'b1;
                        end
                        else begin
                            if (tmr_reg == 32'd1)
                                direction_down <= 1'b0;
                        end
                    end
                    2'b01: direction_down <= 1'b1;
                    default: direction_down <= 1'b0;
                endcase

                if (tmr_en && running) begin
                    if (tmr_cfg[1:0] == 2'b01) begin
                        if (tmr_start)
                            tmr_reg <= tmr_reload;
                        else if (tmr_reg == 32'h00000000) begin
                            if (periodic)
                                tmr_reg <= tmr_reload;
                        end
                        else
                            tmr_reg <= tmr_reg - 32'd1;
                    end
                    else if (tmr_cfg[1:0] == 2'b10) begin
                        if (tmr_start)
                            tmr_reg <= 32'h00000000;
                        else if (tmr_reg == tmr_reload) begin
                            if (periodic)
                                tmr_reg <= 32'h00000000;
                        end
                        else
                            tmr_reg <= tmr_reg + 32'd1;
                    end
                    else if (tmr_cfg[1:0] == 2'b11) begin
                        if (tmr_start)
                            tmr_reg <= 32'h00000000;
                        else if (direction_down)
                            tmr_reg <= tmr_reg - 32'd1;
                        else
                            tmr_reg <= tmr_reg + 32'd1;
                    end

                    if (!periodic && tmr_cfg[0] &&
                        direction_down && (tmr_reg == 32'd1))
                        running <= 1'b0;
                end

                if (pwm0_en) begin
                    if (pwm_fault)
                        pwm0_state <= 1'b0;
                    else if (event_one) begin
                        case (pwm_event)
                            6'b000001: pwm0_state <=
                                pwm_action(pwm0_state, pwm0_cfg[1:0]);
                            6'b000010: pwm0_state <=
                                pwm_action(pwm0_state, pwm0_cfg[3:2]);
                            6'b000100: pwm0_state <=
                                pwm_action(pwm0_state, pwm0_cfg[5:4]);
                            6'b001000: pwm0_state <=
                                pwm_action(pwm0_state, pwm0_cfg[7:6]);
                            6'b010000: pwm0_state <=
                                pwm_action(pwm0_state, pwm0_cfg[9:8]);
                            6'b100000: pwm0_state <=
                                pwm_action(pwm0_state, pwm0_cfg[11:10]);
                            default: pwm0_state <= pwm0_state;
                        endcase
                    end
                end

                if (pwm1_en) begin
                    if (pwm_fault)
                        pwm1_state <= 1'b0;
                    else if (event_one) begin
                        case (pwm_event)
                            6'b000001: pwm1_state <=
                                pwm_action(pwm1_state, pwm1_cfg[1:0]);
                            6'b000010: pwm1_state <=
                                pwm_action(pwm1_state, pwm1_cfg[3:2]);
                            6'b000100: pwm1_state <=
                                pwm_action(pwm1_state, pwm1_cfg[5:4]);
                            6'b001000: pwm1_state <=
                                pwm_action(pwm1_state, pwm1_cfg[7:6]);
                            6'b010000: pwm1_state <=
                                pwm_action(pwm1_state, pwm1_cfg[9:8]);
                            6'b100000: pwm1_state <=
                                pwm_action(pwm1_state, pwm1_cfg[11:10]);
                            default: pwm1_state <= pwm1_state;
                        endcase
                    end
                end

                if (dead_count == 8'h00) begin
                    dead_count   <= pwm_dt;
                    pwm0_delayed <= pwm0_state;
                end
                else begin
                    dead_count <= dead_count - 8'd1;
                end
            end
        end
    end

    /*
     * Registered output stage.
     */
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_out_reg <= 1'b0;
            pwm1_out_reg <= 1'b0;
        end
        else if (pwm_dt_en) begin
            pwm0_out_reg <= pwm0_delayed & pwm0_state;
            pwm1_out_reg <= ~pwm0_delayed & ~pwm0_state;
        end
        else begin
            pwm0_out_reg <= pwm0_state;
            pwm1_out_reg <= pwm1_state;
        end
    end

    assign pwm0 = (pwm0_out_reg ^ pwm0_inv) &
                  ~pwm_fault_latched & pwm0_en;

    assign pwm1 = (pwm1_out_reg ^ pwm1_inv) &
                  ~pwm_fault_latched & pwm1_en;

endmodule

module EF_TMR32_APB #(
    parameter PRW = 16
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [31:0]  PWDATA,
    input  wire [31:0]  PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [31:0]  PRDATA,
    output wire         IRQ,
    output wire [1-1:0] pwm0,
    output wire [1-1:0] pwm1,
    input  wire [1-1:0] pwm_fault
);

  localparam TMR_REG_OFFSET = 16'h0000;
  localparam RELOAD_REG_OFFSET = 16'h0004;
  localparam PR_REG_OFFSET = 16'h0008;
  localparam CMPX_REG_OFFSET = 16'h000C;
  localparam CMPY_REG_OFFSET = 16'h0010;
  localparam CTRL_REG_OFFSET = 16'h0014;
  localparam CFG_REG_OFFSET = 16'h0018;
  localparam PWM0CFG_REG_OFFSET = 16'h001C;
  localparam PWM1CFG_REG_OFFSET = 16'h0020;
  localparam PWMDT_REG_OFFSET = 16'h0024;
  localparam PWMFC_REG_OFFSET = 16'h0028;
  localparam IM_REG_OFFSET = 16'hFF00;
  localparam MIS_REG_OFFSET = 16'hFF04;
  localparam RIS_REG_OFFSET = 16'hFF08;
  localparam IC_REG_OFFSET = 16'hFF0C;

  reg [0:0] GCLK_REG;
  wire clk_g;

  wire clk_gated_en = GCLK_REG[0];
  ef_util_gating_cell clk_gate_cell (
      .clk(PCLK),
      .clk_en(clk_gated_en),
      .clk_o(clk_g)
  );

  wire clk = clk_g;
  wire rst_n = PRESETn;

  wire apb_valid = PSEL & PENABLE;
  wire apb_we = PWRITE & apb_valid;
  wire apb_re = ~PWRITE & apb_valid;

  wire [0:0] tmr_en;
  wire [0:0] tmr_start;
  wire [0:0] pwm0_en;
  wire [0:0] pwm1_en;
  wire [31:0] tmr_reload;
  wire [31:0] cmpx;
  wire [31:0] cmpy;
  wire [PRW-1:0] prescaler;
  wire [2:0] tmr_cfg;
  wire [11:0] pwm0_cfg;
  wire [11:0] pwm1_cfg;
  wire [0:0] pwm0_inv;
  wire [0:0] pwm1_inv;
  wire [7:0] pwm_dt;
  wire [15:0] pwm_fault_clr;
  wire [0:0] pwm_dt_en;
  wire [31:0] tmr;
  wire [0:0] matchx_flag;
  wire [0:0] matchy_flag;
  wire [0:0] timeout_flag;

  wire [31:0] TMR_WIRE;
  assign TMR_WIRE = tmr;

  reg [31:0] RELOAD_REG;
  assign tmr_reload = RELOAD_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) RELOAD_REG <= 0;
    else if (apb_we && (PADDR[15:0] == RELOAD_REG_OFFSET))
      RELOAD_REG <= PWDATA[31:0];

  reg [PRW-1:0] PR_REG;
  assign prescaler = PR_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PR_REG <= 'h0;
    else if (apb_we && (PADDR[15:0] == PR_REG_OFFSET))
      PR_REG <= PWDATA[PRW-1:0];

  reg [31:0] CMPX_REG;
  assign cmpx = CMPX_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CMPX_REG <= 0;
    else if (apb_we && (PADDR[15:0] == CMPX_REG_OFFSET))
      CMPX_REG <= PWDATA[31:0];

  reg [31:0] CMPY_REG;
  assign cmpy = CMPY_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CMPY_REG <= 0;
    else if (apb_we && (PADDR[15:0] == CMPY_REG_OFFSET))
      CMPY_REG <= PWDATA[31:0];

  reg [6:0] CTRL_REG;
  assign tmr_en = CTRL_REG[0:0];
  assign tmr_start = CTRL_REG[1:1];
  assign pwm0_en = CTRL_REG[2:2];
  assign pwm1_en = CTRL_REG[3:3];
  assign pwm_dt_en = CTRL_REG[4:4];
  assign pwm0_inv = CTRL_REG[5:5];
  assign pwm1_inv = CTRL_REG[6:6];
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CTRL_REG <= 0;
    else if (apb_we && (PADDR[15:0] == CTRL_REG_OFFSET))
      CTRL_REG <= PWDATA[6:0];

  reg [2:0] CFG_REG;
  assign tmr_cfg = CFG_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CFG_REG <= 0;
    else if (apb_we && (PADDR[15:0] == CFG_REG_OFFSET))
      CFG_REG <= PWDATA[2:0];

  reg [11:0] PWM0CFG_REG;
  assign pwm0_cfg = PWM0CFG_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWM0CFG_REG <= 0;
    else if (apb_we && (PADDR[15:0] == PWM0CFG_REG_OFFSET))
      PWM0CFG_REG <= PWDATA[11:0];

  reg [15:0] PWM1CFG_REG;
  assign pwm1_cfg = PWM1CFG_REG[11:0];
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWM1CFG_REG <= 0;
    else if (apb_we && (PADDR[15:0] == PWM1CFG_REG_OFFSET))
      PWM1CFG_REG <= PWDATA[15:0];

  reg [7:0] PWMDT_REG;
  assign pwm_dt = PWMDT_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWMDT_REG <= 0;
    else if (apb_we && (PADDR[15:0] == PWMDT_REG_OFFSET))
      PWMDT_REG <= PWDATA[7:0];

  reg [15:0] PWMFC_REG;
  assign pwm_fault_clr = PWMFC_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWMFC_REG <= 0;
    else if (apb_we && (PADDR[15:0] == PWMFC_REG_OFFSET))
      PWMFC_REG <= PWDATA[15:0];

  localparam GCLK_REG_OFFSET = 16'hFF10;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) GCLK_REG <= 0;
    else if (apb_we && (PADDR[15:0] == GCLK_REG_OFFSET))
      GCLK_REG <= PWDATA[0:0];

  reg [2:0] IM_REG;
  reg [2:0] IC_REG;
  reg [2:0] RIS_REG;

  wire [2:0] MIS_REG = RIS_REG & IM_REG;

  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) IM_REG <= 0;
    else if (apb_we && (PADDR[15:0] == IM_REG_OFFSET))
      IM_REG <= PWDATA[2:0];

  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) IC_REG <= 3'b0;
    else if (apb_we && (PADDR[15:0] == IC_REG_OFFSET))
      IC_REG <= PWDATA[2:0];
    else
      IC_REG <= 3'd0;

  wire [0:0] TO = timeout_flag;
  wire [0:0] MX = matchx_flag;
  wire [0:0] MY = matchy_flag;

  integer _i_;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn)
      RIS_REG <= 0;
    else begin
      for (_i_ = 0; _i_ < 1; _i_ = _i_ + 1) begin
        if (IC_REG[_i_])
          RIS_REG[_i_] <= 1'b0;
        else if (TO[_i_] == 1'b1)
          RIS_REG[_i_] <= 1'b1;
      end

      for (_i_ = 1; _i_ < 2; _i_ = _i_ + 1) begin
        if (IC_REG[_i_])
          RIS_REG[_i_] <= 1'b0;
        else if (MX[_i_-1] == 1'b1)
          RIS_REG[_i_] <= 1'b1;
      end

      for (_i_ = 2; _i_ < 3; _i_ = _i_ + 1) begin
        if (IC_REG[_i_])
          RIS_REG[_i_] <= 1'b0;
        else if (MY[_i_-2] == 1'b1)
          RIS_REG[_i_] <= 1'b1;
      end
    end

  assign IRQ = |MIS_REG;

  EF_TMR32 #(
      .PRW(PRW)
  ) instance_to_wrap (
      .clk(clk),
      .rst_n(rst_n),
      .tmr_en(tmr_en),
      .tmr_start(tmr_start),
      .pwm0_en(pwm0_en),
      .pwm1_en(pwm1_en),
      .tmr_reload(tmr_reload),
      .cmpx(cmpx),
      .cmpy(cmpy),
      .prescaler(prescaler),
      .tmr_cfg(tmr_cfg),
      .pwm0_cfg(pwm0_cfg),
      .pwm1_cfg(pwm1_cfg),
      .pwm0_inv(pwm0_inv),
      .pwm1_inv(pwm1_inv),
      .pwm_dt(pwm_dt),
      .pwm_fault_clr(pwm_fault_clr),
      .pwm_dt_en(pwm_dt_en),
      .tmr(tmr),
      .matchx_flag(matchx_flag),
      .matchy_flag(matchy_flag),
      .timeout_flag(timeout_flag),
      .pwm0(pwm0),
      .pwm1(pwm1),
      .pwm_fault(pwm_fault)
  );

  assign PRDATA =
			(PADDR[15:0] == TMR_REG_OFFSET)      ? TMR_WIRE :
			(PADDR[15:0] == RELOAD_REG_OFFSET)   ? RELOAD_REG :
			(PADDR[15:0] == PR_REG_OFFSET)       ? PR_REG :
			(PADDR[15:0] == CMPX_REG_OFFSET)     ? CMPX_REG :
			(PADDR[15:0] == CMPY_REG_OFFSET)     ? CMPY_REG :
			(PADDR[15:0] == CTRL_REG_OFFSET)     ? CTRL_REG :
			(PADDR[15:0] == CFG_REG_OFFSET)      ? CFG_REG :
			(PADDR[15:0] == PWM0CFG_REG_OFFSET)  ? PWM0CFG_REG :
			(PADDR[15:0] == PWM1CFG_REG_OFFSET)  ? PWM1CFG_REG :
			(PADDR[15:0] == PWMDT_REG_OFFSET)    ? PWMDT_REG :
			(PADDR[15:0] == PWMFC_REG_OFFSET)    ? PWMFC_REG :
			(PADDR[15:0] == IM_REG_OFFSET)       ? IM_REG :
			(PADDR[15:0] == MIS_REG_OFFSET)      ? MIS_REG :
			(PADDR[15:0] == RIS_REG_OFFSET)      ? RIS_REG :
			(PADDR[15:0] == GCLK_REG_OFFSET)     ? GCLK_REG :
			32'hDEADBEEF;

  assign PREADY = 1'b1;

